            if(viewId === 'warehouse-heatmap') { initWarehouseHeatmap(); }
            if(viewId === 'expiry-management') { refreshExpiryReport(); }
            if(viewId === 'user-management') { loadUserList(); }
            if(viewId === 'wave-picking') { loadWavesFromFirebase(); }
