        window.warehousesData = [];

        window.loadWarehouses = async function() {
            try {
                var snapshot = await window.getDocs(window.collection(window.db, 'warehouses'));
                window.warehousesData = [];
                snapshot.forEach(function(doc) {
                    window.warehousesData.push({ id: doc.id, ...doc.data() });
                });

                if (window.warehousesData.length === 0) {
                    await initDefaultWarehouses();
                }

                updateWarehouseDropdown();

            } catch(e) {
                console.error('載入倉庫資料失敗:', e);
                window.warehousesData = window.DEFAULT_WAREHOUSES.map(function(w, i) {
                    return { id: 'default-' + i, ...w };
                });
                updateWarehouseDropdown();
            }
        };

        async function initDefaultWarehouses() {
            for (var w of window.DEFAULT_WAREHOUSES) {
                try {
                    await window.addDoc(window.collection(window.db, 'warehouses'), {
                        ...w,
                        createdAt: new Date().toISOString()
                    });
                } catch(e) {
                    console.error('初始化倉庫失敗:', e);
                }
            }
            var snapshot = await window.getDocs(window.collection(window.db, 'warehouses'));
            window.warehousesData = [];
            snapshot.forEach(function(doc) {
                window.warehousesData.push({ id: doc.id, ...doc.data() });
            });
        }

        window.updateWarehouseDropdown = function() {
            var cwGroup = document.getElementById('optgroup-cw');
            var bfGroup = document.getElementById('optgroup-bf');

            if (!cwGroup || !bfGroup) return;

            cwGroup.innerHTML = '';
            bfGroup.innerHTML = '';

            var cwWarehouses = window.warehousesData.filter(function(w) {
                return w.company === '崇文' && w.active !== false;
            }).sort(function(a, b) { return (a.sortOrder || 99) - (b.sortOrder || 99); });

            var bfWarehouses = window.warehousesData.filter(function(w) {
                return w.company === '八方' && w.active !== false;
            }).sort(function(a, b) { return (a.sortOrder || 99) - (b.sortOrder || 99); });

            cwWarehouses.forEach(function(w) {
                var opt = document.createElement('option');
                opt.value = w.code;
                var icon = w.icon === 'store' ? '🏪' : '🏢';
                opt.textContent = icon + ' 崇文_' + w.name;
                cwGroup.appendChild(opt);
            });

            bfWarehouses.forEach(function(w) {
                var opt = document.createElement('option');
                opt.value = w.code;
                var icon = w.icon === 'store' ? '🏪' : '🏢';
                opt.textContent = icon + ' 八方_' + w.name;
                bfGroup.appendChild(opt);
            });
        };

        window.isExternalWarehouse = function(warehouseId) {
            if (!warehouseId) return false;
            if (warehouseId.startsWith('MAIN')) return false;
            if (warehouseId === 'MANAGE') return false;
            return true;
        };

        window.getWarehouseDisplayName = function(warehouseId) {
            if (!warehouseId) return '';

            if (window.VIRTUAL_WAREHOUSES[warehouseId]) {
                return window.VIRTUAL_WAREHOUSES[warehouseId].name;
            }

            var wh = window.warehousesData.find(function(w) { return w.code === warehouseId; });
            if (wh) {
                return wh.company + '_' + wh.name;
            }

            return warehouseId;
        };

        window.onWarehouseChange = function() {
            var warehouseId = document.getElementById('in-warehouse').value;

            if (warehouseId === 'MANAGE') {
                document.getElementById('in-warehouse').value = 'MAIN'; // 重置選單
                openWarehouseManager();
                return;
            }

            var isExternal = isExternalWarehouse(warehouseId);

            var locSection = document.getElementById('location-section');
            var extSection = document.getElementById('external-wh-section');

            if (locSection) locSection.style.display = isExternal ? 'none' : 'flex';
            if (extSection) extSection.style.display = isExternal ? 'flex' : 'none';

            if (isExternal) {
                var displayName = getWarehouseDisplayName(warehouseId);
                var titleEl = document.getElementById('inbound-wh-title');
                if (titleEl) {
                    titleEl.innerHTML = '<span class="bg-cyan-500 text-white px-2 py-1 rounded mr-2">2</span><i class="fa-solid fa-building mr-2 text-cyan-400"></i>' + displayName + ' 入庫';
                }
            }

            updateLivePreview();
        };

        window.onInboundTypeChange = function() {
            var select = document.getElementById('in-type-select');
            if (!select) return;
            var mode = select.value;
            document.getElementById('in-category').value = mode;
            updateLivePreview();
        };

        window.setInboundMode = function(mode) {
            const elem = document.getElementById('in-category');
            if (elem) elem.value = mode;

            ['raw', 'fg', 'wip', 'ret'].forEach(m => {
                const btn = document.getElementById('btn-mode-' + m);
                if (btn) {
                    btn.classList.remove('bg-blue-600', 'bg-purple-600', 'bg-orange-600', 'bg-cyan-600');
                    btn.classList.add('bg-slate-700');
                }
            });

            const colors = {
                'raw': 'bg-blue-600',
                'fg': 'bg-purple-600',
                'wip': 'bg-orange-600',
                'ret': 'bg-cyan-600'
            };

            const activeBtn = document.getElementById('btn-mode-' + mode.toLowerCase());
            if (activeBtn) {
                activeBtn.classList.remove('bg-slate-700');
                activeBtn.classList.add(colors[mode.toLowerCase()] || 'bg-blue-600');
            }

            updateLivePreview();
        };

        window.generateSheetId = function() {
            const date = new Date();
            const year = date.getFullYear().toString().slice(-2);
            const month = (date.getMonth() + 1).toString().padStart(2, '0');
            const day = date.getDate().toString().padStart(2, '0');
            const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
            return 'PRE-' + year + month + day + '-' + random;
        };

        window.autoFillBarcode = function() {
            const sheetInput = document.getElementById('in-sheet-id');

            if (sheetInput && !sheetInput.value) {
                sheetInput.value = window.generateSheetId();
                alert('✅ 已生成插單編號：' + sheetInput.value + '\n\n請將此編號列印貼在棧板上');
            } else if (sheetInput && sheetInput.value) {
                alert('⚠️ 插單編號已存在：' + sheetInput.value);
            }
        };

        // ===== 簡化版板號移動功能 =====

        window.selectedPallet = null;
        window.currentFilter = '';

        window.renderPalletList = function() {
            var container = document.getElementById('pallet-list');
            if (!container) return;

            var inventory = window.currentInventory ? window.currentInventory() : [];
            var filtered = window.currentFilter
                ? inventory.filter(function(item) { return item.productName === window.currentFilter; })
                : inventory;

            if (filtered.length === 0) {
                container.innerHTML = '<div class="text-center text-slate-400 py-8">無儲位資料</div>';
                return;
            }

            var zones = { 'I-A': [], 'I-B': [], 'J-C': [], 'J-D': [] };
            filtered.forEach(function(item) {
                var parsed = parseLocationId(item.locationId);
                if (parsed && zones[parsed.zone]) {
                    zones[parsed.zone].push(item);
                }
            });

            var zoneNames = { 'I-A': 'A區', 'I-B': 'B區', 'J-C': 'C區', 'J-D': 'D區' };
            var html = '';

            for (var zoneKey in zones) {
                var items = zones[zoneKey];
                if (items.length === 0 && window.currentFilter) continue;

                html += '<div class="mb-3 border border-slate-600 rounded">';
                html += '<div class="bg-slate-800 px-3 py-2 font-bold text-white">' + zoneNames[zoneKey] + '</div>';

                if (items.length === 0) {
                    html += '<div class="p-3 text-slate-500 text-sm">此區無儲位</div>';
                } else {
                    items.forEach(function(item) {
                        var bg = 'bg-blue-900/30 border-blue-500';
                        if (item.category === 'FG') bg = 'bg-green-900/30 border-green-500';
                        if (item.category === 'WIP') bg = 'bg-yellow-900/30 border-yellow-500';

                        html += '<div class="' + bg + ' border m-2 p-2 rounded cursor-pointer hover:bg-opacity-70" ';
                        html += 'onclick="selectPallet(\'' + item.id + '\', \'' + item.locationId + '\', \'' + item.productName + '\', ' + (item.quantity || 0) + ')">';
                        html += '<div class="flex justify-between items-start">';
                        html += '<div><div class="text-white font-bold">' + item.locationId + '</div>';
                        html += '<div class="text-slate-300 text-sm">' + item.productName + '</div></div>';
                        html += '<div class="text-white font-bold text-lg">' + (item.quantity || 0) + ' 件</div>';
                        html += '</div>';
                        html += '<div class="text-xs text-slate-400 mt-1">板號: ' + item.palletId + '</div>';
                        html += '</div>';
                    });
                }
                html += '</div>';
            }

            container.innerHTML = html;
        };

        window.selectPallet = function(id, location, product, quantity) {
            window.selectedPallet = { id: id, location: location, product: product, quantity: quantity };

            var panel = document.getElementById('operation-panel');
            if (!panel) return;

            var inventory = window.currentInventory ? window.currentInventory() : [];
            var sameProduct = inventory.filter(function(item) {
                return item.productName === product && item.id !== id;
            });

            var html = '<div class="space-y-3">';
            html += '<div class="bg-slate-900 border border-slate-700 rounded p-3">';
            html += '<div class="text-xs text-slate-400 mb-2">已選擇：</div>';
            html += '<div class="text-white font-bold">' + location + '</div>';
            html += '<div class="text-slate-300">' + product + '</div>';
            html += '<div class="text-white font-bold text-lg">' + quantity + ' 件</div>';
            html += '</div>';

            html += '<div><div class="text-white font-bold text-sm mb-2">請選擇操作：</div>';
            html += '<button onclick="showMoveOptions()" class="w-full p-3 bg-emerald-700 text-white rounded mb-2 hover:bg-emerald-600">';
            html += '<i class="fa-solid fa-arrow-right mr-2"></i>移動到其他儲位</button>';

            if (sameProduct.length > 0) {
                html += '<button onclick="showMergeOptions()" class="w-full p-3 bg-yellow-700 text-white rounded hover:bg-yellow-600">';
                html += '<i class="fa-solid fa-layer-group mr-2"></i>合併（找到 ' + sameProduct.length + ' 個相同品名）</button>';
            }
            html += '</div></div>';

            panel.innerHTML = html;
        };

        window.showMoveOptions = function() {
            var panel = document.getElementById('operation-panel');
            if (!panel) return;

            var html = '<div class="space-y-2">';
            html += '<button onclick="selectPallet(null)" class="text-sm text-blue-400 hover:text-blue-300">';
            html += '<i class="fa-solid fa-arrow-left mr-1"></i>返回</button>';
            html += '<div class="text-white font-bold mb-2">輸入目標儲位：</div>';
            html += '<input type="text" id="target-location" class="w-full p-2 bg-slate-800 text-white rounded border border-slate-600" ';
            html += 'placeholder="例如: I-A-05-2F">';
            html += '<button onclick="executeMove()" class="w-full p-3 bg-blue-600 text-white rounded hover:bg-blue-500 mt-3">';
            html += '確認移動</button>';
            html += '</div>';

            panel.innerHTML = html;
        };

        window.showMergeOptions = function() {
            var panel = document.getElementById('operation-panel');
            if (!panel) return;

            var source = window.selectedPallet;
            var inventory = window.currentInventory ? window.currentInventory() : [];
            var targets = inventory.filter(function(item) {
                return item.productName === source.product && item.id !== source.id;
            });

            var html = '<div class="space-y-2">';
            html += '<button onclick="selectPallet(null)" class="text-sm text-blue-400 hover:text-blue-300">';
            html += '<i class="fa-solid fa-arrow-left mr-1"></i>返回</button>';
            html += '<div class="text-white font-bold mb-2">選擇合併目標：</div>';

            targets.forEach(function(target) {
                html += '<div class="p-2 bg-slate-800 border border-slate-600 rounded cursor-pointer hover:border-yellow-500" ';
                html += 'onclick="executeMerge(\'' + target.id + '\', ' + (target.quantity || 0) + ')">';
                html += '<div class="flex justify-between">';
                html += '<div class="text-white">' + target.locationId + '</div>';
                html += '<div class="text-white font-bold">' + (target.quantity || 0) + ' 件</div>';
                html += '</div>';
                html += '<div class="text-xs text-green-400 mt-1">合併後: ' + (source.quantity + (target.quantity || 0)) + ' 件</div>';
                html += '</div>';
            });

            html += '</div>';
            panel.innerHTML = html;
        };

        window.executeMove = async function() {
            var source = window.selectedPallet;
            var targetLoc = document.getElementById('target-location');
            if (!source || !targetLoc || !targetLoc.value) {
                alert('請輸入目標儲位');
                return;
            }

            var newLoc = targetLoc.value.trim();
            if (!confirm('確定將 ' + source.location + ' 移動到 ' + newLoc + '？')) return;

            try {
                await window.movePalletTx(window.doc(window.db, "pallets", source.id), newLoc);
                alert('✅ 移動成功！');
                window.selectedPallet = null;
                renderPalletList();
                document.getElementById('operation-panel').innerHTML = '<div class="text-center text-slate-400 py-8">請選擇棧板</div>';
            } catch (err) {
                console.error(err);
                alert('❌ 移動失敗: ' + err.message);
            }
        };

        window.executeMerge = async function(targetId, targetQty) {
            var source = window.selectedPallet;
            if (!source) return;

            var totalQty = source.quantity + targetQty;
            if (!confirm('確定合併？\n合併後總數: ' + totalQty + ' 件')) return;

            try {
                var result = await window.mergePalletsTx(
                    window.doc(window.db, "pallets", source.id),
                    window.doc(window.db, "pallets", targetId)
                );
                if (result.total !== totalQty) {
                    alert('ℹ️ 庫存在您操作期間有變動，實際合併後數量為 ' + result.total + ' 件');
                }

                alert('✅ 合併成功！');
                window.selectedPallet = null;
                renderPalletList();
                document.getElementById('operation-panel').innerHTML = '<div class="text-center text-slate-400 py-8">請選擇棧板</div>';
            } catch (err) {
                console.error(err);
                alert('❌ 合併失敗: ' + err.message);
            }
        };

        window.updateProductFilter = function() {
            var select = document.getElementById('product-filter');
            if (!select) return;

            var inventory = window.currentInventory ? window.currentInventory() : [];
            var products = {};
            inventory.forEach(function(item) {
                if (item.productName) products[item.productName] = true;
            });

            var html = '<option value="">-- 全部顯示 --</option>';
            Object.keys(products).sort().forEach(function(name) {
                html += '<option value="' + name + '">' + name + '</option>';
            });
            select.innerHTML = html;
        };

        window.filterByProduct = function() {
            var select = document.getElementById('product-filter');
            window.currentFilter = select ? select.value : '';
            renderPalletList();
        };

        // ===== 智能調度系統 v4 =====

        window.dispatchTasks = [];
        window.selectedProduct = null;
        window.analysisData = null;

        window.analyzeDispersion = function() {
            var inventory = window.currentInventory ? window.currentInventory() : [];

            var productGroups = {};
            inventory.forEach(function(item) {
                var name = item.productName;
                if (!productGroups[name]) {
                    productGroups[name] = [];
                }
                productGroups[name].push(item);
            });

            var analysis = [];
            for (var name in productGroups) {
                var items = productGroups[name];

                var lanes = {};
                var totalQty = 0;
                items.forEach(function(item) {
                    var parsed = parseLocationId(item.locationId);
                    var lane = parsed ? parsed.laneKey : '';
                    if (!lane) return;
                    if (!lanes[lane]) {
                        lanes[lane] = { qty: 0, count: 0 };
                    }
                    lanes[lane].qty += (item.quantity || 0);
                    lanes[lane].count++;
                    totalQty += (item.quantity || 0);
                });

                var laneList = Object.keys(lanes);
                var laneCount = laneList.length;
                var isolatedCount = 0;  // 孤立群組數（只有1個儲位的群組）
                var groupedCount = 0;   // 集中群組數（有2+個儲位的群組）

                laneList.forEach(function(lane) {
                    if (lanes[lane].count < 2) {
                        isolatedCount++;
                    } else {
                        groupedCount++;
                    }
                });

                if (isolatedCount === 0) continue;

                var avgQty = totalQty / items.length;

                analysis.push({
                    productName: name,
                    locationCount: items.length,
                    laneCount: laneCount,
                    isolatedCount: isolatedCount,  // 孤立群組數
                    groupedCount: groupedCount,    // 集中群組數
                    totalQty: totalQty,
                    avgQty: Math.round(avgQty),
                    lanes: lanes,
                    items: items
                });
            }

            analysis.sort(function(a, b) {
                if (b.isolatedCount !== a.isolatedCount) return b.isolatedCount - a.isolatedCount;
                return b.laneCount - a.laneCount;
            });

            window.analysisData = analysis;
            return analysis;
        };

        window.renderDispersionRanking = function() {
            var container = document.getElementById('dispersion-ranking');
            if (!container) return;

            var analysis = window.analyzeDispersion();

            if (analysis.length === 0) {
                container.innerHTML = '<div class="text-green-400 text-sm p-3"><i class="fa-solid fa-check-circle mr-2"></i>所有品項已集中存放（無孤立儲位），無需調度</div>';
                return;
            }

            var html = '';
            analysis.forEach(function(item, index) {
                var priority = '🔴';
                var bgColor = 'bg-red-900/20 border-red-600';
                if (item.isolatedCount === 2) {
                    priority = '🟡';
                    bgColor = 'bg-yellow-900/20 border-yellow-600';
                } else if (item.isolatedCount === 1) {
                    priority = '🟢';
                    bgColor = 'bg-green-900/20 border-green-600';
                }

                html += '<div class="' + bgColor + ' border rounded p-3 mb-2 cursor-pointer hover:bg-opacity-40" ';
                html += 'onclick="selectProductForDispatch(\'' + item.productName + '\')">';
                html += '<div class="flex justify-between items-start mb-1">';
                html += '<div class="text-white font-bold">' + priority + ' ' + item.productName + '</div>';
                html += '<div class="text-xs text-slate-400">#' + (index + 1) + '</div>';
                html += '</div>';
                html += '<div class="text-sm text-slate-300"><span class="text-red-400 font-bold">' + item.isolatedCount + '</span> 個孤立儲位需調度</div>';
                html += '<div class="text-xs text-slate-500">' + item.laneCount + ' 巷道 / ' + item.locationCount + ' 儲位</div>';
                html += '<div class="text-sm text-slate-300 mt-1">總計 <span class="text-white font-bold">' + item.totalQty + '</span> 件</div>';
                html += '</div>';
            });

            container.innerHTML = html;
        };

        window.selectProductForDispatch = function(productName) {
            window.selectedProduct = productName;

            var data = window.analysisData.find(function(item) {
                return item.productName === productName;
            });

            if (!data) return;

            renderProductStats(data);

            var suggestion = generateSmartSuggestion(data);

            renderVisualMap(data, suggestion);
        };

        window.renderProductStats = function(data) {
            var container = document.getElementById('product-stats');
            if (!container) return;

            var distribution = {};
            data.items.forEach(function(item) {
                var parsed = parseLocationId(item.locationId);
                var zone = parsed ? parsed.zoneChar : '?'; // A, B, C, D
                if (!distribution[zone]) distribution[zone] = 0;
                distribution[zone]++;
            });

            var distText = '';
            for (var zone in distribution) {
                distText += zone + '區:' + distribution[zone] + ' ';
            }

            var html = '<div class="bg-slate-800 border border-slate-600 rounded p-3">';
            html += '<div class="text-white font-bold mb-2">📊 ' + data.productName + ' 統計</div>';
            html += '<div class="text-sm text-slate-300 space-y-1">';
            html += '<div>• 總數量: <span class="text-white font-bold">' + data.totalQty + '</span> 件</div>';
            html += '<div>• 儲位數: <span class="text-yellow-400 font-bold">' + data.locationCount + '</span> 個</div>';
            html += '<div>• 平均: <span class="text-white font-bold">' + data.avgQty + '</span> 件/位</div>';
            html += '<div>• 分佈: <span class="text-blue-400">' + distText + '</span></div>';
            html += '</div></div>';

            container.innerHTML = html;
        };

        window.generateSmartSuggestion = function(data) {
            var inventory = window.currentInventory ? window.currentInventory() : [];

            // ===== 建立群組：同一巷道的儲位歸為一組 =====
            var groups = {};  // { 'I-A01': { qty: 500, count: 3, items: [...] }, ... }

            data.items.forEach(function(item) {
                var parsed = parseLocationId(item.locationId);
                var lane = parsed ? parsed.laneKey : ''; // 如 I-A01
                if (!lane) return;
                if (!groups[lane]) {
                    groups[lane] = { qty: 0, count: 0, items: [] };
                }
                groups[lane].qty += (item.quantity || 0);
                groups[lane].count++;
                groups[lane].items.push(item);
            });

            var groupList = Object.keys(groups).map(function(lane) {
                return {
                    lane: lane,
                    qty: groups[lane].qty,
                    count: groups[lane].count,  // 群組內儲位數
                    items: groups[lane].items
                };
            }).sort(function(a, b) {
                if (b.qty !== a.qty) return b.qty - a.qty;
                return b.count - a.count;
            });

            // ===== 分類群組 =====
            var keepGroups = [];    // 保留的群組（集中存放）
            var moveGroups = [];    // 需調度的群組（孤立儲位）

            groupList.forEach(function(g) {
                if (g.count >= 2) {
                    keepGroups.push(g);
                } else {
                    moveGroups.push(g);
                }
            });

            if (moveGroups.length === 0) {
                return {
                    keep: data.items,
                    move: [],
                    suggestions: [],
                    freedSpaces: 0,
                    targetLane: groupList[0] ? groupList[0].lane : null,
                    heatMap: groupList,
                    groups: { keep: keepGroups, move: moveGroups },
                    message: '✅ 所有品項已集中存放（無孤立儲位），無需調度'
                };
            }

            if (keepGroups.length === 0) {
                var targetGroup = groupList[0];
                keepGroups = [targetGroup];
                moveGroups = groupList.slice(1);

                if (moveGroups.length === 0) {
                    return {
                        keep: data.items,
                        move: [],
                        suggestions: [],
                        freedSpaces: 0,
                        targetLane: targetGroup.lane,
                        heatMap: groupList,
                        groups: { keep: keepGroups, move: moveGroups },
                        message: '✅ 僅有單一儲位，無需調度'
                    };
                }
            }

            // ===== 目標巷道 = 最大群組（數量最多） =====
            var targetGroup = keepGroups[0];
            var targetLane = targetGroup.lane;

            var keepItems = [];
            keepGroups.forEach(function(g) {
                keepItems = keepItems.concat(g.items);
            });

            var moveItems = [];
            moveGroups.forEach(function(g) {
                moveItems = moveItems.concat(g.items);
            });

            // ===== 計算目標巷道的可用空位 =====
            function getLaneEmptySlots(lanePrefix) {
                var laneItems = inventory.filter(function(item) {
                    return item.locationId && item.locationId.startsWith(lanePrefix);
                });
                // 各層依 RACK_CONFIG 的混合板型使用率估算還能放幾板（以散板計，3F 只放整板）
                var levelCounts = { '3F': {}, '2F': {}, '1F': {} };
                laneItems.forEach(function(item) {
                    var parsed = parseLocationId(item.locationId);
                    var level = parsed ? parsed.level : '';
                    if (levelCounts[level]) window.addPalletToCounts(levelCounts[level], item);
                });
                var emptySlots = [];
                ['3F', '2F', '1F'].forEach(function(level) {
                    var type = level === '3F' ? 'full' : 'scattered';
                    var n = window.levelRemaining(levelCounts[level], level, type);
                    for (var j = 0; j < n; j++) emptySlots.push(lanePrefix + '-' + level);
                });
                return emptySlots;
            }

            // ===== 生成調度建議 =====
            var suggestions = [];
            var emptySlots = getLaneEmptySlots(targetLane);
            var slotIndex = 0;

            moveItems.forEach(function(moveItem) {
                var parsed = parseLocationId(moveItem.locationId);
                var fromLane = parsed ? parsed.laneKey : '';
                var fromGroup = groups[fromLane];

                if (slotIndex < emptySlots.length) {
                    suggestions.push({
                        from: moveItem,
                        fromLane: fromLane,
                        fromGroupSize: fromGroup ? fromGroup.count : 1,
                        toLocation: emptySlots[slotIndex],
                        toLane: targetLane,
                        toGroupSize: targetGroup.count,
                        quantity: moveItem.quantity || 0,
                        reason: '孤立(' + (fromGroup ? fromGroup.count : 1) + '儲位) → 集中(' + targetGroup.count + '儲位)'
                    });
                    slotIndex++;
                } else {
                    suggestions.push({
                        from: moveItem,
                        fromLane: fromLane,
                        toLocation: '無可用空位',
                        toLane: targetLane + ' (已滿)',
                        quantity: moveItem.quantity || 0,
                        noSpace: true,
                        reason: '目標巷道已滿'
                    });
                }
            });

            return {
                keep: keepItems,
                move: moveItems,
                suggestions: suggestions,
                freedSpaces: suggestions.filter(function(s) { return !s.noSpace; }).length,
                targetLane: targetLane,
                targetHeat: targetGroup.qty,
                targetGroupSize: targetGroup.count,
                heatMap: groupList,
                groups: { keep: keepGroups, move: moveGroups }
            };
        };

        window.renderVisualMap = function(data, suggestion) {
            var container = document.getElementById('visual-map');
            if (!container) return;

            var html = '<div class="space-y-3">';

            if (suggestion.message) {
                html += '<div class="bg-green-900/30 border border-green-600 rounded-lg p-6 text-center">';
                html += '<i class="fa-solid fa-check-circle text-4xl text-green-400 mb-3"></i>';
                html += '<div class="text-green-300 font-bold text-lg">' + suggestion.message + '</div>';
                html += '<div class="text-slate-400 text-sm mt-2">目標巷道：<span class="text-white font-bold">' + (suggestion.targetLane || '-') + '</span></div>';
                html += '</div>';
                html += '</div>';
                container.innerHTML = html;
                window.currentSuggestion = suggestion;
                return;
            }

            // ===== 群組熱力圖顯示 =====
            html += '<div class="bg-slate-800/50 border border-slate-600 rounded-lg p-3 mb-3">';
            html += '<div class="text-white font-bold mb-2"><i class="fa-solid fa-layer-group text-orange-400 mr-2"></i>巷道群組分析</div>';
            html += '<div class="flex flex-wrap gap-2">';

            if (suggestion.heatMap) {
                var maxHeat = suggestion.heatMap[0] ? suggestion.heatMap[0].qty : 1;
                suggestion.heatMap.forEach(function(h, idx) {
                    var heatPercent = Math.round((h.qty / maxHeat) * 100);
                    var isIsolated = h.count < 2;  // 孤立群組
                    var isTarget = suggestion.groups && suggestion.groups.keep.length > 0 && suggestion.groups.keep[0].lane === h.lane;
                    var borderClass = isTarget ? 'ring-2 ring-yellow-400' : (isIsolated ? 'ring-1 ring-red-400' : '');
                    var bgClass = isIsolated ? 'bg-red-900/50' : 'bg-slate-700';

                    html += '<div class="relative group">';
                    html += '<div class="' + borderClass + ' ' + bgClass + ' rounded p-2 text-center min-w-[90px]">';
                    html += '<div class="text-xs text-slate-400 mb-1">' + h.lane + '</div>';
                    html += '<div class="h-2 bg-slate-600 rounded overflow-hidden mb-1">';
                    html += '<div class="h-full ' + (isIsolated ? 'bg-red-500' : 'bg-green-500') + '" style="width:' + heatPercent + '%"></div>';
                    html += '</div>';
                    html += '<div class="text-white font-bold text-sm">' + h.qty + '件</div>';
                    html += '<div class="text-xs ' + (isIsolated ? 'text-red-400' : 'text-green-400') + '">' + h.count + '儲位</div>';
                    if (isTarget) {
                        html += '<div class="text-[10px] text-yellow-400 mt-1">🎯 目標群組</div>';
                    } else if (isIsolated) {
                        html += '<div class="text-[10px] text-red-400 mt-1">⚠️ 孤立</div>';
                    } else {
                        html += '<div class="text-[10px] text-green-400 mt-1">✅ 集中</div>';
                    }
                    html += '</div>';
                    html += '</div>';
                });
            }
            html += '</div>';
            html += '<div class="text-xs text-slate-500 mt-2"><i class="fa-solid fa-info-circle mr-1"></i>群組規則：≥2儲位=集中(綠)、1儲位=孤立(紅)需調度</div>';
            html += '</div>';

            html += '<div class="flex justify-between items-center mb-3">';
            html += '<div class="text-white font-bold">📍 調度方案 <span class="text-sm text-slate-400">(目標: ' + suggestion.targetLane + ' / ' + (suggestion.targetGroupSize || 0) + '儲位)</span></div>';
            html += '<div class="flex items-center gap-3">';
            html += '<label class="flex items-center gap-2 text-sm text-slate-300 cursor-pointer">';
            html += '<input type="checkbox" id="select-all-tasks" checked onchange="toggleAllTasks(this.checked)" class="w-4 h-4 rounded">';
            html += '<span>全選</span>';
            html += '</label>';
            html += '<span id="selected-count" class="text-xs text-blue-400">已選 ' + suggestion.suggestions.filter(function(s){return !s.noSpace}).length + ' 項</span>';
            html += '</div>';
            html += '</div>';

            html += '<div class="mb-3 bg-green-900/20 border border-green-600/50 rounded p-3">';
            html += '<div class="text-green-400 text-sm font-bold mb-2">✅ 集中群組保留（' + suggestion.keep.length + '儲位）</div>';
            html += '<div class="flex flex-wrap gap-2">';
            suggestion.keep.forEach(function(item) {
                html += '<div class="bg-green-900/50 border border-green-600 rounded px-2 py-1 text-sm">';
                html += '<span class="text-white font-bold">' + item.locationId + '</span>';
                html += '<span class="text-green-300 ml-2">' + (item.quantity || 0) + '件</span>';
                html += '</div>';
            });
            html += '</div></div>';

            html += '<div class="mb-3">';
            html += '<div class="text-red-400 text-sm font-bold mb-2">⚠️ 孤立儲位調度（' + suggestion.suggestions.length + '項）→ 集中群組</div>';
            html += '<div class="space-y-2" id="task-list">';

            suggestion.suggestions.forEach(function(sug, index) {
                var isDisabled = sug.noSpace;
                var borderColor = isDisabled ? 'border-slate-600' : 'border-red-600/50';
                var bgColor = isDisabled ? 'bg-slate-800/30' : 'bg-red-900/20';
                var opacity = isDisabled ? 'opacity-50' : '';

                html += '<div class="' + bgColor + ' border ' + borderColor + ' rounded p-3 ' + opacity + '" data-task-index="' + index + '">';
                html += '<div class="flex items-center gap-3">';

                if (!isDisabled) {
                    html += '<input type="checkbox" checked class="task-checkbox w-5 h-5 rounded cursor-pointer" data-index="' + index + '" onchange="updateTaskSelection()">';
                } else {
                    html += '<div class="w-5 h-5 rounded bg-red-900/50 flex items-center justify-center"><i class="fa-solid fa-ban text-red-400 text-xs"></i></div>';
                }

                html += '<div class="flex-1 flex items-center justify-between">';
                html += '<div class="flex items-center gap-2">';
                html += '<span class="text-white font-bold">' + sug.from.locationId + '</span>';
                html += '<span class="text-slate-400">(' + sug.quantity + '件)</span>';
                html += '</div>';
                html += '<i class="fa-solid fa-arrow-right text-slate-500"></i>';
                html += '<div class="text-right">';
                if (isDisabled) {
                    html += '<span class="text-red-400">無空位</span>';
                } else {
                    html += '<span class="text-green-400 font-bold">' + sug.toLocation + '</span>';
                }
                html += '</div>';
                html += '</div>';
                html += '</div>';
                html += '</div>';
            });

            html += '</div></div>';

            html += '<div class="bg-blue-900/20 border border-blue-600/50 rounded p-3" id="effect-preview">';
            html += '<div class="text-blue-400 font-bold mb-2">📈 預期效果</div>';
            html += '<div class="text-sm text-slate-300 grid grid-cols-3 gap-2">';
            var validCount = suggestion.suggestions.filter(function(s){return !s.noSpace}).length;
            html += '<div>釋放 <span class="text-yellow-400 font-bold" id="effect-spaces">' + validCount + '</span> 空位</div>';
            html += '<div>減少 <span class="text-green-400 font-bold" id="effect-percent">' + Math.round(validCount / data.locationCount * 100) + '%</span></div>';
            html += '<div>執行 <span class="text-white font-bold" id="effect-tasks">' + validCount + '</span> 次</div>';
            html += '</div></div>';

            html += '<div class="mt-4 flex gap-2">';
            html += '<button onclick="generateDispatchOrder()" class="flex-1 bg-blue-600 hover:bg-blue-500 text-white py-2 px-4 rounded font-bold" id="btn-generate">';
            html += '<i class="fa-solid fa-file-lines mr-2"></i>生成調度單 (<span id="btn-count">' + validCount + '</span>項)';
            html += '</button>';
            html += '<button onclick="cancelDispatch()" class="bg-slate-700 hover:bg-slate-600 text-white py-2 px-4 rounded">';
            html += '取消';
            html += '</button>';
            html += '</div>';

            html += '</div>';

            container.innerHTML = html;

            window.currentSuggestion = suggestion;
            window.currentData = data;
        };

        window.toggleAllTasks = function(checked) {
            var checkboxes = document.querySelectorAll('.task-checkbox');
            checkboxes.forEach(function(cb) {
                cb.checked = checked;
            });
            updateTaskSelection();
        };

        window.updateTaskSelection = function() {
            var checkboxes = document.querySelectorAll('.task-checkbox');
            var checkedCount = 0;
            var total = checkboxes.length;

            checkboxes.forEach(function(cb) {
                if (cb.checked) checkedCount++;
            });

            var countEl = document.getElementById('selected-count');
            if (countEl) countEl.textContent = '已選 ' + checkedCount + ' 項';

            var btnCount = document.getElementById('btn-count');
            if (btnCount) btnCount.textContent = checkedCount;

            var effectSpaces = document.getElementById('effect-spaces');
            if (effectSpaces) effectSpaces.textContent = checkedCount;

            var effectTasks = document.getElementById('effect-tasks');
            if (effectTasks) effectTasks.textContent = checkedCount;

            var effectPercent = document.getElementById('effect-percent');
            if (effectPercent && window.currentData) {
                effectPercent.textContent = Math.round(checkedCount / window.currentData.locationCount * 100) + '%';
            }

            var selectAll = document.getElementById('select-all-tasks');
            if (selectAll) {
                selectAll.checked = checkedCount === total;
                selectAll.indeterminate = checkedCount > 0 && checkedCount < total;
            }

            var btnGenerate = document.getElementById('btn-generate');
            if (btnGenerate) {
                btnGenerate.disabled = checkedCount === 0;
                btnGenerate.className = checkedCount === 0
                    ? 'flex-1 bg-slate-600 text-slate-400 py-2 px-4 rounded font-bold cursor-not-allowed'
                    : 'flex-1 bg-blue-600 hover:bg-blue-500 text-white py-2 px-4 rounded font-bold';
            }
        };

        window.generateDispatchOrder = function() {
            if (!window.currentSuggestion || !window.selectedProduct) {
                alert('請先選擇品名並查看建議');
                return;
            }

            var suggestion = window.currentSuggestion;
            var product = window.selectedProduct;

            var selectedIndices = [];
            var checkboxes = document.querySelectorAll('.task-checkbox');
            checkboxes.forEach(function(cb) {
                if (cb.checked) {
                    selectedIndices.push(parseInt(cb.getAttribute('data-index')));
                }
            });

            if (selectedIndices.length === 0) {
                alert('請至少選擇一項調度任務');
                return;
            }

            var selectedSuggestions = [];
            selectedIndices.forEach(function(idx) {
                var sug = suggestion.suggestions[idx];
                if (sug && !sug.noSpace) {
                    selectedSuggestions.push(sug);
                }
            });

            if (selectedSuggestions.length === 0) {
                alert('沒有可執行的調度任務');
                return;
            }

            var orderNo = window.generateDocNo ? window.generateDocNo('DS') : 'DS-' + new Date().getFullYear() + ('0'+(new Date().getMonth()+1)).slice(-2) + ('0'+new Date().getDate()).slice(-2) + '-001';
            var timestamp = new Date().toLocaleString('zh-TW');

            var tasks = [];
            selectedSuggestions.forEach(function(sug, index) {
                tasks.push({
                    taskNo: index + 1,
                    fromLocation: sug.from.locationId,
                    fromPalletId: sug.from.palletId,
                    toLocation: sug.toLocation,
                    toLane: sug.toLane,
                    quantity: sug.quantity,
                    status: 'pending'
                });
            });

            var previewData = {
                orderNo: orderNo,
                productName: product,
                createdAt: timestamp,
                tasks: tasks,
                totalTasks: tasks.length
            };

            showDispatchPreview(previewData);
        };

        window.showDispatchPreview = function(previewData) {
            var modal = document.getElementById('dispatch-preview-modal');
            if (!modal) {
                modal = document.createElement('div');
                modal.id = 'dispatch-preview-modal';
                modal.className = 'fixed inset-0 bg-black/70 flex items-center justify-center z-50';
                document.body.appendChild(modal);
            }

            var html = '<div class="bg-slate-800 rounded-lg p-6 max-w-3xl w-full mx-4 max-h-[85vh] overflow-y-auto">';

            html += '<div class="flex justify-between items-start mb-4">';
            html += '<div>';
            html += '<h2 class="text-2xl font-bold text-white">📋 調度單預覽</h2>';
            html += '<div class="text-slate-400 text-sm mt-1">請確認無誤後再生成正式調度單</div>';
            html += '</div>';
            html += '<button onclick="closePreviewModal()" class="text-slate-400 hover:text-white text-2xl">&times;</button>';
            html += '</div>';

            html += '<div class="bg-gradient-to-r from-blue-900 to-blue-800 border border-blue-600 rounded-lg p-4 mb-4">';
            html += '<div class="grid grid-cols-3 gap-4 text-sm">';
            html += '<div><div class="text-blue-300 mb-1">調度單編號</div><div class="text-white font-bold">' + previewData.orderNo + '</div></div>';
            html += '<div><div class="text-blue-300 mb-1">品名</div><div class="text-white font-bold">' + previewData.productName + '</div></div>';
            html += '<div><div class="text-blue-300 mb-1">生成時間</div><div class="text-white font-bold">' + previewData.createdAt + '</div></div>';
            html += '</div></div>';

            html += '<div class="mb-4">';
            html += '<div class="flex justify-between items-center mb-3">';
            html += '<h3 class="text-white font-bold">📦 任務清單（共 ' + previewData.totalTasks + ' 項）</h3>';
            html += '<div class="text-xs text-slate-400">💡 提示：可以調整執行順序</div>';
            html += '</div>';

            html += '<div class="space-y-2">';
            previewData.tasks.forEach(function(task, index) {
                html += '<div class="bg-slate-900 border border-slate-700 rounded-lg p-4 hover:border-blue-500 transition-all">';

                html += '<div class="flex justify-between items-start mb-3">';
                html += '<div class="flex items-center gap-3">';
                html += '<div class="bg-blue-900 text-blue-300 px-3 py-1 rounded font-bold text-sm">任務 ' + task.taskNo + '</div>';

                if (index > 0) {
                    html += '<button onclick="moveTaskUp(' + index + ')" class="text-slate-400 hover:text-white text-xs px-2 py-1 bg-slate-800 rounded" title="上移">';
                    html += '<i class="fa-solid fa-arrow-up"></i></button>';
                }
                if (index < previewData.totalTasks - 1) {
                    html += '<button onclick="moveTaskDown(' + index + ')" class="text-slate-400 hover:text-white text-xs px-2 py-1 bg-slate-800 rounded" title="下移">';
                    html += '<i class="fa-solid fa-arrow-down"></i></button>';
                }
                html += '</div>';

                html += '<button onclick="removeTask(' + index + ')" class="text-red-400 hover:text-red-300 text-xs px-2 py-1 bg-slate-800 rounded" title="移除此任務">';
                html += '<i class="fa-solid fa-trash mr-1"></i>移除</button>';
                html += '</div>';

                html += '<div class="grid grid-cols-4 gap-3">';

                html += '<div class="col-span-1">';
                html += '<div class="text-xs text-slate-400 mb-1">📍 來源儲位</div>';
                html += '<div class="text-white font-bold text-sm">' + task.fromLocation + '</div>';
                html += '<div class="text-xs text-slate-500 mt-1">板號：' + task.fromPalletId + '</div>';
                html += '</div>';

                html += '<div class="col-span-1 flex items-center justify-center">';
                html += '<div class="text-slate-500">';
                html += '<i class="fa-solid fa-arrow-right text-2xl"></i>';
                html += '<div class="text-xs mt-1">' + task.quantity + ' 件</div>';
                html += '</div>';
                html += '</div>';

                html += '<div class="col-span-1">';
                html += '<div class="text-xs text-slate-400 mb-1">🎯 目標儲位</div>';
                html += '<div class="text-green-400 font-bold text-sm">' + task.toLocation + '</div>';
                html += '<div class="text-xs text-green-600 mt-1">合併到此</div>';
                html += '</div>';

                html += '<div class="col-span-1">';
                html += '<div class="text-xs text-slate-400 mb-1">⏱️ 預估時間</div>';
                html += '<div class="text-yellow-400 font-bold text-sm">~5 分鐘</div>';
                html += '<div class="text-xs text-slate-500 mt-1">含移動時間</div>';
                html += '</div>';

                html += '</div>';
                html += '</div>';
            });
            html += '</div>';
            html += '</div>';

            html += '<div class="bg-gradient-to-r from-purple-900/30 to-blue-900/30 border border-purple-600/50 rounded-lg p-4 mb-4">';
            html += '<div class="text-purple-300 font-bold mb-2">📊 執行摘要</div>';
            html += '<div class="grid grid-cols-3 gap-4 text-sm">';
            html += '<div>';
            html += '<div class="text-slate-400">總任務數</div>';
            html += '<div class="text-white font-bold text-xl">' + previewData.totalTasks + ' 項</div>';
            html += '</div>';
            html += '<div>';
            html += '<div class="text-slate-400">預估總時長</div>';
            html += '<div class="text-yellow-400 font-bold text-xl">~' + (previewData.totalTasks * 5) + ' 分鐘</div>';
            html += '</div>';
            html += '<div>';
            html += '<div class="text-slate-400">釋放空位</div>';
            html += '<div class="text-green-400 font-bold text-xl">' + previewData.totalTasks + ' 個</div>';
            html += '</div>';
            html += '</div>';
            html += '</div>';

            html += '<div class="bg-blue-900/20 border border-blue-600/50 rounded-lg p-4 mb-4">';
            html += '<div class="text-blue-400 font-bold mb-2">📱 PDA 端執行流程</div>';
            html += '<div class="space-y-2 text-sm text-slate-300">';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">1</div>';
            html += '<div>堆高機司機的 PDA 會收到推送通知</div>';
            html += '</div>';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">2</div>';
            html += '<div>PDA 顯示第一個任務：「請前往 ' + previewData.tasks[0].fromLocation + '」</div>';
            html += '</div>';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">3</div>';
            html += '<div>司機到達後掃描棧板條碼 → <span class="text-green-400 font-bold">嗶！確認正確</span></div>';
            html += '</div>';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">4</div>';
            html += '<div>載貨移動到 ' + previewData.tasks[0].toLocation + '，掃描儲位 → <span class="text-green-400 font-bold">嗶！任務完成</span></div>';
            html += '</div>';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">5</div>';
            html += '<div>自動顯示下一個任務，重複步驟 3-4</div>';
            html += '</div>';
            html += '<div class="flex items-start gap-2">';
            html += '<div class="bg-blue-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-xs flex-shrink-0 mt-0.5">6</div>';
            html += '<div>所有任務完成後，PDA 顯示「🎉 調度單完成！」</div>';
            html += '</div>';
            html += '</div>';
            html += '</div>';

            html += '<div class="flex gap-3">';
            html += '<button onclick="confirmAndGenerate()" class="flex-1 bg-gradient-to-r from-green-600 to-green-500 hover:from-green-500 hover:to-green-400 text-white py-3 px-6 rounded-lg font-bold text-lg shadow-lg">';
            html += '<i class="fa-solid fa-check-circle mr-2"></i>確認無誤，正式生成';
            html += '</button>';
            html += '<button onclick="closePreviewModal()" class="bg-slate-700 hover:bg-slate-600 text-white py-3 px-6 rounded-lg">';
            html += '<i class="fa-solid fa-times mr-2"></i>取消';
            html += '</button>';
            html += '</div>';

            html += '</div>';

            modal.innerHTML = html;
            modal.classList.remove('hidden');

            window.currentPreviewData = previewData;
        };

        window.confirmAndGenerate = async function() {
            if (!window.currentPreviewData) return;

            var previewData = window.currentPreviewData;

            var order = {
                orderNo: previewData.orderNo,
                productName: previewData.productName,
                createdAt: previewData.createdAt,
                tasks: previewData.tasks,
                operations: previewData.tasks.map(function(t, idx) {
                    return {
                        id: 'op-' + idx,
                        type: t.toLane ? '合併' : '移位',
                        from: t.fromLocation,
                        palletId: t.fromPalletId,
                        to: t.toLocation,
                        qty: t.quantity
                    };
                }),
                totalTasks: previewData.tasks.length,
                completedTasks: 0,
                completedOps: [],
                status: 'pending',
                createdBy: window.getOperatorName ? window.getOperatorName() : 'system'
            };

            try {
                await window.addDoc(window.collection(window.db, 'dispatchOrders'), order);
            } catch (err) {
                console.error('存到 Firebase 失敗:', err);
            }

            if (!window.dispatchOrders) window.dispatchOrders = [];
            window.dispatchOrders.push(order);

            closePreviewModal();

            setTimeout(function() {
                alert('✅ 調度單已生成！\n\n編號：' + order.orderNo + '\n任務數：' + order.totalTasks + ' 項\n\n📱 手機版已同步，堆高機手可立即執行');
                showDispatchOrder(order);
            }, 300);
        };

        window.closePreviewModal = function() {
            var modal = document.getElementById('dispatch-preview-modal');
            if (modal) modal.classList.add('hidden');
        };

        window.moveTaskUp = function(index) {
            if (!window.currentPreviewData || index === 0) return;
            var tasks = window.currentPreviewData.tasks;
            var temp = tasks[index];
            tasks[index] = tasks[index - 1];
            tasks[index - 1] = temp;
            tasks.forEach(function(task, i) {
                task.taskNo = i + 1;
            });
            showDispatchPreview(window.currentPreviewData);
        };

        window.moveTaskDown = function(index) {
            if (!window.currentPreviewData || index === window.currentPreviewData.tasks.length - 1) return;
            var tasks = window.currentPreviewData.tasks;
            var temp = tasks[index];
            tasks[index] = tasks[index + 1];
            tasks[index + 1] = temp;
            tasks.forEach(function(task, i) {
                task.taskNo = i + 1;
            });
            showDispatchPreview(window.currentPreviewData);
        };

        window.removeTask = function(index) {
            if (!window.currentPreviewData) return;
            if (!confirm('確定要移除此任務嗎？')) return;
            window.currentPreviewData.tasks.splice(index, 1);
            window.currentPreviewData.totalTasks = window.currentPreviewData.tasks.length;
            window.currentPreviewData.tasks.forEach(function(task, i) {
                task.taskNo = i + 1;
            });
            if (window.currentPreviewData.tasks.length === 0) {
                alert('所有任務已移除');
                closePreviewModal();
                return;
            }
            showDispatchPreview(window.currentPreviewData);
        };

        window.showDispatchOrder = function(order) {
            var modal = document.getElementById('dispatch-order-modal');
            if (!modal) {
                modal = document.createElement('div');
                modal.id = 'dispatch-order-modal';
                modal.className = 'fixed inset-0 bg-black/70 flex items-center justify-center z-50';
                document.body.appendChild(modal);
            }

            var html = '<div class="bg-slate-800 rounded-lg p-6 max-w-2xl w-full mx-4 max-h-[80vh] overflow-y-auto">';
            html += '<div class="flex justify-between items-start mb-4">';
            html += '<div>';
            html += '<h2 class="text-2xl font-bold text-white">📋 調度單 ' + order.orderNo + '</h2>';
            html += '<div class="text-slate-400 text-sm mt-1">品名：' + order.productName + ' | 生成時間：' + order.createdAt + '</div>';
            html += '</div>';
            html += '<button onclick="closeDispatchOrderModal()" class="text-slate-400 hover:text-white text-2xl">&times;</button>';
            html += '</div>';

            html += '<div class="space-y-3 mb-4">';
            order.tasks.forEach(function(task) {
                var statusIcon = '⏱️';
                var statusText = '待執行';
                var statusColor = 'text-yellow-400';

                if (task.status === 'completed') {
                    statusIcon = '✅';
                    statusText = '已完成';
                    statusColor = 'text-green-400';
                }

                html += '<div class="bg-slate-900 border border-slate-700 rounded p-3">';
                html += '<div class="flex justify-between items-start mb-2">';
                html += '<div class="text-white font-bold">任務 ' + task.taskNo + '</div>';
                html += '<div class="' + statusColor + ' text-sm">' + statusIcon + ' ' + statusText + '</div>';
                html += '</div>';
                html += '<div class="grid grid-cols-3 gap-2 text-sm">';
                html += '<div><div class="text-slate-400">從</div><div class="text-white font-bold">' + task.fromLocation + '</div></div>';
                html += '<div class="text-center"><div class="text-slate-400">數量</div><div class="text-yellow-400 font-bold">' + task.quantity + ' 件</div></div>';
                html += '<div class="text-right"><div class="text-slate-400">到</div><div class="text-white font-bold">' + task.toLocation + '</div></div>';
                html += '</div>';
                html += '<div class="text-xs text-slate-500 mt-2">板號：' + task.fromPalletId + '</div>';
                html += '</div>';
            });
            html += '</div>';

            html += '<div class="bg-blue-900/30 border border-blue-600 rounded p-3 mb-4">';
            html += '<div class="text-blue-400 font-bold mb-1">📱 PDA 端操作流程</div>';
            html += '<div class="text-sm text-slate-300 space-y-1">';
            html += '<div>1️⃣ 堆高機司機 PDA 會收到此調度單</div>';
            html += '<div>2️⃣ 司機按順序執行每個任務</div>';
            html += '<div>3️⃣ 到達來源位 → 掃描棧板 (嗶！確認)</div>';
            html += '<div>4️⃣ 到達目標位 → 掃描儲位 (嗶！完成)</div>';
            html += '<div>5️⃣ 系統自動更新完成狀態</div>';
            html += '</div></div>';

            html += '<div class="flex gap-2">';
            html += '<button onclick="alert(\'請使用智能調度中心的列印功能\')" class="flex-1 bg-green-600 hover:bg-green-500 text-white py-2 px-4 rounded">';
            html += '<i class="fa-solid fa-print mr-2"></i>列印調度單</button>';
            html += '<button onclick="closeDispatchOrderModal()" class="bg-slate-700 hover:bg-slate-600 text-white py-2 px-4 rounded">關閉</button>';
            html += '</div>';

            html += '</div>';

            modal.innerHTML = html;
            modal.classList.remove('hidden');
        };

        window.closeDispatchOrderModal = function() {
            var modal = document.getElementById('dispatch-order-modal');
            if (modal) modal.classList.add('hidden');
        };

        window.cancelDispatch = function() {
            window.selectedProduct = null;
            window.currentSuggestion = null;
            var el = document.getElementById('dispatch-detail-panel');
            if (el) {
                el.innerHTML = '<div class="text-center text-slate-500 py-16"><i class="fa-solid fa-hand-pointer text-6xl mb-4 opacity-30"></i><p class="text-lg">請從左側選擇品項</p></div>';
            }
        };

        window.initSmartDispatch = function() {
            console.log('initSmartDispatch 被呼叫 - 自動開始分析');
            startDispatchAnalysis();
        };

        // ========== 調度中心步驟控制（簡化版）==========
        window.currentDispatchStep = 2; // 直接到步驟 2（選擇工單）

        window.goToDispatchStep = function(step) {
            console.log('goToDispatchStep 被呼叫, step =', step);
            document.querySelectorAll('.dispatch-step').forEach(function(el) {
                el.classList.add('hidden');
            });

            var targetStep = document.getElementById('dispatch-step-' + step);
            if (targetStep) targetStep.classList.remove('hidden');

            for (var i = 1; i <= 3; i++) {
                var indicator = document.getElementById('step-' + i + '-indicator');
                if (!indicator) continue;

                if (i < step) {
                    indicator.className = 'flex items-center gap-2 px-4 py-2 rounded-lg bg-emerald-600 text-white';
                    indicator.querySelector('div').className = 'w-7 h-7 rounded-full bg-white text-emerald-600 flex items-center justify-center font-bold';
                } else if (i === step) {
                    indicator.className = 'flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 text-white';
                    indicator.querySelector('div').className = 'w-7 h-7 rounded-full bg-white text-blue-600 flex items-center justify-center font-bold';
                } else {
                    indicator.className = 'flex items-center gap-2 px-4 py-2 rounded-lg bg-slate-700 text-slate-400';
                    indicator.querySelector('div').className = 'w-7 h-7 rounded-full bg-slate-600 text-slate-400 flex items-center justify-center font-bold';
                }
            }

            window.currentDispatchStep = step;
        };

        window.startDispatchAnalysis = function() {
            document.getElementById('analysis-loading').classList.remove('hidden');

            setTimeout(function() {
                refreshDispatchAnalysis();
            }, 500);
        };

        window.refreshDispatchAnalysis = function() {
            console.log('開始調度分析...');
            var pallets = window.currentPallets ? window.currentPallets() : [];
            console.log('取得庫存資料:', pallets ? pallets.length : 0, '筆');

            if (!pallets || pallets.length === 0) {
                document.getElementById('dispatch-orders-container').innerHTML = '<div class="text-slate-500 text-center py-8 bg-slate-900/50 border border-slate-700 rounded-lg"><i class="fa-solid fa-database text-4xl mb-3 opacity-30"></i><p>無庫存資料</p><p class="text-xs mt-2">請先載入庫存資料</p></div>';
                return;
            }

            var productGroups = {};
            var skippedCount = 0;
            pallets.forEach(function(p) {
                if (!p.locationId) { skippedCount++; return; }
                var zone = p.locationId.split('-')[0];
                if (zone !== 'I' && zone !== 'J' && zone !== 'K') { skippedCount++; return; }

                var parsed = parseLocationId(p.locationId);
                var laneKey = parsed ? parsed.laneKey : p.locationId;

                var key = p.productName + '|' + (p.spec || '');
                if (!productGroups[key]) {
                    productGroups[key] = {
                        name: p.productName,
                        spec: p.spec || '',
                        items: [],
                        locations: new Set(),
                        lanes: new Set(),  // 巷道（如 I-A-01）
                        zones: new Set(),  // 儲區（如 I, J, K）
                        totalQty: 0
                    };
                }
                productGroups[key].items.push(p);
                productGroups[key].locations.add(p.locationId);
                productGroups[key].lanes.add(laneKey);
                productGroups[key].zones.add(zone);
                productGroups[key].totalQty += (p.quantity || 0);
            });

            var dispatchItems = [];
            var optimized = 0;
            var totalMoveOps = 0;
            var totalMergeOps = 0;
            var totalPartialOps = 0;

            Object.values(productGroups).forEach(function(g) {
                var laneCount = g.lanes.size;  // 巷道數
                var locCount = g.locations.size;

                // ========== 取得品項的板容量設定（方案 A+D）==========
                var productConfig = window.getProductPalletCapacity ? window.getProductPalletCapacity(g.name, g.spec) : null;
                var palletCapacity = null;
                var partialPercent = 50;
                var useAutoDetect = false;

                if (productConfig) {
                    palletCapacity = productConfig.palletCapacity;
                    partialPercent = productConfig.partialThreshold || 50;
                } else {
                    useAutoDetect = true;
                    var maxQty = 0;
                    g.items.forEach(function(p) {
                        if ((p.quantity || 0) > maxQty) maxQty = p.quantity;
                    });
                    palletCapacity = maxQty > 0 ? Math.ceil(maxQty * 1.1) : 45;
                }

                var partialThresholdQty = Math.floor(palletCapacity * partialPercent / 100);

                var laneGroups = {};
                g.items.forEach(function(p) {
                    var parsed = parseLocationId(p.locationId);
                    if (parsed) {
                        var laneKey = parsed.laneKey;
                        if (!laneGroups[laneKey]) laneGroups[laneKey] = { qty: 0, palletCount: 0, items: [] };
                        laneGroups[laneKey].qty += (p.quantity || 0);
                        laneGroups[laneKey].palletCount++;
                        laneGroups[laneKey].items.push(p);
                    }
                });

                var laneList = Object.keys(laneGroups);

                var mainLane = null;
                if (laneList.length > 0) {
                    mainLane = laneList.sort(function(a, b) {
                        return laneGroups[b].qty - laneGroups[a].qty;
                    })[0];
                }

                // ========== 第一步：餘板合併建議 ==========
                var partialMerges = [];

                var partialPallets = g.items.filter(function(p) {
                    var qty = p.quantity || 0;
                    return qty > 0 && qty < partialThresholdQty;
                });

                if (partialPallets.length > 1) {
                    partialPallets.sort(function(a, b) {
                        var qtyDiff = (b.quantity || 0) - (a.quantity || 0);
                        if (qtyDiff !== 0) return qtyDiff;
                        var batchA = a.batchNo || '';
                        var batchB = b.batchNo || '';
                        if (batchA !== batchB) return batchA.localeCompare(batchB);
                        var expA = a.expDate || a.expiryDate || '9999';
                        var expB = b.expDate || b.expiryDate || '9999';
                        return expA.localeCompare(expB);
                    });

                    var used = new Set();

                    for (var i = 0; i < partialPallets.length; i++) {
                        if (used.has(i)) continue;

                        var keepPallet = partialPallets[i];
                        var currentTotal = keepPallet.quantity || 0;
                        var mergeGroup = {
                            keep: {
                                docId: keepPallet.id || '',
                                palletId: keepPallet.palletId,
                                location: keepPallet.locationId,
                                qty: keepPallet.quantity,
                                batchNo: keepPallet.batchNo,
                                expDate: keepPallet.expDate || keepPallet.expiryDate
                            },
                            sources: []
                        };

                        used.add(i);

                        for (var j = i + 1; j < partialPallets.length; j++) {
                            if (used.has(j)) continue;

                            var sourcePallet = partialPallets[j];
                            var newTotal = currentTotal + (sourcePallet.quantity || 0);

                            if (newTotal <= palletCapacity) {
                                mergeGroup.sources.push({
                                    docId: sourcePallet.id || '',
                                    palletId: sourcePallet.palletId,
                                    location: sourcePallet.locationId,
                                    qty: sourcePallet.quantity,
                                    batchNo: sourcePallet.batchNo,
                                    expDate: sourcePallet.expDate || sourcePallet.expiryDate
                                });
                                currentTotal = newTotal;
                                used.add(j);
                            }
                        }

                        if (mergeGroup.sources.length > 0) {
                            mergeGroup.totalAfterMerge = currentTotal;
                            mergeGroup.freedLocations = mergeGroup.sources.length;
                            mergeGroup.palletCapacity = palletCapacity;
                            mergeGroup.useAutoDetect = useAutoDetect;
                            partialMerges.push(mergeGroup);
                        }
                    }
                }

                // ========== 第二步：孤立板移位建議 ==========
                var isolatedMoves = [];

                if (laneList.length >= 3 && mainLane) {
                    var mainLaneQty = laneGroups[mainLane].qty;
                    var totalQty = g.totalQty;

                    var mainWarehouse = mainLane.split('-')[0];

                    var mainLaneOccupied = new Set();
                    laneGroups[mainLane].items.forEach(function(item) {
                        mainLaneOccupied.add(item.locationId);
                    });

                    var mainLaneParts = mainLane.split('-');
                    var mainZone = mainLaneParts[0];
                    var mainRow = mainLaneParts[1];
                    var mainCol = mainLaneParts[2];

                    // 依 RACK_CONFIG 計算主巷道各層剩餘容量（混合板型），而不是「空的才算一個位置」
                    var levelPriority = window.RACK_CONFIG.LEVEL_PRIORITY || ['2F', '3F', '1F'];
                    var slotCounts = {};
                    levelPriority.forEach(function(level) {
                        var slotId = mainZone + '-' + mainRow + '-' + mainCol + '-' + level;
                        slotCounts[slotId] = { level: level, counts: {} };
                        pallets.forEach(function(p) {
                            if (p.locationId === slotId) window.addPalletToCounts(slotCounts[slotId].counts, p);
                        });
                    });
                    function pickSlotFor(p) {
                        var type = window.palletTypeOf(p);
                        for (var k = 0; k < levelPriority.length; k++) {
                            var id = mainZone + '-' + mainRow + '-' + mainCol + '-' + levelPriority[k];
                            var sc = slotCounts[id];
                            if (window.canLevelFit(sc.counts, sc.level, type)) {
                                sc.counts[type] = (sc.counts[type] || 0) + 1;
                                return id;
                            }
                        }
                        return null;
                    }
                    var hasRoom = Object.keys(slotCounts).some(function(id) {
                        var sc = slotCounts[id];
                        return window.canLevelFit(sc.counts, sc.level, 'scattered') || window.canLevelFit(sc.counts, sc.level, 'full');
                    });

                    if (!hasRoom) {
                    } else {
                        laneList.forEach(function(lane) {
                            if (lane === mainLane) return;

                            var laneData = laneGroups[lane];
                            var laneWarehouse = lane.split('-')[0];

                            var isReallyIsolated = laneData.palletCount === 1;
                            var isDifferentWarehouse = laneWarehouse !== mainWarehouse;

                            if (isReallyIsolated || (isDifferentWarehouse && laneData.palletCount <= 2)) {
                                {
                                    laneData.items.forEach(function(p) {
                                        var targetSlot = pickSlotFor(p);
                                        if (!targetSlot) return;

                                        var reason = isReallyIsolated ?
                                            '孤立板(僅1板)' :
                                            '跨區(' + laneWarehouse + '→' + mainWarehouse + ')';

                                        isolatedMoves.push({
                                            type: 'isolated',
                                            docId: p.id || '',
                                            palletId: p.palletId,
                                            from: p.locationId,
                                            fromLane: lane,
                                            toLane: mainLane,
                                            toSlot: targetSlot,
                                            qty: p.quantity,
                                            batchNo: p.batchNo,
                                            expDate: p.expDate || p.expiryDate,
                                            reason: reason
                                        });
                                    });
                                }
                            }
                        });
                    }
                }

                totalPartialOps += partialMerges.length;
                totalMoveOps += isolatedMoves.length;

                if (partialMerges.length === 0 && isolatedMoves.length === 0) {
                    optimized++;
                    return;
                }

                var priority = 'low';
                if (partialMerges.length >= 2 || isolatedMoves.length >= 3) priority = 'high';
                else if (partialMerges.length >= 1 || isolatedMoves.length >= 1) priority = 'medium';

                dispatchItems.push({
                    name: g.name,
                    spec: g.spec,
                    totalQty: g.totalQty,
                    laneCount: laneCount,
                    locCount: locCount,
                    mainLane: mainLane,
                    partialMerges: partialMerges,    // 第一步：餘板合併
                    isolatedMoves: isolatedMoves,    // 第二步：孤立移位
                    palletCapacity: palletCapacity,
                    useAutoDetect: useAutoDetect,
                    priority: priority
                });
            });

            dispatchItems.sort(function(a, b) {
                var priorityOrder = { high: 0, medium: 1, low: 2 };
                if (priorityOrder[a.priority] !== priorityOrder[b.priority]) {
                    return priorityOrder[a.priority] - priorityOrder[b.priority];
                }
                return (b.partialMerges.length + b.isolatedMoves.length) -
                       (a.partialMerges.length + a.isolatedMoves.length);
            });

            window._dispatchAnalysis = dispatchItems;

            var totalProducts = Object.keys(productGroups).length;
            var el1 = document.getElementById('stat-need-dispatch');
            var el3 = document.getElementById('stat-need-partial');
            var elFreed = document.getElementById('stat-freed-slots');
            var elOps = document.getElementById('stat-total-ops');
            var el5 = document.getElementById('stat-optimized');
            var el6 = document.getElementById('stat-total-products');

            var totalFreedSlots = 0;
            var totalOps = 0;
            dispatchItems.forEach(function(d) {
                if (d.partialMerges) {
                    d.partialMerges.forEach(function(m) {
                        totalFreedSlots += m.sources.length;
                        totalOps += m.sources.length; // 每個來源板要合併一次
                    });
                }
                if (d.isolatedMoves) {
                    totalOps += d.isolatedMoves.length;
                }
            });

            if (el1) el1.innerText = totalMoveOps;
            if (el3) el3.innerText = totalPartialOps;
            if (elFreed) elFreed.innerText = totalFreedSlots;
            if (elOps) elOps.innerText = totalOps;
            if (el5) el5.innerText = optimized;
            if (el6) el6.innerText = totalProducts;

            var barMerge = document.getElementById('stat-bar-merge');
            var barMove = document.getElementById('stat-bar-move');
            var barOps = document.getElementById('stat-bar-ops');
            var barFree = document.getElementById('stat-bar-free');
            if (barMerge) barMerge.innerText = totalPartialOps;
            if (barMove) barMove.innerText = totalMoveOps;
            if (barOps) barOps.innerText = totalOps;
            if (barFree) barFree.innerText = totalFreedSlots;

            console.log('調度分析完成:', {
                totalProducts: totalProducts,
                needDispatch: dispatchItems.length,
                optimized: optimized,
                partialOps: totalPartialOps,
                moveOps: totalMoveOps,
                freedSlots: totalFreedSlots
            });

            renderDispatchOrders(dispatchItems);

            var loadingEl = document.getElementById('analysis-loading');
            if (loadingEl) loadingEl.classList.add('hidden');
            goToDispatchStep(2);

            var btnStep3 = document.getElementById('btn-goto-step3');
            if (btnStep3) {
                if (dispatchItems.length === 0) {
                    btnStep3.disabled = true;
                    btnStep3.innerText = '無需調度';
                } else {
                    btnStep3.disabled = false;
                    btnStep3.innerHTML = '下一步：發布執行 <i class="fa-solid fa-arrow-right ml-2"></i>';
                }
            }
        };

        function renderDispatchOrders(items) {
            var container = document.getElementById('dispatch-orders-container');
            if (!container) return;

            if (items.length === 0) {
                container.innerHTML = '<div class="text-center py-12"><i class="fa-solid fa-check-circle text-emerald-400 text-5xl mb-4"></i><p class="text-emerald-400 text-xl font-bold">所有品項都已優化！</p><p class="text-slate-500 mt-2">目前無需執行調度作業</p></div>';
                updateDispatchSelectionUI();
                return;
            }

            var html = '<table class="w-full text-sm">';
            html += '<thead class="bg-slate-800 sticky top-0">';
            html += '<tr class="text-slate-400 text-xs">';
            html += '<th class="p-2 text-left w-8"><input type="checkbox" id="dispatch-select-all-table" onchange="toggleAllDispatchOrders()" class="w-4 h-4"></th>';
            html += '<th class="p-2 text-left">品項</th>';
            html += '<th class="p-2 text-center w-20">操作</th>';
            html += '<th class="p-2 text-left">明細</th>';
            html += '<th class="p-2 text-center w-16">釋放</th>';
            html += '<th class="p-2 text-center w-12"></th>';
            html += '</tr></thead><tbody>';

            var orderNo = 1;
            items.forEach(function(item, idx) {
                var hasMerge = item.partialMerges && item.partialMerges.length > 0;
                var hasMove = item.isolatedMoves && item.isolatedMoves.length > 0;
                var mergeCount = 0, moveCount = 0, freeCount = 0;

                if (hasMerge) {
                    item.partialMerges.forEach(function(g) {
                        mergeCount += g.sources.length;
                        freeCount += g.sources.length;
                    });
                }
                if (hasMove) moveCount = item.isolatedMoves.length;

                html += '<tr class="border-b border-slate-700 hover:bg-slate-800/50 dispatch-order-item" data-idx="' + idx + '">';

                html += '<td class="p-2"><input type="checkbox" class="dispatch-order-checkbox w-4 h-4 accent-purple-500" data-idx="' + idx + '" onchange="updateDispatchSelectionUI()"></td>';

                html += '<td class="p-2">';
                html += '<div class="flex items-center gap-2">';
                html += '<span class="bg-blue-600 text-white text-[10px] font-bold px-1.5 py-0.5 rounded">' + String(orderNo).padStart(3, '0') + '</span>';
                html += '<span class="text-white font-bold">' + item.name + '</span>';
                if (item.spec) html += '<span class="text-slate-500 text-xs">(' + item.spec + ')</span>';
                html += '</div>';
                html += '<div class="text-[10px] text-slate-500 mt-0.5">容量' + item.palletCapacity + ' · 庫存' + item.totalQty + ' · ' + item.laneCount + '巷道</div>';
                html += '</td>';

                html += '<td class="p-2 text-center">';
                if (mergeCount > 0) html += '<span class="inline-block bg-orange-900/50 text-orange-400 text-[10px] px-1.5 py-0.5 rounded border border-orange-700 mr-1">併' + mergeCount + '</span>';
                if (moveCount > 0) html += '<span class="inline-block bg-blue-900/50 text-blue-400 text-[10px] px-1.5 py-0.5 rounded border border-blue-700">移' + moveCount + '</span>';
                html += '</td>';

                html += '<td class="p-2 text-xs">';
                if (hasMerge) {
                    item.partialMerges.forEach(function(g, gIdx) {
                        var srcLocs = g.sources.map(function(s) { return s.location; }).join(', ');
                        html += '<div class="text-orange-300 mb-0.5">';
                        html += '<span class="text-orange-500">→</span> ' + srcLocs + ' <span class="text-slate-500">併入</span> <span class="text-emerald-400 font-mono">' + g.keep.location + '</span>';
                        html += ' <span class="text-slate-600">(' + g.totalAfterMerge + '件)</span>';
                        html += '</div>';
                    });
                }
                if (hasMove) {
                    item.isolatedMoves.forEach(function(m) {
                        html += '<div class="text-blue-300 mb-0.5">';
                        html += '<span class="text-blue-500">→</span> <span class="font-mono">' + m.from + '</span> <span class="text-slate-500">移至</span> <span class="text-emerald-400 font-mono">' + m.toSlot + '</span>';
                        html += ' <span class="text-slate-600">(' + m.qty + '件)</span>';
                        html += '</div>';
                    });
                }
                html += '</td>';

                html += '<td class="p-2 text-center">';
                if (freeCount > 0) {
                    html += '<span class="text-emerald-400 font-bold">' + freeCount + '</span>';
                } else {
                    html += '<span class="text-slate-600">-</span>';
                }
                html += '</td>';

                html += '<td class="p-2 text-center">';
                html += '<button onclick="printSingleDispatchOrder(' + idx + ')" class="text-slate-400 hover:text-white"><i class="fa-solid fa-print"></i></button>';
                html += '</td>';

                html += '</tr>';
                orderNo++;
            });

            html += '</tbody></table>';
            container.innerHTML = html;
            updateDispatchSelectionUI();
        }

        window.printSingleDispatchOrder = function(idx) {
            if (!window._dispatchAnalysis) {
                alert('請先執行調度分析');
                return;
            }
            var item = window._dispatchAnalysis[idx];
            if (!item) {
                alert('找不到工單資料');
                return;
            }
            printDispatchOrder([item], '調度工單 - ' + item.name);
        };

        // ========== 調度工單勾選功能 ==========
        window.toggleAllDispatchOrders = function() {
            var selectAll = document.getElementById('dispatch-select-all');
            var selectAllTable = document.getElementById('dispatch-select-all-table');
            var isChecked = selectAll ? selectAll.checked : (selectAllTable ? selectAllTable.checked : false);
            var checkboxes = document.querySelectorAll('.dispatch-order-checkbox');
            checkboxes.forEach(function(cb) {
                cb.checked = isChecked;
            });
            updateDispatchSelectionUI();
        };

        window.updateDispatchSelectionUI = function() {
            var checkboxes = document.querySelectorAll('.dispatch-order-checkbox:checked');
            var count = checkboxes.length;
            var total = document.querySelectorAll('.dispatch-order-checkbox').length;

            var countEl = document.getElementById('dispatch-selected-count');
            if (countEl) countEl.innerText = count;

            var publishCountEl = document.getElementById('publish-count');
            if (publishCountEl) publishCountEl.innerText = count;

            var selectAll = document.getElementById('dispatch-select-all');
            if (selectAll) {
                selectAll.checked = count === total && total > 0;
                selectAll.indeterminate = count > 0 && count < total;
            }

            var btnPublish = document.getElementById('btn-publish-mobile');
            var btnPrint = document.getElementById('btn-print-selected');
            if (btnPublish) btnPublish.disabled = count === 0;
            if (btnPrint) btnPrint.disabled = count === 0;
        };

        window.getSelectedDispatchIndices = function() {
            var indices = [];
            document.querySelectorAll('.dispatch-order-checkbox:checked').forEach(function(cb) {
                indices.push(parseInt(cb.dataset.idx));
            });
            return indices;
        };

        window.publishSelectedToMobile = async function() {
            var indices = getSelectedDispatchIndices();
            if (indices.length === 0) {
                alert('請先勾選要發布的工單');
                return;
            }

            var items = indices.map(function(idx) { return window._dispatchAnalysis[idx]; }).filter(Boolean);

            var totalOps = 0;
            items.forEach(function(item) {
                if (item.partialMerges) {
                    item.partialMerges.forEach(function(g) { totalOps += g.sources.length; });
                }
                if (item.isolatedMoves) totalOps += item.isolatedMoves.length;
            });

            if (!confirm('確定要發布 ' + items.length + ' 個調度工單到手機？\n\n共 ' + totalOps + ' 項操作\n\n發布後，堆高機手的手機會立即收到通知')) {
                return;
            }

            var successCount = 0;
            var timestamp = new Date().toISOString();
            var batchNo = 'DSP-' + Date.now().toString().slice(-8);

            for (var i = 0; i < items.length; i++) {
                var item = items[i];
                var operations = [];
                var opIndex = 0;

                if (item.partialMerges) {
                    item.partialMerges.forEach(function(group) {
                        group.sources.forEach(function(src) {
                            operations.push({
                                id: 'op-' + opIndex++,
                                type: '合併',
                                from: src.location,
                                palletId: src.palletId || '',
                                qty: src.qty,
                                to: group.keep.location
                            });
                        });
                    });
                }

                if (item.isolatedMoves) {
                    item.isolatedMoves.forEach(function(m) {
                        operations.push({
                            id: 'op-' + opIndex++,
                            type: '移位',
                            from: m.from,
                            palletId: m.palletId || '',
                            qty: m.qty,
                            to: m.toSlot,
                            reason: m.reason
                        });
                    });
                }

                if (operations.length === 0) continue;

                var order = {
                    orderNo: batchNo + '-' + String(i + 1).padStart(3, '0'),
                    batchNo: batchNo,
                    productName: item.name,
                    spec: item.spec || '',
                    operations: operations,
                    totalOps: operations.length,
                    completedOps: [],
                    status: 'pending',
                    createdAt: timestamp,
                    createdBy: window.getOperatorName ? window.getOperatorName() : 'system'
                };

                try {
                    await window.addDoc(window.collection(window.db, 'dispatchOrders'), order);
                    successCount++;
                } catch (err) {
                    console.error('發布工單失敗:', err);
                }
            }

            if (successCount > 0) {
                alert('✅ 已發布 ' + successCount + ' 個調度工單到手機！\n\n批次編號：' + batchNo + '\n\n📱 堆高機手的手機會收到通知');

                document.querySelectorAll('.dispatch-order-checkbox').forEach(function(cb) { cb.checked = false; });
                document.getElementById('dispatch-select-all').checked = false;
                updateDispatchSelectionUI();
            } else {
                alert('❌ 發布失敗，請檢查網路連線');
            }
        };

        window.printSelectedDispatchOrders = function() {
            var indices = getSelectedDispatchIndices();
            if (indices.length === 0) {
                alert('請先勾選要列印的工單');
                return;
            }

            var items = indices.map(function(idx) { return window._dispatchAnalysis[idx]; }).filter(Boolean);
            printDispatchOrdersInternal(items, '調度工單（選取）');
        };

        window.publishDispatchToMobile = async function() {
            if (!window._dispatchAnalysis || window._dispatchAnalysis.length === 0) {
                alert('目前沒有調度工單可發布\n\n請先等待系統分析完成');
                return;
            }

            var items = window._dispatchAnalysis;
            var totalOps = 0;
            items.forEach(function(item) {
                if (item.partialMerges) {
                    item.partialMerges.forEach(function(g) { totalOps += g.sources.length; });
                }
                if (item.isolatedMoves) totalOps += item.isolatedMoves.length;
            });

            if (!confirm('確定要發布 ' + items.length + ' 個調度工單到手機？\n\n共 ' + totalOps + ' 項操作\n\n發布後，堆高機手的手機會立即收到通知')) {
                return;
            }

            var successCount = 0;
            var timestamp = new Date().toISOString();
            var batchNo = 'DSP-' + Date.now().toString().slice(-8);

            for (var i = 0; i < items.length; i++) {
                var item = items[i];
                var operations = [];
                var opIndex = 0;

                if (item.partialMerges) {
                    item.partialMerges.forEach(function(group) {
                        group.sources.forEach(function(src) {
                            operations.push({
                                id: 'op-' + opIndex++,
                                type: '合併',
                                from: src.location,
                                palletId: src.palletId || '',
                                qty: src.qty,
                                to: group.keep.location
                            });
                        });
                    });
                }

                if (item.isolatedMoves) {
                    item.isolatedMoves.forEach(function(m) {
                        operations.push({
                            id: 'op-' + opIndex++,
                            type: '移位',
                            from: m.from,
                            palletId: m.palletId || '',
                            qty: m.qty,
                            to: m.toSlot,
                            reason: m.reason
                        });
                    });
                }

                if (operations.length === 0) continue;

                var order = {
                    orderNo: batchNo + '-' + String(i + 1).padStart(3, '0'),
                    batchNo: batchNo,
                    productName: item.name,
                    spec: item.spec || '',
                    operations: operations,
                    totalOps: operations.length,
                    completedOps: [],
                    status: 'pending',
                    createdAt: timestamp,
                    createdBy: window.getOperatorName ? window.getOperatorName() : 'system'
                };

                try {
                    await window.addDoc(window.collection(window.db, 'dispatchOrders'), order);
                    successCount++;
                } catch (err) {
                    console.error('發布工單失敗:', err);
                }
            }

            if (successCount > 0) {
                alert('✅ 已發布 ' + successCount + ' 個調度工單到手機！\n\n批次編號：' + batchNo + '\n\n📱 堆高機手的手機會收到通知');

                var section = document.getElementById('published-orders-section');
                var list = document.getElementById('published-orders-list');
                if (section && list) {
                    section.classList.remove('hidden');
                    list.innerHTML += '<div class="flex items-center justify-between bg-slate-800 rounded-lg p-3">' +
                        '<div class="flex items-center gap-3">' +
                        '<i class="fa-solid fa-check-circle text-green-400"></i>' +
                        '<span class="text-white font-mono">' + batchNo + '</span>' +
                        '<span class="text-slate-400 text-sm">' + successCount + ' 個工單</span>' +
                        '</div>' +
                        '<span class="text-slate-500 text-sm">' + new Date().toLocaleTimeString('zh-TW') + '</span>' +
                        '</div>';
                }
            } else {
                alert('❌ 發布失敗，請檢查網路連線');
            }
        };

        window.printAllDispatchOrders = function() {
            if (!window._dispatchAnalysis) {
                alert('請先執行調度分析（點擊「開始分析」按鈕）');
                return;
            }
            var items = window._dispatchAnalysis;
            if (items.length === 0) {
                alert('目前無需要調度的工單（所有品項都已優化）');
                return;
            }
            printDispatchOrdersInternal(items, '調度工單總表');
        };

        function printDispatchOrdersInternal(items, title) {
            var html = '<style>';
                html += '.page-header { text-align: center; border-bottom: 2px solid #000; padding-bottom: 8px; margin-bottom: 15px; }';
                html += '.page-header h1 { font-size: 18px; margin: 0; }';
                html += '.page-header .date { font-size: 10px; color: #666; }';
                html += '.order { border: 2px solid #333; margin-bottom: 15px; page-break-inside: avoid; }';
                html += '.order-header { background: #333; color: white; padding: 8px 12px; font-size: 13px; font-weight: bold; }';
                html += '.order-info { background: #f5f5f5; padding: 6px 12px; border-bottom: 1px solid #ccc; font-size: 10px; }';
                html += '.order-info span { margin-right: 15px; }';
                html += '.section { border-top: 1px solid #ccc; }';
                html += '.section-header { background: #eee; padding: 5px 12px; font-weight: bold; font-size: 11px; }';
                html += '.section-header.merge { background: #fff3cd; }';
                html += '.section-header.move { background: #cce5ff; }';
                html += 'table { width: 100%; border-collapse: collapse; }';
                html += 'th { background: #f0f0f0; text-align: left; padding: 5px 8px; font-weight: normal; font-size: 10px; border-bottom: 1px solid #ccc; }';
                html += 'td { padding: 6px 8px; border-bottom: 1px solid #eee; }';
                html += '.from { color: #c00; font-weight: bold; font-family: monospace; }';
                html += '.to { color: #060; font-weight: bold; font-family: monospace; }';
                html += '.qty { text-align: right; font-weight: bold; }';
                html += '.checkbox { width: 18px; height: 18px; border: 2px solid #333; display: inline-block; }';
                html += '.result-row { background: #e8f5e9; font-weight: bold; }';
                html += '.signature { margin-top: 20px; display: flex; justify-content: space-around; }';
                html += '.signature div { text-align: center; }';
                html += '.signature .line { width: 120px; border-bottom: 1px solid #000; height: 30px; margin-bottom: 5px; }';
                html += '</style>';

                html += '<div class="page-header">';
                html += '<h1>' + title + '</h1>';
                html += '<div class="date">產生時間：' + new Date().toLocaleString('zh-TW') + '</div>';
                html += '</div>';

            items.forEach(function(item, idx) {
                html += '<div class="order">';
                html += '<div class="order-header">工單 #' + String(idx + 1).padStart(3, '0') + '　' + item.name + (item.spec ? ' (' + item.spec + ')' : '') + '</div>';

                html += '<div class="order-info">';
                html += '<span>板容量：<b>' + item.palletCapacity + '</b> 件/板</span>';
                html += '<span>餘板標準：<b>&lt;' + Math.floor(item.palletCapacity * 0.5) + '</b>件</span>';
                html += '<span>總庫存：<b>' + item.totalQty + '</b> 件</span>';
                html += '<span>主巷道：<b>' + (item.mainLane || '-') + '</b></span>';
                html += '</div>';

                if (item.partialMerges && item.partialMerges.length > 0) {
                    item.partialMerges.forEach(function(group, gIdx) {
                        html += '<div class="section">';
                        html += '<div class="section-header merge">【合併作業 #' + (gIdx + 1) + '】完成後釋放 ' + group.sources.length + ' 個儲位</div>';
                        html += '<table>';
                        html += '<tr><th style="width:40px">步驟</th><th>來源儲位</th><th>板號</th><th style="width:60px">數量</th><th style="width:30px">→</th><th>目標儲位</th><th>說明</th><th style="width:50px">完成</th></tr>';

                        group.sources.forEach(function(src, sIdx) {
                            html += '<tr>';
                            html += '<td>' + (sIdx + 1) + '</td>';
                            html += '<td class="from">' + src.location + '</td>';
                            html += '<td>' + (src.palletId || '-') + '</td>';
                            html += '<td class="qty">' + src.qty + ' 件</td>';
                            html += '<td>→</td>';
                            html += '<td class="to">' + group.keep.location + '</td>';
                            html += '<td>合併至此，來源清空</td>';
                            html += '<td><span class="checkbox"></span></td>';
                            html += '</tr>';
                        });

                        html += '<tr class="result-row">';
                        html += '<td colspan="3">合併後結果</td>';
                        html += '<td class="qty">' + group.totalAfterMerge + ' 件</td>';
                        html += '<td></td>';
                        html += '<td class="to">' + group.keep.location + '</td>';
                        html += '<td>' + Math.round(group.totalAfterMerge / item.palletCapacity * 100) + '% 板容量</td>';
                        html += '<td></td>';
                        html += '</tr>';
                        html += '</table></div>';
                    });
                }

                if (item.isolatedMoves && item.isolatedMoves.length > 0) {
                    html += '<div class="section">';
                    html += '<div class="section-header move">【移位作業】移至主巷道 ' + item.mainLane + ' 集中存放</div>';
                    html += '<table>';
                    html += '<tr><th style="width:40px">步驟</th><th>來源儲位</th><th>板號</th><th style="width:60px">數量</th><th style="width:30px">→</th><th>目標儲位</th><th>移位原因</th><th style="width:50px">完成</th></tr>';

                    item.isolatedMoves.forEach(function(m, mIdx) {
                        html += '<tr>';
                        html += '<td>' + (mIdx + 1) + '</td>';
                        html += '<td class="from">' + m.from + '</td>';
                        html += '<td>' + (m.palletId || '-') + '</td>';
                        html += '<td class="qty">' + m.qty + ' 件</td>';
                        html += '<td>→</td>';
                        html += '<td class="to">' + m.toSlot + '</td>';
                        html += '<td>' + m.reason + '</td>';
                        html += '<td><span class="checkbox"></span></td>';
                        html += '</tr>';
                    });
                    html += '</table></div>';
                }

                html += '</div>';
            });

            html += '<div class="signature">';
            html += '<div><div class="line"></div>製單人</div>';
            html += '<div><div class="line"></div>執行人</div>';
            html += '<div><div class="line"></div>確認人</div>';
            html += '</div>';

            openPrintPreview(html, title, 1000, 800);
        }

        // ========== 調度工單執行系統 ==========

        window._dispatchExecData = {
            currentOrderIdx: -1,
            operations: [],      // 當前工單的所有操作
            completedIds: []     // 已完成的操作ID
        };

        window.openDispatchExecuteModal = function() {
            var items = window._dispatchAnalysis;
            if (!items || items.length === 0) {
                alert('目前無調度工單可執行\n請先點擊「重新分析」產生工單');
                return;
            }

            var select = document.getElementById('dispatch-exec-order-select');
            select.innerHTML = '<option value="">-- 請選擇工單 --</option>';
            items.forEach(function(item, idx) {
                var opsCount = (item.partialMerges ? item.partialMerges.reduce(function(sum, m) { return sum + m.sources.length; }, 0) : 0) +
                               (item.isolatedMoves ? item.isolatedMoves.length : 0);
                select.innerHTML += '<option value="' + idx + '">工單 #' + String(idx + 1).padStart(3, '0') + ' - ' + item.name + ' (' + opsCount + '項操作)</option>';
            });

            window._dispatchExecData = { currentOrderIdx: -1, operations: [], completedIds: [] };
            document.getElementById('dispatch-exec-list').innerHTML = '<tr><td colspan="9" class="text-center text-slate-500 py-8">請選擇工單</td></tr>';
            document.getElementById('dispatch-exec-progress').innerText = '0/0';
            document.getElementById('dispatch-scan-input').value = '';
            document.getElementById('dispatch-scan-result').classList.add('hidden');
            document.getElementById('dispatch-batch-mode').checked = false;
            toggleDispatchBatchMode();

            document.getElementById('modal-dispatch-execute').classList.remove('hidden');

            setTimeout(function() {
                document.getElementById('dispatch-scan-input').focus();
            }, 100);
        };

        window.closeDispatchExecuteModal = function() {
            document.getElementById('modal-dispatch-execute').classList.add('hidden');
        };

        window.toggleDispatchBatchMode = function() {
            var batchMode = document.getElementById('dispatch-batch-mode').checked;
            var scanArea = document.getElementById('dispatch-scan-area');
            var batchHeader = document.getElementById('dispatch-batch-header');
            var batchExecBtn = document.getElementById('btn-dispatch-batch-exec');

            if (batchMode) {
                scanArea.style.display = 'none';
                batchHeader.style.display = '';
                batchExecBtn.classList.remove('hidden');
                document.getElementById('dispatch-exec-subtitle').innerText = '勾選已完成項目後批次執行';
            } else {
                scanArea.style.display = '';
                batchHeader.style.display = 'none';
                batchExecBtn.classList.add('hidden');
                document.getElementById('dispatch-exec-subtitle').innerText = '掃描板號確認執行';
            }

            renderDispatchExecList();
        };

        window.loadDispatchExecOrder = function() {
            var select = document.getElementById('dispatch-exec-order-select');
            var idx = parseInt(select.value);

            if (isNaN(idx) || idx < 0) {
                document.getElementById('dispatch-exec-list').innerHTML = '<tr><td colspan="9" class="text-center text-slate-500 py-8">請選擇工單</td></tr>';
                document.getElementById('dispatch-exec-progress').innerText = '0/0';
                return;
            }

            var item = window._dispatchAnalysis[idx];
            if (!item) return;

            var operations = [];
            var opIdx = 0;

            if (item.partialMerges) {
                item.partialMerges.forEach(function(group, gIdx) {
                    group.sources.forEach(function(src, sIdx) {
                        operations.push({
                            id: 'merge-' + gIdx + '-' + sIdx,
                            type: 'merge',
                            typeName: '合併',
                            from: src.location,
                            docId: src.docId || '',
                            palletId: src.palletId || '',
                            qty: src.qty,
                            to: group.keep.location,
                            toSlotSuggested: group.keep.location,
                            note: '合併至保留板',
                            completed: false,
                            groupIdx: gIdx,
                            sourceIdx: sIdx,
                            keepPallet: group.keep
                        });
                        opIdx++;
                    });
                });
            }

            if (item.isolatedMoves) {
                item.isolatedMoves.forEach(function(m, mIdx) {
                    operations.push({
                        id: 'move-' + mIdx,
                        type: 'move',
                        typeName: '移位',
                        from: m.from,
                        docId: m.docId || '',
                        palletId: m.palletId || '',
                        qty: m.qty,
                        to: m.toSlot,
                        toSlotSuggested: m.toSlot,
                        note: m.reason,
                        completed: false
                    });
                    opIdx++;
                });
            }

            window._dispatchExecData = {
                currentOrderIdx: idx,
                currentItem: item,
                operations: operations,
                completedIds: []
            };

            renderDispatchExecList();
            updateDispatchProgress();

            document.getElementById('dispatch-scan-input').focus();
        };

        function renderDispatchExecList() {
            var tbody = document.getElementById('dispatch-exec-list');
            var ops = window._dispatchExecData.operations;
            var batchMode = document.getElementById('dispatch-batch-mode').checked;

            if (ops.length === 0) {
                tbody.innerHTML = '<tr><td colspan="9" class="text-center text-slate-500 py-8">請選擇工單</td></tr>';
                return;
            }

            var html = '';
            ops.forEach(function(op) {
                var statusBadge = op.completed
                    ? '<span class="badge badge-green"><i class="fa-solid fa-check mr-1"></i>完成</span>'
                    : '<span class="badge badge-yellow"><i class="fa-solid fa-clock mr-1"></i>待執行</span>';
                var rowClass = op.completed ? 'bg-emerald-900/20' : '';
                var typeColor = op.type === 'merge' ? 'orange' : 'blue';

                html += '<tr class="' + rowClass + ' border-b border-slate-700/50 hover:bg-slate-800/50">';

                if (batchMode) {
                    html += '<td class="p-2"><input type="checkbox" class="dispatch-op-check w-4 h-4" data-id="' + op.id + '"' + (op.completed ? ' checked disabled' : '') + '></td>';
                }

                html += '<td class="p-2">' + statusBadge + '</td>';
                html += '<td class="p-2"><span class="badge badge-' + typeColor + '">' + op.typeName + '</span></td>';
                html += '<td class="p-2 font-mono text-red-400 font-bold">' + op.from + '</td>';
                html += '<td class="p-2 font-mono text-slate-300">' + (op.palletId || '-') + '</td>';
                html += '<td class="p-2 text-right text-yellow-400 font-bold">' + op.qty + '</td>';
                html += '<td class="p-2 text-center text-slate-500"><i class="fa-solid fa-arrow-right"></i></td>';
                html += '<td class="p-2 font-mono text-emerald-400 font-bold">' + op.to + '</td>';
                html += '<td class="p-2 text-slate-400 text-xs">' + op.note + '</td>';
                html += '</tr>';
            });

            tbody.innerHTML = html;
        }

        function updateDispatchProgress() {
            var ops = window._dispatchExecData.operations;
            var completed = ops.filter(function(op) { return op.completed; }).length;
            document.getElementById('dispatch-exec-progress').innerText = completed + '/' + ops.length;
        }

        window.confirmDispatchScan = function() {
            var input = document.getElementById('dispatch-scan-input');
            var scanned = input.value.trim();
            var resultEl = document.getElementById('dispatch-scan-result');

            if (!scanned) {
                resultEl.innerHTML = '<span class="text-yellow-400"><i class="fa-solid fa-exclamation-triangle mr-1"></i>請輸入板號</span>';
                resultEl.classList.remove('hidden');
                return;
            }

            var ops = window._dispatchExecData.operations;
            var found = null;

            for (var i = 0; i < ops.length; i++) {
                if (!ops[i].completed) {
                    if (ops[i].palletId === scanned || ops[i].from === scanned) {
                        found = ops[i];
                        break;
                    }
                }
            }

            if (!found) {
                resultEl.innerHTML = '<span class="text-red-400"><i class="fa-solid fa-times-circle mr-1"></i>找不到符合的待執行項目：' + scanned + '</span>';
                resultEl.classList.remove('hidden');
                input.select();
                return;
            }

            executeDispatchOperation(found);

            resultEl.innerHTML = '<span class="text-emerald-400"><i class="fa-solid fa-check-circle mr-1"></i>已確認：' + found.from + ' → ' + found.to + '</span>';
            resultEl.classList.remove('hidden');

            input.value = '';
            input.focus();
        };

        window.toggleAllDispatchChecks = function() {
            var checkAll = document.getElementById('dispatch-check-all').checked;
            document.querySelectorAll('.dispatch-op-check:not(:disabled)').forEach(function(cb) {
                cb.checked = checkAll;
            });
        };

        window.executeDispatchBatch = async function() {
            var checkboxes = document.querySelectorAll('.dispatch-op-check:checked:not(:disabled)');
            if (checkboxes.length === 0) {
                alert('請勾選要執行的項目');
                return;
            }

            if (!confirm('確定要執行勾選的 ' + checkboxes.length + ' 項操作？\n\n系統將自動更新庫存位置。')) {
                return;
            }

            var ops = window._dispatchExecData.operations;
            var ids = [];
            checkboxes.forEach(function(cb) { ids.push(cb.dataset.id); });

            for (var i = 0; i < ops.length; i++) {
                if (ids.indexOf(ops[i].id) >= 0 && !ops[i].completed) {
                    await executeDispatchOperation(ops[i]);
                }
            }

            alert('✅ 已執行 ' + ids.length + ' 項操作');
        };

        async function executeDispatchOperation(op) {
            try {
                if (op.type === 'merge') {
                    var keep = op.keepPallet || {};
                    var sourceRef = await window.resolvePalletRef(op.docId, op.palletId, op.from);
                    var targetRef = await window.resolvePalletRef(keep.docId, keep.palletId, keep.location);
                    await window.mergePalletsTx(sourceRef, targetRef, { note: op.note || ('合併至 ' + op.to) });

                } else if (op.type === 'move') {
                    var palletRef = await window.resolvePalletRef(op.docId, op.palletId, op.from);
                    await window.movePalletTx(palletRef, op.to, { note: op.note || '' });
                }

                op.completed = true;
                window._dispatchExecData.completedIds.push(op.id);

                renderDispatchExecList();
                updateDispatchProgress();

            } catch (err) {
                console.error('執行操作失敗:', err);
                alert('操作失敗: ' + err.message);
            }
        }

        window.completeDispatchOrder = function() {
            var ops = window._dispatchExecData.operations;
            var completed = ops.filter(function(op) { return op.completed; }).length;

            if (completed === 0) {
                alert('尚未執行任何操作');
                return;
            }

            var remaining = ops.length - completed;
            var msg = '工單執行摘要：\n\n';
            msg += '✅ 已完成：' + completed + ' 項\n';
            if (remaining > 0) {
                msg += '⏳ 未完成：' + remaining + ' 項\n';
            }
            msg += '\n確定要結束此工單嗎？';

            if (!confirm(msg)) return;

            if (window.loadInventory) window.loadInventory();

            closeDispatchExecuteModal();

            setTimeout(function() {
                if (window.refreshDispatchAnalysis) window.refreshDispatchAnalysis();
            }, 500);

            alert('✅ 工單已完成！\n\n庫存已更新，系統將重新分析調度需求。');
        };

        // ========== 波次揀貨系統 ==========

        window._waveData = {
            waves: [],
            currentWave: null,
            pickingList: [],
            completedItems: []
        };

        window.loadWavesFromFirebase = async function() {
            try {
                if (!window.db || !window.collection || !window.getDocs) {
                    console.log('Firebase 尚未初始化，使用 localStorage');
                    window._waveData.waves = JSON.parse(localStorage.getItem('wms_waves') || '[]');
                    refreshWaveList();
                    return;
                }

                var snapshot = await window.getDocs(window.collection(window.db, 'waves'));
                window._waveData.waves = [];
                snapshot.forEach(function(doc) {
                    window._waveData.waves.push({ id: doc.id, ...doc.data() });
                });

                window._waveData.waves.sort(function(a, b) {
                    return (b.createdAt || '').localeCompare(a.createdAt || '');
                });

                console.log('波次資料已載入:', window._waveData.waves.length, '筆');

                localStorage.setItem('wms_waves', JSON.stringify(window._waveData.waves));

                refreshWaveList();
            } catch(e) {
                console.error('載入波次資料失敗:', e);
                window._waveData.waves = JSON.parse(localStorage.getItem('wms_waves') || '[]');
                refreshWaveList();
            }
        };

        async function saveWaves() {
            localStorage.setItem('wms_waves', JSON.stringify(window._waveData.waves));
        }

        function generateWaveNo() {
            var today = new Date();
            var dateStr = today.getFullYear().toString().substr(2) +
                         String(today.getMonth() + 1).padStart(2, '0') +
                         String(today.getDate()).padStart(2, '0');
            var todayWaves = window._waveData.waves.filter(function(w) {
                return w.waveNo && w.waveNo.indexOf('W' + dateStr) === 0;
            });
            var seq = todayWaves.length + 1;
            return 'W' + dateStr + '-' + String(seq).padStart(3, '0');
        }

        window.waveCompany = '崇文';

        window.setWaveCompany = function(company) {
            window.waveCompany = company;

            document.getElementById('btn-wave-cw').className = company === '崇文'
                ? 'px-3 py-1.5 rounded text-xs font-bold bg-blue-600 text-white'
                : 'px-3 py-1.5 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            document.getElementById('btn-wave-bf').className = company === '八方'
                ? 'px-3 py-1.5 rounded text-xs font-bold bg-purple-600 text-white'
                : 'px-3 py-1.5 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';

            refreshWaveList();
        };

        window.rmCompany = 'all';
        window.rmStockData = [];
        window.rmStockSelected = {};
        window.rmStockFilter = 'all';
        
        // 原料領用購物車
        window.rmPickingCart = [];
        
        // 原料領用彈窗狀態
        window.rmModalState = {
            step: 1,
            allItems: [],
            selectedProduct: null,
            selectedSpec: null,
            selectedBatch: null,
            selectedLocation: null,
            selectedItem: null
        };
        
        // 原料領用彈窗購物車
        window.rmModalCart = [];

        // 更新步驟狀態（防呆機制）
        window.updateRmStepStatus = function() {
            var user = (document.getElementById('rm-pick-user').value || '').trim();
            var step1Complete = user.length > 0;
            
            // 更新步驟 1 面板狀態
            var step1Panel = document.getElementById('rm-step1-panel');
            if (step1Complete) {
                step1Panel.classList.remove('border-slate-600');
                step1Panel.classList.add('border-emerald-500/50');
            } else {
                step1Panel.classList.add('border-slate-600');
                step1Panel.classList.remove('border-emerald-500/50');
            }
            
            // 更新步驟 2 按鈕狀態
            var btn = document.getElementById('btn-open-rm-modal');
            var step2Panel = document.getElementById('rm-step2-panel');
            var step2Hint = document.getElementById('rm-step2-hint');
            
            if (step1Complete) {
                btn.disabled = false;
                step2Panel.classList.remove('opacity-50');
                if (step2Hint) {
                    step2Hint.innerHTML = '<i class="fa-solid fa-info-circle mr-1"></i>彈窗內可連續選擇多筆品項';
                    step2Hint.classList.remove('text-orange-400');
                    step2Hint.classList.add('text-slate-500');
                }
            } else {
                btn.disabled = true;
                step2Panel.classList.add('opacity-50');
                if (step2Hint) {
                    step2Hint.innerHTML = '<i class="fa-solid fa-lock mr-1"></i>請先填寫領用人';
                    step2Hint.classList.add('text-orange-400');
                    step2Hint.classList.remove('text-slate-500');
                }
            }
            
            // 更新確認按鈕
            var confirmBtn = document.getElementById('btn-rm-confirm-cart');
            if (confirmBtn) {
                confirmBtn.disabled = !(step1Complete && window.rmPickingCart.length > 0);
            }
        };

        // 設定公司篩選
        window.setRmCompany = function(filter) {
            window.rmStockFilter = filter;
            
            document.getElementById('btn-rm-all').className = filter === 'all'
                ? 'px-3 py-1 rounded text-xs font-bold bg-cyan-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            document.getElementById('btn-rm-cw').className = filter === '崇文'
                ? 'px-3 py-1 rounded text-xs font-bold bg-blue-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            document.getElementById('btn-rm-bf').className = filter === '八方'
                ? 'px-3 py-1 rounded text-xs font-bold bg-purple-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
        };

        // 開啟原料領用品項選擇彈窗
        window.openRmProductModal = function() {
            var user = (document.getElementById('rm-pick-user').value || '').trim();
            if (!user) {
                alert('請先填寫領用人');
                return;
            }
            
            // 載入庫存資料
            var inventory = [];
            if (window.currentInventory && typeof window.currentInventory === 'function') {
                inventory = window.currentInventory() || [];
            } else if (window.currentPallets && typeof window.currentPallets === 'function') {
                inventory = window.currentPallets() || [];
            }
            
            // 根據篩選條件過濾
            var filter = window.rmStockFilter;
            var sourceData = inventory.filter(function(item) {
                if (!item.productName || (item.quantity || 0) <= 0) return false;
                if (filter !== 'all' && item.company !== filter) return false;
                return true;
            });
            
            if (sourceData.length === 0) {
                alert('目前無可領用的品項');
                return;
            }
            
            window.rmModalState = {
                step: 1, allItems: sourceData,
                selectedProduct: null, selectedSpec: null, selectedBatch: null,
                selectedLocation: null, selectedItem: null
            };
            
            window.rmModalCart = [];
            renderRmModalCart();
            
            document.getElementById('modal-rm-product').classList.remove('hidden');
            document.getElementById('rm-modal-search').value = '';
            document.getElementById('rm-modal-search').placeholder = '搜尋品名...';
            
            updateRmModalSteps(1);
            renderRmModalStep1();
        };

        // 關閉彈窗
        window.closeRmProductModal = function() {
            document.getElementById('modal-rm-product').classList.add('hidden');
        };

        // 更新步驟指示器
        function updateRmModalSteps(currentStep) {
            var steps = ['1', '2', '3', '4', '5'];
            
            steps.forEach(function(s, idx) {
                var tag = document.getElementById('rm-step-tag-' + s);
                if (!tag) return;
                
                var stepNum = idx + 1;
                if (stepNum < currentStep) {
                    tag.className = 'bg-emerald-600 text-white px-2 py-0.5 rounded font-bold';
                } else if (stepNum === currentStep) {
                    tag.className = 'bg-blue-600 text-white px-2 py-0.5 rounded font-bold';
                } else {
                    tag.className = 'text-slate-500';
                }
            });
            
            updateRmBreadcrumb();
            
            var backBtn = document.getElementById('rm-modal-back-btn');
            backBtn.classList.toggle('hidden', currentStep <= 1);
            
            window.rmModalState.step = currentStep;
        }

        // 更新麵包屑
        function updateRmBreadcrumb() {
            var state = window.rmModalState;
            var parts = [];
            
            if (state.selectedProduct) {
                parts.push('<span class="bg-blue-900/80 text-blue-300 px-1.5 py-0.5 rounded text-xs cursor-pointer hover:bg-blue-800" onclick="rmModalGoToStep(1)">' + escapeHtml(state.selectedProduct).substring(0, 10) + '</span>');
            }
            if (state.selectedSpec !== null) {
                parts.push('<i class="fa-solid fa-angle-right text-slate-600 text-[10px]"></i>');
                parts.push('<span class="bg-purple-900/80 text-purple-300 px-1.5 py-0.5 rounded text-xs cursor-pointer hover:bg-purple-800" onclick="rmModalGoToStep(2)">' + escapeHtml(state.selectedSpec || '無規格').substring(0, 8) + '</span>');
            }
            if (state.selectedBatch !== null) {
                parts.push('<i class="fa-solid fa-angle-right text-slate-600 text-[10px]"></i>');
                parts.push('<span class="bg-cyan-900/80 text-cyan-300 px-1.5 py-0.5 rounded text-xs cursor-pointer hover:bg-cyan-800" onclick="rmModalGoToStep(3)">' + escapeHtml(state.selectedBatch || '無批號').substring(0, 8) + '</span>');
            }
            if (state.selectedLocation) {
                parts.push('<i class="fa-solid fa-angle-right text-slate-600 text-[10px]"></i>');
                parts.push('<span class="bg-emerald-900/80 text-emerald-300 px-1.5 py-0.5 rounded text-xs">' + escapeHtml(state.selectedLocation) + '</span>');
            }
            
            var bcEl = document.getElementById('rm-bc-product');
            bcEl.innerHTML = parts.length > 0 ? parts.join('') : '<span class="text-slate-500 text-xs">選擇品項...</span>';
        }

        // 返回上一步
        window.rmModalGoBack = function() {
            var step = window.rmModalState.step;
            if (step > 1) {
                rmModalGoToStep(step - 1);
            }
        };

        // 跳到指定步驟
        window.rmModalGoToStep = function(step) {
            var state = window.rmModalState;
            document.getElementById('rm-modal-search').value = '';
            
            if (step === 1) {
                state.selectedProduct = null; state.selectedSpec = null;
                state.selectedBatch = null; state.selectedLocation = null; state.selectedItem = null;
                document.getElementById('rm-modal-search').placeholder = '搜尋品名...';
                updateRmModalSteps(1);
                renderRmModalStep1();
            } else if (step === 2 && state.selectedProduct) {
                state.selectedSpec = null; state.selectedBatch = null;
                state.selectedLocation = null; state.selectedItem = null;
                document.getElementById('rm-modal-search').placeholder = '搜尋規格...';
                updateRmModalSteps(2);
                renderRmModalStep2();
            } else if (step === 3 && state.selectedSpec !== null) {
                state.selectedBatch = null; state.selectedLocation = null; state.selectedItem = null;
                document.getElementById('rm-modal-search').placeholder = '搜尋批號...';
                updateRmModalSteps(3);
                renderRmModalStep3();
            } else if (step === 4 && state.selectedBatch !== null) {
                state.selectedLocation = null; state.selectedItem = null;
                document.getElementById('rm-modal-search').placeholder = '搜尋儲位...';
                updateRmModalSteps(4);
                renderRmModalStep4();
            }
        };

        // 過濾列表
        window.filterRmModalList = function() {
            var step = window.rmModalState.step;
            if (step === 1) renderRmModalStep1();
            else if (step === 2) renderRmModalStep2();
            else if (step === 3) renderRmModalStep3();
            else if (step === 4) renderRmModalStep4();
        };

        // Step 1: 選擇品名
        function renderRmModalStep1() {
            var keyword = (document.getElementById('rm-modal-search').value || '').trim().toLowerCase();
            var items = window.rmModalState.allItems;
            var productMap = {};
            
            items.forEach(function(item) {
                var name = item.productName || '';
                if (keyword && !name.toLowerCase().includes(keyword)) return;
                if (!productMap[name]) productMap[name] = { name: name, count: 0, totalQty: 0 };
                productMap[name].count++;
                productMap[name].totalQty += item.quantity || 0;
            });
            
            var products = Object.values(productMap).sort(function(a, b) {
                return a.name.localeCompare(b.name, 'zh-TW');
            });
            
            var listArea = document.getElementById('rm-modal-list-area');
            if (products.length === 0) {
                listArea.innerHTML = '<div class="text-center text-slate-500 py-8"><i class="fa-solid fa-inbox text-3xl mb-2"></i><div class="text-sm">無符合項目</div></div>';
                return;
            }
            
            var html = '<div class="space-y-1">';
            products.forEach(function(p) {
                html += '<div class="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded px-3 py-2 cursor-pointer flex justify-between items-center" onclick="selectRmModalProduct(\'' + escapeHtml(p.name) + '\')">';
                html += '<span class="text-white text-sm font-medium truncate flex-1">' + escapeHtml(p.name) + '</span>';
                html += '<div class="flex items-center gap-2 ml-2"><span class="text-yellow-400 font-bold text-sm">' + p.totalQty + '</span><i class="fa-solid fa-chevron-right text-slate-500 text-xs"></i></div>';
                html += '</div>';
            });
            html += '</div>';
            listArea.innerHTML = html;
        }

        window.selectRmModalProduct = function(productName) {
            window.rmModalState.selectedProduct = productName;
            document.getElementById('rm-modal-search').value = '';
            document.getElementById('rm-modal-search').placeholder = '搜尋規格...';
            updateRmModalSteps(2);
            renderRmModalStep2();
        };

        // Step 2: 選擇規格
        function renderRmModalStep2() {
            var keyword = (document.getElementById('rm-modal-search').value || '').trim().toLowerCase();
            var items = window.rmModalState.allItems;
            var selectedProduct = window.rmModalState.selectedProduct;
            var specMap = {};
            
            items.forEach(function(item) {
                if (item.productName !== selectedProduct) return;
                var spec = item.spec || '';
                if (keyword && !spec.toLowerCase().includes(keyword)) return;
                var key = spec || '__empty__';
                if (!specMap[key]) specMap[key] = { spec: spec, count: 0, totalQty: 0 };
                specMap[key].count++;
                specMap[key].totalQty += item.quantity || 0;
            });
            
            var specs = Object.values(specMap).sort(function(a, b) {
                if (a.spec === '') return -1;
                if (b.spec === '') return 1;
                return a.spec.localeCompare(b.spec, 'zh-TW');
            });
            
            var listArea = document.getElementById('rm-modal-list-area');
            if (specs.length === 0) {
                listArea.innerHTML = '<div class="text-center text-slate-500 py-8"><i class="fa-solid fa-inbox text-3xl mb-2"></i><div class="text-sm">無符合項目</div></div>';
                return;
            }
            
            var html = '<div class="space-y-1">';
            specs.forEach(function(s) {
                var displaySpec = s.spec || '(無規格)';
                html += '<div class="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded px-3 py-2 cursor-pointer flex justify-between items-center" onclick="selectRmModalSpec(\'' + escapeHtml(s.spec) + '\')">';
                html += '<span class="text-white text-sm font-medium truncate flex-1">' + escapeHtml(displaySpec) + '</span>';
                html += '<div class="flex items-center gap-2 ml-2"><span class="text-yellow-400 font-bold text-sm">' + s.totalQty + '</span><i class="fa-solid fa-chevron-right text-slate-500 text-xs"></i></div>';
                html += '</div>';
            });
            html += '</div>';
            listArea.innerHTML = html;
        }

        window.selectRmModalSpec = function(spec) {
            window.rmModalState.selectedSpec = spec;
            document.getElementById('rm-modal-search').value = '';
            document.getElementById('rm-modal-search').placeholder = '搜尋批號...';
            updateRmModalSteps(3);
            renderRmModalStep3();
        };

        // Step 3: 選擇批號
        function renderRmModalStep3() {
            var keyword = (document.getElementById('rm-modal-search').value || '').trim().toLowerCase();
            var items = window.rmModalState.allItems;
            var state = window.rmModalState;
            var batchMap = {};
            
            items.forEach(function(item) {
                if (item.productName !== state.selectedProduct) return;
                if ((item.spec || '') !== state.selectedSpec) return;
                var batch = item.batchNo || '';
                if (keyword && !batch.toLowerCase().includes(keyword)) return;
                var key = batch || '__empty__';
                var expDate = item.expiryDate;
                if (expDate && expDate.toDate) expDate = expDate.toDate();
                if (expDate && typeof expDate === 'object') expDate = expDate.toLocalYMD();
                
                if (!batchMap[key]) {
                    batchMap[key] = { batch: batch, expDate: expDate || '', count: 0, totalQty: 0, items: [] };
                }
                batchMap[key].count++;
                batchMap[key].totalQty += item.quantity || 0;
                batchMap[key].items.push(item);
            });
            
            var batches = Object.values(batchMap).sort(function(a, b) {
                if (a.expDate && b.expDate) return a.expDate.localeCompare(b.expDate);
                return a.batch.localeCompare(b.batch, 'zh-TW');
            });
            
            var listArea = document.getElementById('rm-modal-list-area');
            if (batches.length === 0) {
                listArea.innerHTML = '<div class="text-center text-slate-500 py-8"><i class="fa-solid fa-inbox text-3xl mb-2"></i><div class="text-sm">無符合項目</div></div>';
                return;
            }
            
            var html = '<div class="space-y-1">';
            batches.forEach(function(b) {
                var displayBatch = b.batch || '(無批號)';
                var expClass = 'text-slate-400';
                if (b.expDate) {
                    var days = Math.floor((new Date(b.expDate) - new Date()) / 86400000);
                    if (days < 0) expClass = 'text-red-400';
                    else if (days < 30) expClass = 'text-orange-400';
                    else if (days < 90) expClass = 'text-yellow-400';
                }
                
                html += '<div class="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded px-3 py-2 cursor-pointer" onclick="selectRmModalBatch(\'' + escapeHtml(b.batch) + '\')">';
                html += '<div class="flex justify-between items-center">';
                html += '<div class="flex-1 min-w-0"><span class="text-white text-sm font-medium">' + escapeHtml(displayBatch) + '</span>';
                if (b.expDate) html += '<span class="text-xs ' + expClass + ' ml-2">' + b.expDate + '</span>';
                html += '</div>';
                html += '<div class="flex items-center gap-2 ml-2"><span class="text-yellow-400 font-bold text-sm">' + b.totalQty + '</span><i class="fa-solid fa-chevron-right text-slate-500 text-xs"></i></div>';
                html += '</div></div>';
            });
            html += '</div>';
            listArea.innerHTML = html;
        }

        window.selectRmModalBatch = function(batch) {
            window.rmModalState.selectedBatch = batch;
            document.getElementById('rm-modal-search').value = '';
            document.getElementById('rm-modal-search').placeholder = '搜尋儲位...';
            updateRmModalSteps(4);
            renderRmModalStep4();
        };

        // Step 4: 選擇儲位
        function renderRmModalStep4() {
            var keyword = (document.getElementById('rm-modal-search').value || '').trim().toLowerCase();
            var state = window.rmModalState;
            
            var locations = state.allItems.filter(function(item) {
                if (item.productName !== state.selectedProduct) return false;
                if ((item.spec || '') !== state.selectedSpec) return false;
                if ((item.batchNo || '') !== state.selectedBatch) return false;
                if (keyword && !(item.locationId || '').toLowerCase().includes(keyword)) return false;
                return true;
            });
            
            var listArea = document.getElementById('rm-modal-list-area');
            if (locations.length === 0) {
                listArea.innerHTML = '<div class="text-center text-slate-500 py-8"><i class="fa-solid fa-inbox text-3xl mb-2"></i><div class="text-sm">無符合項目</div></div>';
                return;
            }
            
            var html = '<div class="grid grid-cols-3 gap-2">';
            locations.forEach(function(loc) {
                html += '<div class="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded p-2 cursor-pointer text-center" onclick="selectRmModalLocation(\'' + escapeHtml(loc.id || '') + '\')">';
                html += '<div class="text-emerald-400 font-bold text-sm">' + escapeHtml(loc.locationId || '-') + '</div>';
                html += '<div class="text-yellow-400 font-bold">' + (loc.quantity || 0) + '</div>';
                html += '</div>';
            });
            html += '</div>';
            listArea.innerHTML = html;
        }

        window.selectRmModalLocation = function(itemId) {
            var state = window.rmModalState;
            var selectedItem = state.allItems.find(function(i) {
                return i.id === itemId &&
                       i.productName === state.selectedProduct &&
                       (i.spec || '') === state.selectedSpec &&
                       (i.batchNo || '') === state.selectedBatch;
            });
            if (selectedItem) {
                state.selectedLocation = selectedItem.locationId;
                state.selectedItem = selectedItem;
                updateRmModalSteps(5);
                renderRmModalStep5();
            }
        };

        // Step 5: 輸入數量
        function renderRmModalStep5() {
            var state = window.rmModalState;
            var item = state.selectedItem;
            if (!item) return;
            
            var maxQty = item.quantity || 0;
            var expDate = item.expiryDate;
            if (expDate && expDate.toDate) expDate = expDate.toDate();
            if (expDate && typeof expDate === 'object') expDate = expDate.toLocalYMD();
            
            var html = '<div class="max-w-sm mx-auto space-y-3">';
            
            // 品項摘要
            html += '<div class="bg-slate-800 border border-slate-700 rounded-lg p-3 text-sm">';
            html += '<div class="text-white font-bold truncate">' + escapeHtml(state.selectedProduct) + '</div>';
            html += '<div class="text-slate-400 text-xs mt-1">' + escapeHtml(state.selectedSpec || '無規格') + ' | ' + escapeHtml(state.selectedBatch || '無批號') + '</div>';
            html += '<div class="text-emerald-400 text-xs mt-0.5"><i class="fa-solid fa-location-dot mr-1"></i>' + escapeHtml(state.selectedLocation) + '</div>';
            if (expDate) html += '<div class="text-yellow-400 text-xs mt-0.5"><i class="fa-solid fa-calendar mr-1"></i>效期: ' + expDate + '</div>';
            html += '<div class="flex justify-between items-center mt-2 pt-2 border-t border-slate-700">';
            html += '<span class="text-slate-400 text-xs">可領數量</span><span class="text-yellow-400 font-bold text-lg">' + maxQty + '</span>';
            html += '</div></div>';
            
            // 數量輸入
            html += '<div class="bg-cyan-900/30 border border-cyan-600/50 rounded-lg p-3">';
            html += '<div class="flex items-center gap-2">';
            html += '<button onclick="adjustRmQty(-10)" class="w-9 h-9 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-sm">-10</button>';
            html += '<button onclick="adjustRmQty(-1)" class="w-9 h-9 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold">-1</button>';
            html += '<input type="number" id="rm-modal-qty" class="flex-1 scan-input text-center text-xl font-bold h-10" value="' + maxQty + '" min="1" max="' + maxQty + '">';
            html += '<button onclick="adjustRmQty(1)" class="w-9 h-9 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold">+1</button>';
            html += '<button onclick="adjustRmQty(10)" class="w-9 h-9 bg-slate-700 hover:bg-slate-600 text-white rounded font-bold text-sm">+10</button>';
            html += '</div>';
            html += '<div class="flex gap-2 mt-2">';
            html += '<button onclick="setRmQtyMax()" class="flex-1 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded text-xs font-bold">全部</button>';
            html += '<button onclick="setRmQtyHalf()" class="flex-1 py-1.5 bg-slate-700 hover:bg-slate-600 text-white rounded text-xs font-bold">一半</button>';
            html += '</div></div>';
            
            // 按鈕
            html += '<button onclick="addToRmModalCart()" class="w-full py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg font-bold text-sm"><i class="fa-solid fa-cart-plus mr-1"></i>加入已選</button>';
            html += '<button onclick="rmModalGoToStep(1)" class="w-full py-2 bg-slate-700 hover:bg-slate-600 text-white rounded text-xs"><i class="fa-solid fa-plus mr-1"></i>繼續選擇其他品項</button>';
            html += '</div>';
            
            document.getElementById('rm-modal-list-area').innerHTML = html;
        }

        window.adjustRmQty = function(delta) {
            var input = document.getElementById('rm-modal-qty');
            var max = parseInt(input.max) || 9999;
            var newVal = Math.max(1, Math.min(max, (parseInt(input.value) || 0) + delta));
            input.value = newVal;
        };

        window.setRmQtyMax = function() {
            var input = document.getElementById('rm-modal-qty');
            input.value = input.max;
        };

        window.setRmQtyHalf = function() {
            var input = document.getElementById('rm-modal-qty');
            input.value = Math.ceil((parseInt(input.max) || 0) / 2);
        };

        // 加入彈窗購物車
        window.addToRmModalCart = function() {
            var state = window.rmModalState;
            var item = state.selectedItem;
            var qtyInput = document.getElementById('rm-modal-qty');
            var qty = parseInt(qtyInput.value) || 0;
            var maxQty = parseInt(qtyInput.max) || 0;
            
            if (qty <= 0) { alert('請輸入有效數量'); return; }
            if (qty > maxQty) { alert('數量不能超過 ' + maxQty); return; }
            
            var expDate = item.expiryDate;
            if (expDate && expDate.toDate) expDate = expDate.toDate();
            if (expDate && typeof expDate === 'object') expDate = expDate.toLocalYMD();
            
            window.rmModalCart.push({
                id: item.id,
                productName: state.selectedProduct,
                spec: state.selectedSpec || '',
                batchNo: state.selectedBatch || '',
                expDate: expDate || '',
                locationId: state.selectedLocation || '',
                quantity: qty,
                maxQty: maxQty,
                company: item.company || '崇文',
                totalWeight: item.totalWeight || 0,
                sourceItem: item
            });
            
            renderRmModalCart();
            showNotification('✅ 已加入 ' + qty + ' 件', 'success');
            
            state.selectedProduct = null; state.selectedSpec = null;
            state.selectedBatch = null; state.selectedLocation = null; state.selectedItem = null;
            
            document.getElementById('rm-modal-search').value = '';
            document.getElementById('rm-modal-search').placeholder = '搜尋品名...';
            updateRmModalSteps(1);
            renderRmModalStep1();
        };

        // 渲染彈窗購物車
        function renderRmModalCart() {
            var cartList = document.getElementById('rm-modal-cart-list');
            var cartCount = document.getElementById('rm-modal-cart-count');
            var confirmBtn = document.getElementById('rm-modal-confirm-btn');
            
            cartCount.textContent = window.rmModalCart.length;
            
            if (window.rmModalCart.length === 0) {
                cartList.innerHTML = '<div class="text-center text-slate-500 py-6 text-xs"><i class="fa-solid fa-inbox text-xl mb-1 opacity-50"></i><div>尚未選擇</div></div>';
                confirmBtn.disabled = true;
                return;
            }
            
            confirmBtn.disabled = false;
            var totalQty = 0;
            
            var html = '<div class="space-y-1">';
            window.rmModalCart.forEach(function(item, idx) {
                totalQty += item.quantity;
                html += '<div class="bg-slate-800 border border-slate-700 rounded p-1.5 relative text-xs">';
                html += '<button onclick="removeFromRmModalCart(' + idx + ')" class="absolute -top-1 -right-1 w-4 h-4 bg-red-600 hover:bg-red-500 text-white rounded-full text-[10px] flex items-center justify-center"><i class="fa-solid fa-times"></i></button>';
                html += '<div class="text-white font-bold truncate pr-3">' + escapeHtml(item.productName).substring(0, 12) + '</div>';
                html += '<div class="flex justify-between items-center mt-0.5">';
                html += '<span class="text-emerald-400 truncate">' + escapeHtml(item.locationId) + '</span>';
                html += '<span class="text-yellow-400 font-bold">' + item.quantity + '</span>';
                html += '</div></div>';
            });
            html += '</div>';
            html += '<div class="mt-2 pt-2 border-t border-slate-600 flex justify-between items-center text-xs">';
            html += '<span class="text-slate-400 font-bold">合計</span>';
            html += '<span class="text-yellow-400 font-bold">' + totalQty + ' 件</span>';
            html += '</div>';
            
            cartList.innerHTML = html;
        }

        window.removeFromRmModalCart = function(idx) {
            window.rmModalCart.splice(idx, 1);
            renderRmModalCart();
        };

        // 確認彈窗購物車，加入主清單
        window.confirmRmModalCart = function() {
            if (window.rmModalCart.length === 0) { alert('請先選擇品項'); return; }
            
            window.rmModalCart.forEach(function(item) {
                window.rmPickingCart.push(Object.assign({}, item));
            });
            
            renderRmCartDisplay();
            showNotification('✅ 已加入 ' + window.rmModalCart.length + ' 筆到領用清單', 'success');
            
            window.rmModalCart = [];
            closeRmProductModal();
            updateRmStepStatus();
        };

        // 渲染主頁面的領用清單
        function renderRmCartDisplay() {
            var cartDisplay = document.getElementById('rm-cart-display');
            var countDisplay = document.getElementById('rm-cart-count-display');
            var qtyDisplay = document.getElementById('rm-cart-qty-display');
            
            if (window.rmPickingCart.length === 0) {
                cartDisplay.innerHTML = '<div class="text-center text-slate-500 py-10"><i class="fa-solid fa-inbox text-4xl mb-3 opacity-50"></i><div>尚未選擇品項</div><div class="text-xs mt-1">點擊「選擇品項」開始添加</div></div>';
                countDisplay.textContent = '0';
                qtyDisplay.textContent = '0';
                return;
            }
            
            var totalQty = 0;
            var html = '<div class="space-y-2">';
            
            window.rmPickingCart.forEach(function(item, idx) {
                totalQty += item.quantity;
                var expClass = 'text-slate-400';
                if (item.expDate) {
                    var days = Math.floor((new Date(item.expDate) - new Date()) / 86400000);
                    if (days < 0) expClass = 'text-red-400';
                    else if (days < 30) expClass = 'text-orange-400';
                    else if (days < 90) expClass = 'text-yellow-400';
                }
                
                html += '<div class="bg-slate-800 border border-slate-700 rounded-lg p-3 relative">';
                html += '<button onclick="removeFromRmCart(' + idx + ')" class="absolute top-2 right-2 w-6 h-6 bg-red-600/80 hover:bg-red-500 text-white rounded-full text-xs flex items-center justify-center"><i class="fa-solid fa-times"></i></button>';
                html += '<div class="flex items-start gap-3">';
                html += '<div class="flex-1">';
                html += '<div class="text-white font-bold">' + escapeHtml(item.productName) + '</div>';
                html += '<div class="text-slate-400 text-xs mt-1">' + escapeHtml(item.spec || '無規格') + ' | 批號: ' + escapeHtml(item.batchNo || '無') + '</div>';
                html += '<div class="flex items-center gap-3 mt-1 text-xs">';
                html += '<span class="text-emerald-400"><i class="fa-solid fa-location-dot mr-1"></i>' + escapeHtml(item.locationId) + '</span>';
                if (item.expDate) html += '<span class="' + expClass + '"><i class="fa-solid fa-calendar mr-1"></i>' + item.expDate + '</span>';
                html += '</div>';
                html += '</div>';
                html += '<div class="text-right">';
                html += '<div class="text-yellow-400 font-bold text-xl">' + item.quantity + '</div>';
                html += '<div class="text-slate-500 text-xs">件</div>';
                html += '</div>';
                html += '</div></div>';
            });
            html += '</div>';
            
            cartDisplay.innerHTML = html;
            countDisplay.textContent = window.rmPickingCart.length;
            qtyDisplay.textContent = totalQty;
        }

        window.removeFromRmCart = function(idx) {
            window.rmPickingCart.splice(idx, 1);
            renderRmCartDisplay();
            updateRmStepStatus();
        };

        window.clearRmCart = function() {
            if (window.rmPickingCart.length === 0) return;
            if (!confirm('確定要清空領用清單嗎？')) return;
            window.rmPickingCart = [];
            renderRmCartDisplay();
            updateRmStepStatus();
        };

        // 從購物車確認領料
        window.confirmRmPickingFromCart = function() {
            var user = (document.getElementById('rm-pick-user').value || '').trim();
            if (!user) { alert('請填寫領用人'); return; }
            if (window.rmPickingCart.length === 0) { alert('請選擇領用品項'); return; }
            
            // 轉換為舊格式，複用既有的確認邏輯
            window.rmStockSelected = {};
            window.rmPickingCart.forEach(function(item) {
                var key = 'rm_' + item.id;
                window.rmStockSelected[key] = {
                    item: {
                        id: item.id,
                        company: item.company,
                        productName: item.productName,
                        spec: item.spec,
                        batchNo: item.batchNo,
                        locationId: item.locationId,
                        quantity: item.maxQty,
                        availableQty: item.maxQty,
                        totalWeight: item.totalWeight,
                        expDate: item.expDate
                    },
                    qty: item.quantity
                };
            });
            
            // 呼叫既有的確認函數
            confirmRmPickingNew();
        };

        // 列印領料單（從購物車）
        window.printRmPickingListFromCart = function() {
            if (window.rmPickingCart.length === 0) {
                alert('請先選擇領用品項');
                return;
            }
            
            // 轉換為舊格式
            window.rmStockSelected = {};
            window.rmPickingCart.forEach(function(item) {
                var key = 'rm_' + item.id;
                window.rmStockSelected[key] = {
                    item: {
                        id: item.id,
                        company: item.company,
                        productName: item.productName,
                        spec: item.spec,
                        batchNo: item.batchNo,
                        locationId: item.locationId,
                        quantity: item.maxQty,
                        totalWeight: item.totalWeight,
                        expDate: item.expDate
                    },
                    qty: item.quantity
                };
            });
            
            printRmPickingList();
        };

        // 載入原料庫存資料（全部庫存）
        window.loadRmStockData = function() {
            var inventory = [];
            
            // 優先使用 currentInventory，否則使用 currentPallets
            if (window.currentInventory && typeof window.currentInventory === 'function') {
                inventory = window.currentInventory() || [];
            } else if (window.currentPallets && typeof window.currentPallets === 'function') {
                inventory = window.currentPallets() || [];
            }
            
            // 如果還沒有資料，等一下再試
            if (inventory.length === 0) {
                var tbody = document.getElementById('rm-stock-tbody');
                if (tbody) {
                    tbody.innerHTML = '<tr><td colspan="11" class="text-center text-slate-500 py-10"><i class="fa-solid fa-spinner fa-spin text-3xl mb-2"></i><br>正在載入庫存資料...</td></tr>';
                }
                setTimeout(loadRmStockData, 500);
                return;
            }
            
            // 建立寄庫對照表
            var consignmentByLocation = {};
            if (window.consignmentData && Array.isArray(window.consignmentData)) {
                window.consignmentData.forEach(function(c) {
                    if (c.status !== 'active' || !c.locationId) return;
                    if (!consignmentByLocation[c.locationId]) {
                        consignmentByLocation[c.locationId] = { qty: 0, customers: [] };
                    }
                    consignmentByLocation[c.locationId].qty += (c.remainingQty || 0);
                    if (c.customer && consignmentByLocation[c.locationId].customers.indexOf(c.customer) === -1) {
                        consignmentByLocation[c.locationId].customers.push(c.customer);
                    }
                });
            }
            
            window.rmStockData = [];
            
            inventory.forEach(function(item) {
                if (!item.productName || (item.quantity || 0) <= 0) return;
                
                var locationId = item.locationId || '';
                var consignInfo = consignmentByLocation[locationId] || { qty: 0, customers: [] };
                var consignedQty = consignInfo.qty;
                var availableQty = Math.max(0, item.quantity - consignedQty);
                
                // 效期處理
                var expDate = '';
                var daysRemaining = 999;
                if (item.expiryDate) {
                    var exp = item.expiryDate.toDate ? item.expiryDate.toDate() : new Date(item.expiryDate);
                    expDate = exp.toLocaleDateString('zh-TW');
                    daysRemaining = Math.ceil((exp - new Date()) / (1000 * 60 * 60 * 24));
                }
                
                var uniqueKey = 'rm_' + item.id;
                
                window.rmStockData.push({
                    id: item.id,
                    key: uniqueKey,
                    company: item.company || '崇文',
                    productName: item.productName,
                    spec: item.spec || '',
                    batchNo: item.batchNo || '',
                    locationId: locationId,
                    quantity: item.quantity || 0,
                    consignedQty: consignedQty,
                    consignCustomers: consignInfo.customers,
                    availableQty: availableQty,
                    expDate: expDate,
                    daysRemaining: daysRemaining,
                    totalWeight: item.totalWeight || 0
                });
            });
            
            // 排序：效期近的優先，同效期按品名
            window.rmStockData.sort(function(a, b) {
                if (a.daysRemaining !== b.daysRemaining) return a.daysRemaining - b.daysRemaining;
                return (a.productName || '').localeCompare(b.productName || '', 'zh-TW');
            });
            
            renderRmStockTable();
        };

        // 篩選原料庫存（全部/崇文/八方）
        window.filterRmStock = function(filter) {
            window.rmStockFilter = filter;
            
            document.getElementById('btn-rm-all').className = filter === 'all'
                ? 'px-3 py-1 rounded text-xs font-bold bg-cyan-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            document.getElementById('btn-rm-cw').className = filter === '崇文'
                ? 'px-3 py-1 rounded text-xs font-bold bg-blue-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            document.getElementById('btn-rm-bf').className = filter === '八方'
                ? 'px-3 py-1 rounded text-xs font-bold bg-purple-600 text-white'
                : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            
            renderRmStockTable();
        };

        // 渲染原料庫存表格
        window.renderRmStockTable = function() {
            var tbody = document.getElementById('rm-stock-tbody');
            if (!tbody) return;
            
            var search = (document.getElementById('rm-stock-search')?.value || '').toLowerCase();
            var filter = window.rmStockFilter || 'all';
            
            var filtered = window.rmStockData.filter(function(item) {
                // 公司篩選
                if (filter !== 'all' && item.company !== filter) return false;
                
                // 搜尋篩選
                if (search) {
                    var match = (item.productName || '').toLowerCase().indexOf(search) >= 0 ||
                                (item.spec || '').toLowerCase().indexOf(search) >= 0 ||
                                (item.batchNo || '').toLowerCase().indexOf(search) >= 0 ||
                                (item.locationId || '').toLowerCase().indexOf(search) >= 0 ||
                                (item.company || '').toLowerCase().indexOf(search) >= 0;
                    if (!match) return false;
                }
                return true;
            });
            
            if (filtered.length === 0) {
                tbody.innerHTML = '<tr><td colspan="11" class="text-center text-slate-500 py-10"><i class="fa-solid fa-inbox text-3xl mb-2"></i><br>無符合條件的庫存</td></tr>';
                return;
            }
            
            var html = '';
            filtered.forEach(function(item) {
                var isSelected = window.rmStockSelected[item.key];
                var selectedQty = isSelected ? isSelected.qty : 0;
                var hasConsign = item.consignedQty > 0;
                var isExpiring = item.daysRemaining <= 30;
                var isExpired = item.daysRemaining < 0;
                
                var rowClass = 'border-b border-slate-800 hover:bg-slate-800';
                if (hasConsign) rowClass += ' bg-amber-900/20';
                if (isSelected) rowClass += ' bg-cyan-900/30';
                
                var expClass = 'text-slate-400';
                if (isExpired) expClass = 'text-red-400 font-bold';
                else if (isExpiring) expClass = 'text-yellow-400';
                
                html += '<tr class="' + rowClass + '">';
                
                // 勾選
                html += '<td class="p-2 text-center">';
                html += '<input type="checkbox" class="rm-item-checkbox w-5 h-5" data-key="' + item.key + '" ';
                html += (isSelected ? 'checked' : '') + ' ';
                html += (item.availableQty <= 0 ? 'disabled' : '') + ' ';
                html += 'onchange="toggleRmItem(\'' + item.key + '\', this.checked)">';
                html += '</td>';
                
                // 公司
                var companyClass = item.company === '八方' ? 'text-purple-400' : 'text-blue-400';
                html += '<td class="p-2 ' + companyClass + ' font-bold">' + item.company + '</td>';
                
                // 品名
                html += '<td class="p-2 text-white font-bold">' + item.productName + '</td>';
                
                // 規格
                html += '<td class="p-2 text-yellow-400">' + (item.spec || '-') + '</td>';
                
                // 批號
                html += '<td class="p-2 text-slate-400 font-mono text-xs">' + (item.batchNo || '-') + '</td>';
                
                // 數量
                html += '<td class="p-2 text-right text-white">' + item.quantity + '</td>';
                
                // 重量
                var weightDisplay = item.totalWeight > 0 ? item.totalWeight + ' kg' : '-';
                html += '<td class="p-2 text-right text-slate-400">' + weightDisplay + '</td>';
                
                // 位置
                html += '<td class="p-2 text-cyan-400 font-mono">' + item.locationId + '</td>';
                
                // 效期
                html += '<td class="p-2 ' + expClass + '">';
                html += item.expDate || '-';
                if (isExpired) html += ' <span class="text-[10px]">(過期)</span>';
                else if (isExpiring) html += ' <span class="text-[10px]">(' + item.daysRemaining + '天)</span>';
                html += '</td>';
                
                // 寄庫客戶（含可領數量）
                if (hasConsign) {
                    html += '<td class="p-2">';
                    html += '<span class="text-amber-400">' + item.consignCustomers.join(',') + '</span>';
                    html += '<br><span class="text-green-400 text-xs">可領 ' + item.availableQty + '</span>';
                    html += '</td>';
                } else {
                    html += '<td class="p-2 text-slate-600">-</td>';
                }
                
                // 領用數量
                html += '<td class="p-2 text-center">';
                if (item.availableQty > 0) {
                    html += '<input type="number" class="scan-input w-20 text-center font-bold ' + (hasConsign ? 'border-amber-500/50' : '') + '" ';
                    html += 'data-key="' + item.key + '" ';
                    html += 'value="' + selectedQty + '" ';
                    html += 'min="0" max="' + item.availableQty + '" ';
                    html += 'onchange="updateRmItemQty(\'' + item.key + '\', this.value)" ';
                    html += 'onfocus="this.select()">';
                } else {
                    html += '<span class="text-slate-600">-</span>';
                }
                html += '</td>';
                
                html += '</tr>';
            });
            
            tbody.innerHTML = html;
        };

        // 全選/取消全選
        window.toggleRmAll = function(checked) {
            window.rmStockData.forEach(function(item) {
                if (item.availableQty <= 0) return;
                if (checked) {
                    window.rmStockSelected[item.key] = { item: item, qty: item.availableQty };
                } else {
                    delete window.rmStockSelected[item.key];
                }
            });
            renderRmStockTable();
            updateRmSelectionStats();
        };

        // 單項勾選
        window.toggleRmItem = function(key, checked) {
            var item = window.rmStockData.find(function(d) { return d.key === key; });
            if (!item) return;
            
            if (checked) {
                var currentQty = window.rmStockSelected[key] ? window.rmStockSelected[key].qty : item.availableQty;
                window.rmStockSelected[key] = { item: item, qty: currentQty || item.availableQty };
            } else {
                delete window.rmStockSelected[key];
            }
            renderRmStockTable();
            updateRmSelectionStats();
        };

        // 更新單項數量
        window.updateRmItemQty = function(key, qty) {
            var item = window.rmStockData.find(function(d) { return d.key === key; });
            if (!item) return;
            
            qty = parseInt(qty) || 0;
            if (qty > item.availableQty) {
                qty = item.availableQty;
                showNotification('⚠️ 最多可領 ' + item.availableQty + ' 件' + (item.consignedQty > 0 ? '（有寄庫）' : ''), 'warning');
            }
            
            if (qty > 0) {
                window.rmStockSelected[key] = { item: item, qty: qty };
                // 自動勾選
                var checkbox = document.querySelector('.rm-item-checkbox[data-key="' + key + '"]');
                if (checkbox) checkbox.checked = true;
            } else {
                delete window.rmStockSelected[key];
                var checkbox = document.querySelector('.rm-item-checkbox[data-key="' + key + '"]');
                if (checkbox) checkbox.checked = false;
            }
            
            updateRmSelectionStats();
        };

        // 更新選擇統計
        window.updateRmSelectionStats = function() {
            var keys = Object.keys(window.rmStockSelected);
            var totalQty = 0;
            keys.forEach(function(key) {
                totalQty += window.rmStockSelected[key].qty || 0;
            });
            
            document.getElementById('rm-selected-count').innerText = keys.length;
            document.getElementById('rm-selected-qty').innerText = totalQty;
            document.getElementById('rm-selected-total').innerText = totalQty;
            
            var btn = document.getElementById('btn-rm-confirm');
            if (btn) btn.disabled = keys.length === 0;
        };

        // 保存領用資訊的全域變數
        window.rmPickingInfo = { user: '', dept: '', note: '' };

        // 確認領料（新版）
        window.confirmRmPickingNew = function() {
            var user = document.getElementById('rm-pick-user')?.value.trim();
            if (!user) {
                alert('請輸入領用人');
                document.getElementById('rm-pick-user')?.focus();
                return;
            }
            
            var dept = document.getElementById('rm-pick-dept')?.value || '';
            var note = document.getElementById('rm-pick-note')?.value || '';
            
            // 保存到全域變數
            window.rmPickingInfo = { user: user, dept: dept, note: note };
            var keys = Object.keys(window.rmStockSelected);
            if (keys.length === 0) {
                alert('請選擇要領用的品項');
                return;
            }
            
            // 建立確認清單
            var html = '<div class="space-y-3 max-h-96 overflow-auto">';
            var totalQty = 0;
            
            keys.forEach(function(key, idx) {
                var sel = window.rmStockSelected[key];
                var item = sel.item;
                totalQty += sel.qty;
                
                var hasConsign = item.consignedQty > 0;
                var companyClass = item.company === '八方' ? 'text-purple-400' : 'text-blue-400';
                
                html += '<div class="bg-slate-800 rounded-lg p-3 ' + (hasConsign ? 'border border-amber-500/50' : '') + '">';
                html += '<div class="flex justify-between items-start">';
                html += '<div>';
                html += '<span class="' + companyClass + ' text-xs font-bold mr-2">[' + item.company + ']</span>';
                html += '<span class="text-white font-bold">' + item.productName + '</span>';
                html += '<div class="text-slate-400 text-sm">' + (item.spec || '-') + ' | ' + (item.batchNo || '-') + '</div>';
                if (hasConsign) {
                    html += '<div class="text-amber-400 text-xs mt-1">⚠️ 寄庫 ' + item.consignedQty + ' 件（' + item.consignCustomers.join(',') + '）</div>';
                }
                html += '</div>';
                html += '<div class="text-right">';
                html += '<div class="text-cyan-400 font-mono">' + item.locationId + '</div>';
                html += '<div class="text-yellow-400 font-bold text-xl">' + sel.qty + ' 件</div>';
                if (sel.qty < item.quantity) {
                    html += '<div class="text-slate-500 text-xs">餘 ' + (item.quantity - sel.qty) + ' 件</div>';
                }
                html += '</div>';
                html += '</div>';
                html += '</div>';
            });
            
            html += '</div>';
            
            html += '<div class="mt-4 p-3 bg-slate-900 rounded-lg">';
            html += '<div class="grid grid-cols-3 gap-3 text-sm">';
            html += '<div><span class="text-slate-500">領用人：</span><span class="text-white">' + user + '</span></div>';
            html += '<div><span class="text-slate-500">單位：</span><span class="text-white">' + (dept || '-') + '</span></div>';
            html += '<div><span class="text-slate-500">備註：</span><span class="text-white">' + (note || '-') + '</span></div>';
            html += '</div>';
            html += '<div class="mt-2 pt-2 border-t border-slate-700 flex justify-between">';
            html += '<span class="text-slate-400">共 ' + keys.length + ' 筆</span>';
            html += '<span class="text-yellow-400 font-bold text-lg">總計 ' + totalQty + ' 件</span>';
            html += '</div>';
            html += '</div>';
            
            WMS.createModal('rm-confirm-modal', {
                title: '確認原料領用',
                icon: 'fa-solid fa-clipboard-check text-emerald-400',
                content: html,
                width: '600px',
                footer: `
                    <button onclick="WMS.closeModal('rm-confirm-modal')" class="px-4 py-2 bg-slate-600 hover:bg-slate-500 text-white rounded">取消</button>
                    <button onclick="executeRmPicking()" class="px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded font-bold">
                        <i class="fa-solid fa-check mr-1"></i>確認出庫
                    </button>
                `
            });
        };

        // 執行原料領用出庫
        window.executeRmPicking = async function() {
            // 使用保存的領用資訊
            var info = window.rmPickingInfo || {};
            var user = info.user || '';
            var dept = info.dept || '';
            var note = info.note || '';
            var keys = Object.keys(window.rmStockSelected);
            
            try {
                var totalQty = 0;
                var count = 0;
                var changes = [];
                var picks = [];

                keys.forEach(function(key) {
                    var sel = window.rmStockSelected[key];
                    var pickQty = parseFloat(sel.qty) || 0;
                    if (pickQty <= 0) return;
                    var ref = window.doc(window.db, 'pallets', sel.item.id);
                    changes.push({ ref: ref, delta: -pickQty, deleteWhenEmpty: true, label: sel.item.palletId || sel.item.productName });
                    picks.push({ ref: ref, pickQty: pickQty });
                    count++;
                    totalQty += pickQty;
                });

                // 全部品項在同一個交易裡扣帳：任何一板庫存不足就整筆取消
                await window.runStockTransaction({
                    changes: changes,
                    logs: function(results) {
                        return picks.map(function(pk) {
                            var item = results[pk.ref.path].data;
                            return {
                                type: 'picking-rm',
                                company: item.company || '崇文',
                                productName: item.productName,
                                spec: item.spec,
                                batchNo: item.batchNo,
                                quantity: -pk.pickQty,
                                quantityChange: -pk.pickQty,
                                locationId: item.locationId,
                                palletId: item.palletId || '',
                                note: '原料領用 - ' + user + (dept ? ' (' + dept + ')' : '') + (note ? ' - ' + note : ''),
                                operator: user
                            };
                        });
                    }
                });

                WMS.closeModal('rm-confirm-modal');
                showNotification('✅ 原料領用完成！共 ' + count + ' 筆 ' + totalQty + ' 件，正在列印...', 'success');
                
                // 先列印領料單（需要用到 rmStockSelected 資料）
                printRmPickingList();
                
                // 列印後清空選擇
                window.rmStockSelected = {};
                window.rmPickingCart = [];
                window.rmPickingInfo = { user: '', dept: '', note: '' };
                document.getElementById('rm-pick-user').value = '';
                document.getElementById('rm-pick-dept').value = '';
                document.getElementById('rm-pick-note').value = '';
                
                // 更新顯示
                renderRmCartDisplay();
                updateRmStepStatus();
                
                // 重新載入
                setTimeout(loadRmStockData, 500);
                
            } catch (e) {
                console.error('原料領用失敗:', e);
                alert('❌ 原料領用失敗：' + e.message);
            }
        };

        // 列印領料單
        window.printRmPickingList = function() {
            var keys = Object.keys(window.rmStockSelected);
            if (keys.length === 0) {
                alert('請先選擇要領用的品項');
                return;
            }
            
            // 使用保存的領用資訊
            var info = window.rmPickingInfo || {};
            var user = info.user || document.getElementById('rm-pick-user')?.value || '';
            var dept = info.dept || document.getElementById('rm-pick-dept')?.value || '';
            
            var html = '<html><head><title>原料領用單</title><style>';
            html += 'body { font-family: sans-serif; padding: 20px; }';
            html += 'h1 { text-align: center; margin-bottom: 10px; }';
            html += '.info { margin-bottom: 15px; }';
            html += 'table { width: 100%; border-collapse: collapse; }';
            html += 'th, td { border: 1px solid #333; padding: 8px; text-align: left; }';
            html += 'th { background: #eee; }';
            html += '.right { text-align: right; }';
            html += '.sign { margin-top: 40px; display: flex; justify-content: space-around; }';
            html += '.sign div { width: 150px; border-top: 1px solid #333; text-align: center; padding-top: 5px; }';
            html += '</style></head><body>';
            
            html += '<h1>原料領用單</h1>';
            html += '<div class="info">';
            html += '<div>領用人：' + (user || '___') + ' | 單位：' + (dept || '___') + '</div>';
            html += '<div>日期：' + new Date().toLocaleString('zh-TW') + '</div>';
            html += '</div>';
            
            html += '<table><thead><tr>';
            html += '<th>公司</th><th>品名</th><th>規格</th><th>批號</th><th>儲位</th><th class="right">領用數量</th>';
            html += '</tr></thead><tbody>';
            
            var total = 0;
            keys.forEach(function(key) {
                var sel = window.rmStockSelected[key];
                var item = sel.item;
                total += sel.qty;
                html += '<tr>';
                html += '<td>' + (item.company || '崇文') + '</td>';
                html += '<td>' + item.productName + '</td>';
                html += '<td>' + (item.spec || '-') + '</td>';
                html += '<td>' + (item.batchNo || '-') + '</td>';
                html += '<td>' + item.locationId + '</td>';
                html += '<td class="right">' + sel.qty + '</td>';
                html += '</tr>';
            });
            
            html += '<tr><td colspan="5" style="text-align:right;font-weight:bold;">合計</td>';
            html += '<td class="right" style="font-weight:bold;">' + total + ' 件</td></tr>';
            html += '</tbody></table>';
            
            html += '<div class="sign">';
            html += '<div>領用人</div>';
            html += '<div>倉管</div>';
            html += '<div>主管</div>';
            html += '</div>';
            
            html += '</body></html>';
            
            var win = window.open('', '_blank');
            win.document.write(html);
            win.document.close();
            win.print();
        };

        window.refreshWaveList = function() {
            var tbody = document.getElementById('wave-list-body');
            if (!tbody) return;

            var waves = window._waveData.waves;

            var today = new Date().toLocalYMD();
            var todayWaves = waves.filter(function(w) { return w.createdAt && w.createdAt.indexOf(today) === 0; });
            var pending = waves.filter(function(w) { return w.status === 'pending'; });
            var picking = waves.filter(function(w) { return w.status === 'picking'; });
            var done = waves.filter(function(w) { return w.status === 'done'; });

            document.getElementById('wave-stat-today').innerText = todayWaves.length;
            document.getElementById('wave-stat-pending').innerText = pending.length;
            document.getElementById('wave-stat-picking').innerText = picking.length;
            document.getElementById('wave-stat-done').innerText = done.length;

            var orders = (window._orderData && window._orderData.orders) ? window._orderData.orders.filter(function(o) {
                return o.status === 'pending' || o.status === 'confirmed';
            }) : [];
            document.getElementById('wave-stat-orders').innerText = orders.length;

            if (waves.length === 0) {
                tbody.innerHTML = '<tr><td colspan="8" class="text-center text-slate-500 py-8">尚無波次資料</td></tr>';
                return;
            }

            var sorted = waves.slice().sort(function(a, b) {
                return new Date(b.createdAt) - new Date(a.createdAt);
            });

            var html = '';
            sorted.forEach(function(wave) {
                var statusBadge = '';
                var progressInfo = '';
                var timeInfo = '';

                if (wave.status === 'pending') {
                    statusBadge = '<span class="badge badge-yellow"><i class="fa-solid fa-clock mr-1"></i>待揀貨</span>';
                } else if (wave.status === 'picking') {
                    statusBadge = '<span class="badge badge-blue"><i class="fa-solid fa-spinner fa-spin mr-1"></i>揀貨中</span>';
                    if (wave.startedAt) {
                        var mins = Math.round((new Date() - new Date(wave.startedAt)) / 60000);
                        timeInfo = '<div class="text-xs text-orange-400">已進行 ' + mins + ' 分鐘</div>';
                    }
                } else if (wave.status === 'sorting') {
                    statusBadge = '<span class="badge badge-purple"><i class="fa-solid fa-tags mr-1"></i>待分貨</span>';
                } else if (wave.status === 'done') {
                    statusBadge = '<span class="badge badge-green"><i class="fa-solid fa-check mr-1"></i>已出貨</span>';
                    if (wave.completedAt && wave.createdAt) {
                        var mins = Math.round((new Date(wave.completedAt) - new Date(wave.createdAt)) / 60000);
                        timeInfo = '<div class="text-xs text-slate-500">耗時 ' + mins + ' 分鐘</div>';
                    }
                }

                var hasChanges = wave.hasOrderChanges;
                var rowClass = hasChanges ? 'bg-orange-900/20 border-l-4 border-l-orange-500' : '';
                html += '<tr class="hover:bg-slate-800/50 border-b border-slate-700/50 ' + rowClass + '">';
                html += '<td class="p-3 font-mono text-cyan-400 font-bold">' + wave.waveNo;
                if (hasChanges) {
                    html += ' <span class="text-orange-400 text-xs" title="訂單有異動"><i class="fa-solid fa-triangle-exclamation"></i></span>';
                }
                html += '</td>';
                html += '<td class="p-3 text-white">' + (wave.logistics || '混合') + '</td>';
                html += '<td class="p-3">' + statusBadge + '</td>';
                html += '<td class="p-3 text-right text-slate-300">' + (wave.orders ? wave.orders.length : 0) + '</td>';
                html += '<td class="p-3 text-right text-slate-300">' + (wave.itemCount || 0) + ' 項</td>';
                html += '<td class="p-3 text-right text-yellow-400 font-bold">' + (wave.totalQty || 0) + ' <span class="text-xs text-slate-400 font-normal">件</span></td>';
                html += '<td class="p-3 text-slate-400 text-xs">' + new Date(wave.createdAt).toLocaleString('zh-TW') + '</td>';
                html += '<td class="p-3 text-center">';
                if (wave.status === 'pending') {
                    html += '<button onclick="openWaveExecute(\'' + wave.waveNo + '\')" class="bg-blue-600 hover:bg-blue-500 text-white text-xs px-3 py-1 rounded mr-1"><i class="fa-solid fa-play mr-1"></i>開始揀貨</button>';
                    html += '<button onclick="openAddToWaveModal(\'' + wave.waveNo + '\')" class="bg-purple-600 hover:bg-purple-500 text-white text-xs px-2 py-1 rounded mr-1" title="追加訂單"><i class="fa-solid fa-plus"></i></button>';
                } else if (wave.status === 'picking') {
                    html += '<button onclick="openWaveExecute(\'' + wave.waveNo + '\')" class="bg-orange-600 hover:bg-orange-500 text-white text-xs px-3 py-1 rounded mr-1"><i class="fa-solid fa-spinner fa-spin mr-1"></i>繼續揀貨</button>';
                } else if (wave.status === 'sorting') {
                    html += '<button onclick="openWaveSorting(\'' + wave.waveNo + '\')" class="bg-purple-600 hover:bg-purple-500 text-white text-xs px-3 py-1 rounded mr-1"><i class="fa-solid fa-tags mr-1"></i>分貨作業</button>';
                }
                html += '<button onclick="viewWaveDetail(\'' + wave.waveNo + '\')" class="bg-slate-600 hover:bg-slate-500 text-white text-xs px-2 py-1 rounded mr-1" title="檢視明細"><i class="fa-solid fa-eye"></i></button>';
                if (wave.status === 'pending') {
                    html += '<button onclick="deleteWave(\'' + wave.waveNo + '\')" class="bg-red-600 hover:bg-red-500 text-white text-xs px-2 py-1 rounded" title="刪除波次"><i class="fa-solid fa-trash"></i></button>';
                }
                if (wave.status === 'done') {
                    html += '<button onclick="printWaveLabels(\'' + wave.waveNo + '\')" class="bg-slate-600 hover:bg-slate-500 text-white text-xs px-2 py-1 rounded" title="重印標籤"><i class="fa-solid fa-print"></i></button>';
                }
                html += '</td>';
                html += '</tr>';
            });

            tbody.innerHTML = html;

        checkWaveChangeAlert();
        };

function checkWaveChangeAlert() {
    var changedWaves = (window._waveData.waves || []).filter(function(w) { return w.hasOrderChanges; });
    var existingAlert = document.getElementById('wave-change-alert-bar');

    if (changedWaves.length > 0) {
        var waveNos = changedWaves.map(function(w) { return w.waveNo; }).join(', ');

        if (!existingAlert) {
            var alertBar = document.createElement('div');
            alertBar.id = 'wave-change-alert-bar';
            alertBar.className = 'fixed top-0 left-0 right-0 z-[100] bg-gradient-to-r from-red-600 to-orange-600 text-white py-3 px-4 flex items-center justify-between shadow-lg';
            alertBar.innerHTML = '<div class="flex items-center gap-3">' +
                '<i class="fa-solid fa-triangle-exclamation text-2xl animate-pulse"></i>' +
                '<div>' +
                '<span class="font-bold">⚠️ 有 ' + changedWaves.length + ' 個波次需要更新揀貨單！</span>' +
                '<span class="ml-2 text-red-200">(' + waveNos + ')</span>' +
                '</div>' +
                '</div>' +
                '<button onclick="updateChangedWaves()" class="bg-white text-red-600 px-4 py-2 rounded-lg font-bold hover:bg-red-100 transition flex items-center gap-2">' +
                '<i class="fa-solid fa-print"></i>立即更新並列印' +
                '</button>';
            document.body.appendChild(alertBar);

            document.body.style.paddingTop = '56px';
        } else {
            existingAlert.querySelector('.font-bold').innerText = '⚠️ 有 ' + changedWaves.length + ' 個波次需要更新揀貨單！';
        }
    } else {
        if (existingAlert) {
            existingAlert.remove();
            document.body.style.paddingTop = '';
        }
    }
}

window.openWaveSorting = function(waveNo) {
    var wave = window._waveData.waves.find(function(w) { return w.waveNo === waveNo; });
    if (!wave) {
        alert('找不到波次 ' + waveNo);
        return;
    }

    window._waveData.currentWave = wave;

    var modal = document.createElement('div');
    modal.id = 'modal-wave-sorting';
    modal.className = 'fixed inset-0 z-50 bg-black/80 flex items-center justify-center backdrop-blur-sm';

    var ordersHtml = '';
    (wave.orders || []).forEach(function(order) {
        var totalPkgQty = 0;
        var itemsHtml = (order.items || []).filter(function(item) {
            return !window.isExcludedFromSortingLabel(item.productName);
        }).map(function(item) {
            var qty = item.quantity || 0;
            var boxPerPkg = parseBoxPerPackage(item.productName);
            var pkgQty = (boxPerPkg > 0 && qty > 0) ? Math.ceil(qty / boxPerPkg) : (item.packageQty || 1);
            if (!window.isPackagingItem(item.productName)) {
                totalPkgQty += pkgQty;
            }
            var isPackaging = window.isPackagingItem(item.productName);
            var qtyDisplay = isPackaging ? '<span class="text-slate-500">' + pkgQty + ' (包材)</span>' : '<span class="text-yellow-400 font-bold">' + pkgQty + ' 件</span>';
            return '<div class="flex justify-between text-sm py-1 border-b border-slate-700/50">' +
                '<span class="text-slate-300">' + item.productName + ' ' + (item.spec || '') + '</span>' +
                qtyDisplay + '</div>';
        }).join('');

        itemsHtml += '<div class="flex justify-between text-sm py-2 mt-1 bg-slate-700/50 rounded px-2">' +
            '<span class="text-white font-bold">小計</span>' +
            '<span class="text-red-400 font-bold text-lg">' + totalPkgQty + ' 件</span></div>';

        ordersHtml += '<div class="bg-slate-800 border border-slate-600 rounded-lg p-4 mb-3">' +
            '<div class="flex justify-between items-start mb-3">' +
            '<div><div class="text-cyan-400 font-mono text-sm">' + order.orderNo + '</div>' +
            '<div class="text-white font-bold text-lg">' + order.customer + '</div>' +
            '<div class="text-slate-400 text-xs">' + (order.address || '') + '</div></div>' +
            '<div class="text-right"><span class="px-2 py-1 rounded text-xs bg-slate-700 text-slate-300">' + (order.logistics || wave.logistics) + '</span>' +
            '<div class="mt-2"><button onclick="printSingleLabel(\'' + order.orderNo + '\')" class="bg-purple-600 hover:bg-purple-500 text-white text-xs px-3 py-1 rounded">' +
            '<i class="fa-solid fa-tag mr-1"></i>列印標籤</button></div></div></div>' +
            '<div class="border-t border-slate-600 pt-2">' + itemsHtml + '</div></div>';
    });

    modal.innerHTML = '<div class="bg-slate-900 border border-slate-700 rounded-2xl w-[900px] max-h-[90vh] shadow-2xl flex flex-col">' +
        '<div class="bg-gradient-to-r from-purple-900 to-pink-900 p-4 rounded-t-2xl border-b border-slate-700 flex justify-between items-center">' +
        '<div><h3 class="text-white font-bold text-lg"><i class="fa-solid fa-tags mr-2 text-purple-400"></i>分貨作業 - ' + wave.waveNo + '</h3>' +
        '<p class="text-purple-200 text-xs mt-1">物流商：' + wave.logistics + ' | 訂單數：' + (wave.orders || []).length + '</p></div>' +
        '<button onclick="printAllLabels()" class="bg-purple-600 hover:bg-purple-500 text-white px-4 py-2 rounded-lg text-sm font-bold">' +
        '<i class="fa-solid fa-print mr-1"></i>列印全部標籤</button></div>' +
        '<div class="p-4 bg-purple-900/20 border-b border-slate-700"><div class="flex items-center text-purple-300 text-sm">' +
        '<i class="fa-solid fa-info-circle mr-2"></i>請依標籤將貨物分配給各客戶，確認無誤後點擊「完成分貨」</div></div>' +
        '<div class="flex-1 overflow-auto p-4">' + ordersHtml + '</div>' +
        '<div class="p-4 border-t border-slate-700 flex gap-3">' +
        (wave.logistics === '大榮' || wave.logistics === '大榮貨運' ?
        '<button onclick="openPalletPlanModal()" class="flex-1 py-3 bg-orange-600 hover:bg-orange-500 text-white rounded-lg font-bold">' +
        '<i class="fa-solid fa-pallet mr-2"></i>棧板堆疊規劃</button>' : '') +
        '<button onclick="completeSorting()" class="flex-1 py-3 bg-green-600 hover:bg-green-500 text-white rounded-lg font-bold">' +
        '<i class="fa-solid fa-truck mr-2"></i>完成分貨，出貨</button>' +
        '<button onclick="closeSortingModal()" class="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg">關閉</button></div></div>';

    document.body.appendChild(modal);
};

window.closeSortingModal = function() {
    var modal = document.getElementById('modal-wave-sorting');
    if (modal) modal.remove();
};

window.printSingleLabel = function(orderNo) {
    var wave = window._waveData.currentWave;
    var order = (wave.orders || []).find(function(o) { return o.orderNo === orderNo; });
    if (!order) return;

    var printWindow = window.open('', '_blank', 'width=1100,height=800');
    var totalPkg = 0;
    var itemsHtml = (order.items || []).filter(function(item) {
        return !window.isExcludedFromSortingLabel(item.productName);
    }).map(function(item) {
        var qty = item.quantity || 0;
        var boxPerPkg = parseBoxPerPackage(item.productName);
        var pkgQty = (boxPerPkg > 0 && qty > 0) ? Math.ceil(qty / boxPerPkg) : (item.packageQty || 1);
        if (!window.isPackagingItem(item.productName)) {
            totalPkg += pkgQty;
        }
        var isPackaging = window.isPackagingItem(item.productName);
        var qtyText = isPackaging ? '(包材)' : pkgQty + ' 件';
        return '<div class="item"><span>' + item.productName + ' ' + (item.spec || '') + '</span><strong>' + qtyText + '</strong></div>';
    }).join('');

    printWindow.document.write('<!DOCTYPE html><html><head><title>分貨標籤</title>' +
        '<style>body{font-family:"Microsoft JhengHei",sans-serif;padding:20px}' +
        '.label{border:2px solid #333;padding:15px;width:320px}' +
        '.logistics{background:#333;color:white;padding:5px 10px;font-weight:bold;margin:-15px -15px 10px -15px}' +
        '.customer{font-size:24px;font-weight:bold;margin:10px 0}' +
        '.total{background:#dc2626;color:white;padding:8px;text-align:center;font-size:20px;font-weight:bold;margin:10px 0;border-radius:4px}' +
        '.items{border-top:1px dashed #ccc;padding-top:10px}' +
        '.item{margin:5px 0;display:flex;justify-content:space-between}' +
        '.address{font-size:12px;color:#666;margin-top:10px;border-top:1px dashed #ccc;padding-top:10px}</style></head>' +
        '<body><div class="label"><div class="logistics">' + (order.logistics || wave.logistics) + '</div>' +
        '<div style="font-size:14px;color:#666">📦 ' + order.orderNo + '</div>' +
        '<div class="customer">👤 ' + order.customer + '</div>' +
        '<div class="total">共 ' + totalPkg + ' 件</div>' +
        '<div class="items">' + itemsHtml + '</div>' +
        (order.address ? '<div class="address">📍 ' + order.address + '</div>' : '') +
        '</div><script>window.print();<\/script></body></html>');
    printWindow.document.close();
};

window.printAllLabels = function() {
    var wave = window._waveData.currentWave;
    var printWindow = window.open('', '_blank', 'width=1100,height=800');

    var labelsHtml = (wave.orders || []).map(function(order) {
        var totalPkg = 0;
        var itemsHtml = (order.items || []).filter(function(item) {
            return !window.isExcludedFromSortingLabel(item.productName);
        }).map(function(item) {
            var qty = item.quantity || 0;
            var boxPerPkg = parseBoxPerPackage(item.productName);
            var pkgQty = (boxPerPkg > 0 && qty > 0) ? Math.ceil(qty / boxPerPkg) : (item.packageQty || 1);
            if (!window.isPackagingItem(item.productName)) {
                totalPkg += pkgQty;
            }
            var isPackaging = window.isPackagingItem(item.productName);
            var qtyText = isPackaging ? '(包材)' : pkgQty + ' 件';
            return '<div class="item"><span>' + item.productName + '</span><strong>' + qtyText + '</strong></div>';
        }).join('');

        return '<div class="label"><div class="logistics">' + (order.logistics || wave.logistics) + '</div>' +
            '<div style="font-size:14px;color:#666">📦 ' + order.orderNo + '</div>' +
            '<div class="customer">👤 ' + order.customer + '</div>' +
            '<div class="total">共 ' + totalPkg + ' 件</div>' +
            '<div class="items">' + itemsHtml + '</div>' +
            (order.address ? '<div class="address">📍 ' + order.address + '</div>' : '') + '</div>';
    }).join('');

    printWindow.document.write('<!DOCTYPE html><html><head><title>分貨標籤</title>' +
        '<style>body{font-family:"Microsoft JhengHei",sans-serif;padding:20px}' +
        '.label{border:2px solid #333;padding:15px;width:320px;margin-bottom:20px;page-break-inside:avoid}' +
        '.logistics{background:#333;color:white;padding:5px 10px;font-weight:bold;margin:-15px -15px 10px -15px}' +
        '.customer{font-size:24px;font-weight:bold;margin:10px 0}' +
        '.total{background:#dc2626;color:white;padding:8px;text-align:center;font-size:20px;font-weight:bold;margin:10px 0;border-radius:4px}' +
        '.items{border-top:1px dashed #ccc;padding-top:10px}' +
        '.item{margin:5px 0;display:flex;justify-content:space-between}' +
        '.address{font-size:12px;color:#666;margin-top:10px;border-top:1px dashed #ccc;padding-top:10px}</style></head>' +
        '<body>' + labelsHtml + '<script>window.print();<\/script></body></html>');
    printWindow.document.close();
};

// ========== 棧板堆疊規劃功能 ==========

var PALLET_CONFIG = {
    bottomCount: 7,    // 每層底數（件）
    layerCount: 8,     // 層數
    maxCapacity: 56    // 總容量（7×8=56件）
};

window.openPalletPlanModal = function() {
    var wave = window._waveData.currentWave;
    if (!wave || !wave.orders || wave.orders.length === 0) {
        alert('無訂單資料');
        return;
    }

    if (wave.logistics !== '大榮' && wave.logistics !== '大榮貨運') {
        alert('棧板堆疊規劃僅適用於大榮貨運');
        return;
    }

    var ordersWithQty = (wave.orders || []).map(function(order) {
        var totalPkg = 0;
        (order.items || []).forEach(function(item) {
            var qty = item.quantity || 0;
            var boxPerPkg = parseBoxPerPackage(item.productName);
            var pkgQty = (boxPerPkg > 0 && qty > 0) ? Math.ceil(qty / boxPerPkg) : (item.packageQty || 1);
            totalPkg += pkgQty;
        });
        return {
            orderNo: order.orderNo,
            customer: order.customer,
            address: order.address || '',
            logistics: order.logistics || wave.logistics,
            totalPkg: totalPkg
        };
    });

    ordersWithQty.sort(function(a, b) {
        if (a.totalPkg !== b.totalPkg) return a.totalPkg - b.totalPkg;

        return a.orderNo.localeCompare(b.orderNo);
    });

    var pallets = [];
    var currentPallet = { orders: [], totalPkg: 0, layers: [] };
    var currentLayer = [];
    var currentLayerPkg = 0;

    ordersWithQty.forEach(function(order) {
        if (currentPallet.totalPkg + order.totalPkg > PALLET_CONFIG.maxCapacity) {
            if (currentLayer.length > 0) {
                currentPallet.layers.push(currentLayer);
            }
            if (currentPallet.orders.length > 0) {
                pallets.push(currentPallet);
            }
            currentPallet = { orders: [], totalPkg: 0, layers: [] };
            currentLayer = [];
            currentLayerPkg = 0;
        }

        if (currentLayerPkg + order.totalPkg > PALLET_CONFIG.bottomCount) {
            if (currentLayer.length > 0) {
                currentPallet.layers.push(currentLayer);
            }
            currentLayer = [];
            currentLayerPkg = 0;
        }

        currentPallet.orders.push(order);
        currentPallet.totalPkg += order.totalPkg;
        currentLayer.push(order);
        currentLayerPkg += order.totalPkg;
    });

    if (currentLayer.length > 0) {
        currentPallet.layers.push(currentLayer);
    }
    if (currentPallet.orders.length > 0) {
        pallets.push(currentPallet);
    }

    var modal = document.createElement('div');
    modal.id = 'modal-pallet-plan';
    modal.className = 'fixed inset-0 z-50 bg-black/80 flex items-center justify-center backdrop-blur-sm overflow-auto py-4';

    var palletsHtml = pallets.map(function(pallet, pIdx) {
        var layersHtml = pallet.layers.map(function(layer, lIdx) {
            var layerNum = pallet.layers.length - lIdx;
            var layerOrders = layer.map(function(o) {
                return '<span class="inline-block bg-slate-600 text-white text-xs px-2 py-1 rounded mr-1 mb-1">' +
                    o.customer + ' <span class="text-yellow-400">' + o.totalPkg + '件</span></span>';
            }).join('');
            var layerTotal = layer.reduce(function(sum, o) { return sum + o.totalPkg; }, 0);

            return '<div class="border-b border-slate-600 py-2">' +
                '<div class="flex justify-between items-center mb-1">' +
                '<span class="text-slate-400 text-sm">第 ' + layerNum + ' 層' + (layerNum === 1 ? ' (底層-散板/人工)' : layerNum === pallet.layers.length ? ' (頂層-堆高機)' : '') + '</span>' +
                '<span class="text-cyan-400 text-sm">' + layerTotal + ' 件</span>' +
                '</div>' +
                '<div>' + layerOrders + '</div>' +
                '</div>';
        }).join('');

        var usagePercent = Math.round(pallet.totalPkg / PALLET_CONFIG.maxCapacity * 100);
        var usageColor = usagePercent >= 80 ? 'text-green-400' : (usagePercent >= 50 ? 'text-yellow-400' : 'text-red-400');

        return '<div class="bg-slate-800 border border-slate-600 rounded-lg p-4 mb-4">' +
            '<div class="flex justify-between items-center mb-3 pb-2 border-b border-slate-500">' +
            '<div class="text-white font-bold text-lg"><i class="fa-solid fa-pallet mr-2 text-orange-400"></i>棧板 #' + (pIdx + 1) + '</div>' +
            '<div class="text-right">' +
            '<div class="' + usageColor + ' font-bold">' + pallet.totalPkg + ' / ' + PALLET_CONFIG.maxCapacity + ' 件</div>' +
            '<div class="text-slate-400 text-xs">使用率 ' + usagePercent + '%</div>' +
            '</div></div>' +
            '<div class="text-xs text-orange-300 mb-2"><i class="fa-solid fa-arrow-up mr-1"></i>從上往下讀 = 取貨順序（先取上層）</div>' +
            layersHtml +
            '</div>';
    }).join('');

    var totalOrders = ordersWithQty.length;
    var totalPkg = ordersWithQty.reduce(function(sum, o) { return sum + o.totalPkg; }, 0);

    modal.innerHTML = '<div class="bg-slate-900 border border-slate-700 rounded-2xl w-[800px] max-h-[90vh] shadow-2xl flex flex-col m-4">' +
        '<div class="bg-gradient-to-r from-orange-900 to-amber-900 p-4 rounded-t-2xl border-b border-slate-700">' +
        '<h3 class="text-white font-bold text-lg"><i class="fa-solid fa-pallet mr-2 text-orange-400"></i>棧板堆疊規劃 - ' + wave.waveNo + '</h3>' +
        '<p class="text-orange-200 text-sm mt-1">物流商：' + wave.logistics + ' | 訂單：' + totalOrders + ' 筆 | 總件數：' + totalPkg + ' 件 | 棧板：' + pallets.length + ' 板</p></div>' +
        '<div class="p-4 bg-orange-900/20 border-b border-slate-700">' +
        '<div class="flex items-center justify-between">' +
        '<div class="text-orange-300 text-sm"><i class="fa-solid fa-lightbulb mr-2"></i>堆疊原則：小單先疊（底層-散板人工），大單後疊（上層-堆高機）</div>' +
        '<div class="text-slate-400 text-xs">棧板容量：' + PALLET_CONFIG.bottomCount + '底 × ' + PALLET_CONFIG.layerCount + '層 = ' + PALLET_CONFIG.maxCapacity + '件</div>' +
        '</div></div>' +
        '<div class="flex-1 overflow-auto p-4">' + palletsHtml + '</div>' +
        '<div class="p-4 border-t border-slate-700 flex gap-3">' +
        '<button onclick="printPalletPlan()" class="flex-1 py-3 bg-orange-600 hover:bg-orange-500 text-white rounded-lg font-bold">' +
        '<i class="fa-solid fa-print mr-2"></i>列印堆疊規劃表</button>' +
        '<button onclick="closePalletPlanModal()" class="px-6 py-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg">關閉</button></div></div>';

    document.body.appendChild(modal);
};

window.closePalletPlanModal = function() {
    var modal = document.getElementById('modal-pallet-plan');
    if (modal) modal.remove();
};

function getDeliveryRegion(address) {
    if (!address) return 0;

    var regionWeights = {
        '台北': 1, '臺北': 1, '新北': 1, '基隆': 2, '桃園': 2, '新竹': 3,
        '苗栗': 4, '台中': 5, '臺中': 5, '彰化': 5, '南投': 6, '雲林': 6,
        '嘉義': 7, '台南': 8, '臺南': 8, '高雄': 9, '屏東': 10,
        '宜蘭': 6, '花蓮': 11, '台東': 12, '臺東': 12,
        '澎湖': 15, '金門': 16, '馬祖': 16, '連江': 16
    };

    for (var city in regionWeights) {
        if (address.includes(city)) {
            return regionWeights[city];
        }
    }
    return 5; // 預設中等距離
}

window.printPalletPlan = function() {
    var wave = window._waveData.currentWave;

    var ordersWithQty = (wave.orders || []).map(function(order) {
        var totalPkg = 0;
        (order.items || []).forEach(function(item) {
            var qty = item.quantity || 0;
            var boxPerPkg = parseBoxPerPackage(item.productName);
            var pkgQty = (boxPerPkg > 0 && qty > 0) ? Math.ceil(qty / boxPerPkg) : (item.packageQty || 1);
            totalPkg += pkgQty;
        });
        return {
            orderNo: order.orderNo,
            customer: order.customer,
            address: order.address || '',
            totalPkg: totalPkg
        };
    });

    ordersWithQty.sort(function(a, b) {
        if (a.totalPkg !== b.totalPkg) return a.totalPkg - b.totalPkg;
        return a.orderNo.localeCompare(b.orderNo);
    });

    var pallets = [];
    var currentPallet = { orders: [], totalPkg: 0 };

    ordersWithQty.forEach(function(order) {
        if (currentPallet.totalPkg + order.totalPkg > PALLET_CONFIG.maxCapacity) {
            if (currentPallet.orders.length > 0) pallets.push(currentPallet);
            currentPallet = { orders: [], totalPkg: 0 };
        }
        currentPallet.orders.push(order);
        currentPallet.totalPkg += order.totalPkg;
    });
    if (currentPallet.orders.length > 0) pallets.push(currentPallet);

    var printWindow = window.open('', '_blank', 'width=1100,height=800');
    var now = new Date().toLocaleString('zh-TW');

    var html = '<!DOCTYPE html><html><head><title>棧板堆疊規劃表</title>' +
        '<style>' +
        'body { font-family: "Microsoft JhengHei", sans-serif; font-size: 12px; padding: 15px; }' +
        '.header { text-align: center; margin-bottom: 15px; border-bottom: 2px solid #333; padding-bottom: 10px; }' +
        '.header h2 { margin: 0 0 5px 0; }' +
        '.info { margin-bottom: 15px; display: flex; gap: 20px; }' +
        '.info-item { background: #f3f4f6; padding: 5px 10px; border-radius: 4px; }' +
        '.pallet { border: 2px solid #333; margin-bottom: 15px; page-break-inside: avoid; }' +
        '.pallet-header { background: #374151; color: white; padding: 8px 10px; font-weight: bold; display: flex; justify-content: space-between; }' +
        '.pallet-body { padding: 10px; }' +
        '.layer { border-bottom: 1px dashed #ccc; padding: 5px 0; }' +
        '.layer:last-child { border-bottom: none; }' +
        '.layer-num { color: #666; font-size: 11px; }' +
        '.order-tag { display: inline-block; background: #e5e7eb; padding: 2px 8px; margin: 2px; border-radius: 3px; }' +
        '.order-qty { color: #dc2626; font-weight: bold; }' +
        '.note { background: #fef3c7; padding: 10px; margin-bottom: 15px; border-radius: 4px; }' +
        '.timestamp { text-align: right; font-size: 10px; color: #666; margin-top: 15px; }' +
        '</style></head><body>';

    html += '<div class="header"><h2>棧板堆疊規劃表</h2><h3>' + wave.waveNo + ' - ' + wave.logistics + '</h3></div>';

    html += '<div class="note"><b>📋 堆疊原則：</b>小單先疊（底層-散板/人工搬運），大單後疊（上層-堆高機搬運）<br>' +
        '<b>📦 棧板規格：</b>' + PALLET_CONFIG.bottomCount + ' 底 × ' + PALLET_CONFIG.layerCount + ' 層 = ' + PALLET_CONFIG.maxCapacity + ' 件/板</div>';

    html += '<div class="info">' +
        '<div class="info-item"><b>訂單數：</b>' + ordersWithQty.length + ' 筆</div>' +
        '<div class="info-item"><b>總件數：</b>' + ordersWithQty.reduce(function(s,o){return s+o.totalPkg;},0) + ' 件</div>' +
        '<div class="info-item"><b>棧板數：</b>' + pallets.length + ' 板</div></div>';

    pallets.forEach(function(pallet, pIdx) {
        html += '<div class="pallet">';
        html += '<div class="pallet-header"><span>棧板 #' + (pIdx + 1) + '</span><span>' + pallet.totalPkg + ' / ' + PALLET_CONFIG.maxCapacity + ' 件</span></div>';
        html += '<div class="pallet-body">';

        var stackOrder = 1;
        pallet.orders.slice().reverse().forEach(function(order, idx) {
            var layerNum = Math.floor(idx / PALLET_CONFIG.bottomCount) + 1;
            html += '<div class="layer">' +
                '<span class="layer-num">取貨順序 ' + stackOrder + '</span> ' +
                '<span class="order-tag">' + order.customer + ' <span class="order-qty">' + order.totalPkg + '件</span></span> ' +
                '<span style="color:#666;font-size:10px">' + order.address.substring(0, 15) + '...</span>' +
                '</div>';
            stackOrder++;
        });

        html += '</div></div>';
    });

    html += '<div class="timestamp">列印日期：' + now + '</div>';
    html += '<script>window.print();<\/script></body></html>';

    printWindow.document.write(html);
    printWindow.document.close();
};

window.completeSorting = async function() {
    var wave = window._waveData.currentWave;

    if (!confirm('確定完成分貨？\n\n波次 ' + wave.waveNo + ' 將標記為【已出貨】')) {
        return;
    }

    wave.status = 'done';
    wave.sortedAt = new Date().toISOString();
    wave.completedAt = new Date().toISOString();

    if (wave.id) {
        try {
            await window.updateDoc(window.doc(window.db, 'waves', wave.id), {
                status: 'done',
                sortedAt: wave.sortedAt,
                completedAt: wave.completedAt
            });
        } catch (err) {
            console.error('更新波次狀態失敗:', err);
        }
    }

    for (var i = 0; i < (wave.orders || []).length; i++) {
        var order = wave.orders[i];
        var orderInData = window._orderData.orders.find(function(o) { return o.orderNo === order.orderNo; });
        if (orderInData) {
            orderInData.status = 'shipped';
        }
        if (order.id) {
            try {
                await window.updateDoc(window.doc(window.db, 'salesOrders', order.id), {
                    status: 'shipped',
                    shippedAt: new Date().toISOString(),
                    waveNo: wave.waveNo
                });
            } catch (err) {
                console.error('更新訂單狀態失敗:', order.orderNo, err);
            }
        }
    }

    saveWaves();

    var mins = Math.round((new Date(wave.completedAt) - new Date(wave.createdAt)) / 60000);
    alert('✅ 波次 ' + wave.waveNo + ' 已完成出貨！\n\n訂單數：' + (wave.orders || []).length + ' 筆\n總耗時：' + mins + ' 分鐘');

    closeSortingModal();
    refreshWaveList();
};

window.viewWaveDetail = function(waveNo) {
    var wave = window._waveData.waves.find(function(w) { return w.waveNo === waveNo; });
    if (!wave) return;

    var statusMap = { pending: '待揀貨', picking: '揀貨中', sorting: '待分貨', done: '已出貨' };
    var timeInfo = '建立：' + new Date(wave.createdAt).toLocaleString('zh-TW');
    if (wave.startedAt) timeInfo += '\n開始揀貨：' + new Date(wave.startedAt).toLocaleString('zh-TW');
    if (wave.pickedAt) timeInfo += '\n揀貨完成：' + new Date(wave.pickedAt).toLocaleString('zh-TW');
    if (wave.completedAt) timeInfo += '\n出貨完成：' + new Date(wave.completedAt).toLocaleString('zh-TW');

    var orderList = (wave.orders || []).map(function(o, i) { return (i + 1) + '. ' + o.customer + ' (' + o.orderNo + ')'; }).join('\n');

    alert('【波次明細】\n\n' +
        '波次編號：' + wave.waveNo + '\n' +
        '物流商：' + wave.logistics + '\n' +
        '狀態：' + (statusMap[wave.status] || wave.status) + '\n' +
        '訂單數：' + (wave.orders || []).length + ' 筆\n' +
        '品項數：' + (wave.itemCount || 0) + ' 項\n' +
        '總件數：' + (wave.totalQty || 0) + ' 件（包裝單位）\n' +
        (wave.totalSmallQty ? '最小單位：' + wave.totalSmallQty + '\n' : '') + '\n' +
        '【時間記錄】\n' + timeInfo + '\n\n' +
        '【訂單清單】\n' + orderList);
};

window.deleteWave = async function(waveNo) {
    var wave = window._waveData.waves.find(function(w) { return w.waveNo === waveNo; });
    if (!wave) return;

    if (wave.status !== 'pending') {
        alert('只能刪除「待揀貨」狀態的波次');
        return;
    }

    if (!confirm('確定要刪除波次 ' + waveNo + '？\n\n訂單數：' + (wave.orders || []).length + ' 筆\n刪除後訂單將恢復為待處理狀態。')) {
        return;
    }

    for (var i = 0; i < (wave.orders || []).length; i++) {
        var order = wave.orders[i];
        var orderInData = window._orderData.orders.find(function(o) { return o.orderNo === order.orderNo; });
        if (orderInData) {
            orderInData.status = 'pending';
            orderInData.waveNo = null;
        }
        if (order.id) {
            try {
                await window.updateDoc(window.doc(window.db, 'salesOrders', order.id), {
                    status: 'pending',
                    waveNo: null
                });
            } catch (err) {
                console.error('恢復訂單狀態失敗:', err);
            }
        }
    }

    if (wave.id) {
        try {
            await window.deleteDoc(window.doc(window.db, 'waves', wave.id));
        } catch (err) {
            console.error('刪除波次失敗:', err);
        }
    }

    var idx = window._waveData.waves.findIndex(function(w) { return w.waveNo === waveNo; });
    if (idx >= 0) window._waveData.waves.splice(idx, 1);
    saveWaves();

    alert('✅ 波次 ' + waveNo + ' 已刪除');
    refreshWaveList();
};

window.printWaveLabels = function(waveNo) {
    var wave = window._waveData.waves.find(function(w) { return w.waveNo === waveNo; });
    if (!wave) return;
    window._waveData.currentWave = wave;
    printAllLabels();
};

