            if (!stock) return;

            var whName = window.EXTERNAL_WAREHOUSES[stock.warehouseId]?.name || stock.warehouseId;

            document.getElementById('transfer-id').value = id;
            document.getElementById('transfer-name').innerText = stock.productName;
