// 載入庫存資料
window.loadConsignStockData = function() {
    const internalInventory = window.currentInventory ? window.currentInventory() : [];
    const externalInventory = window.externalStock || [];
    
    // 建立已寄倉對照表
    // 內倉用 品名|規格|批號|儲位 匹配
    // 外倉用 品名|規格|批號|倉庫名稱 匹配
    const consignedMap = {};
    if (window.consignmentData && Array.isArray(window.consignmentData)) {
        window.consignmentData.forEach(c => {
            if (c.status !== 'active') return;
            var key;
            if (c.locationId) {
                // 內倉：用儲位區分
                key = `${c.productName || ''}|${c.spec || ''}|${c.batchNo || ''}|${c.locationId}`;
            } else {
                // 外倉：用倉庫名稱區分
                key = `${c.productName || ''}|${c.spec || ''}|${c.batchNo || ''}|${c.sourceWarehouse || ''}`;
            }
            consignedMap[key] = (consignedMap[key] || 0) + (c.remainingQty || 0);
        });
    }
    
    console.log('📋 寄庫對照表:', consignedMap);
    
    const allItems = [];
    
    // 內倉
    internalInventory.forEach(item => {
        if (!item.productName || (item.quantity || 0) <= 0) return;
        const status = (item.status || '').toLowerCase();
        if (status === 'shipped' || status === 'outbound' || status === 'deleted') return;
        
        const warehouseName = item.warehouse || item.company || '內倉';
        const locationId = item.locationId || '';
        // 內倉用儲位匹配
        const consignKey = `${item.productName}|${item.spec || ''}|${item.batchNo || ''}|${locationId}`;
        const consigned = consignedMap[consignKey] || 0;
        
        // 用於選擇的唯一 key（加入 id 確保唯一）
        const uniqueKey = `internal_${item.id}`;
        
        allItems.push({
            id: item.id,
            stockType: 'internal',
            productName: item.productName,
            spec: item.spec || '',
            batchNo: item.batchNo || '',
            quantity: item.quantity || 0,
            consigned: consigned,
            available: Math.max(0, (item.quantity || 0) - consigned),
            locationId: locationId,
            warehouseName: warehouseName,
            expDate: item.expiryDate ? (item.expiryDate.toDate ? item.expiryDate.toDate().toLocaleDateString('zh-TW') : new Date(item.expiryDate).toLocaleDateString('zh-TW')) : '-',
            key: uniqueKey
        });
    });
    
    // 外倉
    externalInventory.forEach(item => {
        if (!item.productName || (item.quantity || 0) <= 0) return;
        
        let warehouseName = item.warehouseId || '';
        const wh = (window.warehousesData || []).find(w => w.code === item.warehouseId || w.id === item.warehouseId);
        if (wh) warehouseName = wh.company + '_' + wh.name;
        else if (item.company) warehouseName = item.company + '_' + (item.warehouseId || '外倉');
        
        // 外倉用倉庫名稱匹配
        const consignKey = `${item.productName}|${item.spec || ''}|${item.batchNo || ''}|${warehouseName}`;
        const consigned = consignedMap[consignKey] || 0;
        
        // 用於選擇的唯一 key（加入 id 確保唯一）
        const uniqueKey = `external_${item.id}`;
        
        allItems.push({
            id: item.id,
            stockType: 'external',
            productName: item.productName,
            spec: item.spec || '',
            batchNo: item.batchNo || '',
            quantity: item.quantity || 0,
            consigned: consigned,
            available: Math.max(0, (item.quantity || 0) - consigned),
            locationId: warehouseName,
            warehouseName: warehouseName,
            expDate: item.expDate || '-',
            key: uniqueKey
        });
    });
    
    // 排序
    allItems.sort((a, b) => {
        const n = (a.productName || '').localeCompare(b.productName || '', 'zh-TW');
        if (n !== 0) return n;
        return (a.spec || '').localeCompare(b.spec || '', 'zh-TW');
    });
    
    window.consignStockData = allItems;
    renderConsignStockTable();
};

// 渲染表格
window.renderConsignStockTable = function() {
    const tbody = document.getElementById('consign-stock-tbody');
    if (!tbody) return;
    
    const searchText = (document.getElementById('consign-stock-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignStockFilter || 'all';
    
    let filtered = window.consignStockData.filter(item => {
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        if (searchText) {
            return (item.productName || '').toLowerCase().includes(searchText) ||
                   (item.spec || '').toLowerCase().includes(searchText) ||
                   (item.batchNo || '').toLowerCase().includes(searchText) ||
                   (item.locationId || '').toLowerCase().includes(searchText);
        }
        return true;
    });
    
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="11" class="text-center text-slate-500 py-10">無符合條件的庫存</td></tr>';
        return;
    }
    
    let html = '';
    filtered.forEach((item, idx) => {
        const isInternal = item.stockType === 'internal';
        const typeClass = isInternal ? 'bg-blue-600' : 'bg-purple-600';
        const typeLabel = isInternal ? '內' : '外';
        const disabled = item.available <= 0;
        const selected = window.consignStockSelected[item.key];
        const isChecked = !!selected;
        const rowBg = isChecked ? 'bg-emerald-900/30' : '';
        
        // 效期顏色
        let expClass = 'text-slate-400';
        if (item.expDate && item.expDate !== '-') {
            try {
                const parts = item.expDate.split('/');
                if (parts.length === 3) {
                    const expDate = new Date(parts[0], parts[1]-1, parts[2]);
                    const diffDays = Math.ceil((expDate - new Date()) / 86400000);
                    if (diffDays < 0) expClass = 'text-red-500';
                    else if (diffDays < 30) expClass = 'text-orange-400';
                    else if (diffDays < 90) expClass = 'text-yellow-400';
                }
            } catch(e) {}
        }
        
        html += `
            <tr class="border-b border-slate-700/50 hover:bg-slate-800/50 ${rowBg}" data-key="${item.key}">
                <td class="p-2 text-center">
                    <input type="checkbox" class="cs-checkbox" data-idx="${idx}" ${isChecked ? 'checked' : ''} ${disabled ? 'disabled' : ''} onchange="toggleConsignItem(${idx}, this.checked)">
                </td>
                <td class="p-2"><span class="px-1.5 py-0.5 rounded text-[10px] ${typeClass}">${typeLabel}</span></td>
                <td class="p-2 text-white">${item.productName}</td>
                <td class="p-2 text-yellow-400">${item.spec || '-'}</td>
                <td class="p-2 text-slate-400 font-mono text-xs">${item.batchNo || '-'}</td>
                <td class="p-2 text-right text-white">${item.quantity}</td>
                <td class="p-2 text-right ${item.consigned > 0 ? 'text-amber-400' : 'text-slate-600'}">${item.consigned || '-'}</td>
                <td class="p-2 text-right ${item.available > 0 ? 'text-emerald-400 font-bold' : 'text-red-400'}">${item.available}</td>
                <td class="p-2 ${isInternal ? 'text-cyan-400' : 'text-teal-400'} font-mono text-xs">${item.locationId || '-'}</td>
                <td class="p-2 ${expClass} text-xs">${item.expDate}</td>
                <td class="p-2 text-center">
                    <input type="number" class="scan-input w-20 py-1 text-center text-xs ${disabled ? 'opacity-40' : ''}" 
                        data-idx="${idx}" min="1" max="${item.available}" 
                        value="${selected?.qty || ''}" placeholder="${item.available}"
                        ${disabled ? 'disabled' : ''} 
                        onchange="updateConsignQty(${idx}, this.value)" onfocus="this.select()">
                </td>
            </tr>
        `;
    });
    
    tbody.innerHTML = html;
    updateConsignSummary();
};

// 篩選類型
window.filterConsignStock = function(type) {
    window.consignStockFilter = type;
    ['all', 'internal', 'external'].forEach(t => {
        const btn = document.getElementById(`btn-cs-${t}`);
        if (btn) btn.className = t === type 
            ? 'px-3 py-1 rounded text-xs font-bold bg-slate-600 text-white'
            : 'px-3 py-1 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
    });
    renderConsignStockTable();
};

// 全選
window.toggleConsignAll = function(checked) {
    document.querySelectorAll('.cs-checkbox:not(:disabled)').forEach(cb => {
        const idx = parseInt(cb.dataset.idx);
        cb.checked = checked;
        toggleConsignItem(idx, checked, false);
    });
    updateConsignSummary();
};

// 單選
window.toggleConsignItem = function(idx, checked, update = true) {
    const searchText = (document.getElementById('consign-stock-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignStockFilter || 'all';
    
    const filtered = window.consignStockData.filter(item => {
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        if (searchText) {
            return (item.productName || '').toLowerCase().includes(searchText) ||
                   (item.spec || '').toLowerCase().includes(searchText) ||
                   (item.batchNo || '').toLowerCase().includes(searchText);
        }
        return true;
    });
    
    const item = filtered[idx];
    if (!item) return;
    
    const row = document.querySelector(`tr[data-key="${item.key}"]`);
    
    if (checked) {
        const qtyInput = document.querySelector(`input[type="number"][data-idx="${idx}"]`);
        let qty = parseInt(qtyInput?.value);
        // 如果輸入框為空或無效，使用可寄數量
        if (isNaN(qty) || qty <= 0) {
            qty = item.available;
        }
        qty = Math.min(qty, item.available);
        
        window.consignStockSelected[item.key] = { item: item, qty: qty };
        
        // 更新輸入框顯示
        if (qtyInput) qtyInput.value = qty;
        if (row) row.classList.add('bg-emerald-900/30');
    } else {
        delete window.consignStockSelected[item.key];
        if (row) row.classList.remove('bg-emerald-900/30');
    }
    
    if (update) updateConsignSummary();
};

// 更新數量
window.updateConsignQty = function(idx, value) {
    const searchText = (document.getElementById('consign-stock-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignStockFilter || 'all';
    
    const filtered = window.consignStockData.filter(item => {
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        if (searchText) {
            return (item.productName || '').toLowerCase().includes(searchText) ||
                   (item.spec || '').toLowerCase().includes(searchText) ||
                   (item.batchNo || '').toLowerCase().includes(searchText);
        }
        return true;
    });
    
    const item = filtered[idx];
    if (!item) return;
    
    const qty = parseInt(value) || 0;
    const checkbox = document.querySelector(`.cs-checkbox[data-idx="${idx}"]`);
    const row = document.querySelector(`tr[data-key="${item.key}"]`);
    
    if (qty > 0 && qty <= item.available) {
        if (checkbox && !checkbox.checked) checkbox.checked = true;
        window.consignStockSelected[item.key] = { item, qty };
        if (row) row.classList.add('bg-emerald-900/30');
    } else if (qty > item.available) {
        const qtyInput = document.querySelector(`input[type="number"][data-idx="${idx}"]`);
        if (qtyInput) qtyInput.value = item.available;
        updateConsignQty(idx, item.available);
        return;
    } else {
        if (checkbox) checkbox.checked = false;
        delete window.consignStockSelected[item.key];
        if (row) row.classList.remove('bg-emerald-900/30');
    }
    
    updateConsignSummary();
};

// 更新統計
window.updateConsignSummary = function() {
    const keys = Object.keys(window.consignStockSelected || {});
    let totalQty = 0;
    
    keys.forEach(k => {
        const sel = window.consignStockSelected[k];
        const qty = parseInt(sel?.qty) || 0;
        totalQty += qty;
    });
    
    const countEl = document.getElementById('consign-selected-count');
    const qtyEl = document.getElementById('consign-selected-qty');
    const totalEl = document.getElementById('consign-selected-total');
    const btn = document.getElementById('btn-save-consignment');
    
    if (countEl) countEl.textContent = keys.length;
    if (qtyEl) qtyEl.textContent = totalQty.toLocaleString();
    if (totalEl) totalEl.textContent = keys.length;
    if (btn) btn.disabled = keys.length === 0;
    
    console.log('📊 統計更新:', keys.length, '筆,', totalQty, '件');
};

// 儲存寄庫
window.saveNewConsignment = async function() {
    const customer = document.getElementById('consign-customer')?.value.trim();
    const rate = parseFloat(document.getElementById('consign-rate')?.value) || 0.37;
    const consignDate = document.getElementById('consign-date')?.value;
    const freeUntil = document.getElementById('consign-free-until')?.value;
    
    if (!customer) { alert('請輸入客戶名稱'); return; }
    
    const keys = Object.keys(window.consignStockSelected);
    if (keys.length === 0) { alert('請選擇品項'); return; }
    
    const freeUntilDate = new Date(freeUntil);
    const chargeStartDate = new Date(freeUntilDate);
    chargeStartDate.setDate(chargeStartDate.getDate() + 1);
    const chargeStartStr = chargeStartDate.toLocalYMD();
    
    try {
        let count = 0, totalQty = 0;
        
        for (const key of keys) {
            const sel = window.consignStockSelected[key];
            const item = sel.item;
            
            await window.saveConsignmentToFirebase({
                source: item.stockType,
                sourceWarehouse: item.warehouseName,
                locationId: item.stockType === 'internal' ? (item.locationId || '') : '',
                productName: item.productName,
                spec: item.spec || '',
                batchNo: item.batchNo || '',
                expDate: item.expDate || '',
                customer: customer,
                originalQty: sel.qty,
                remainingQty: sel.qty,
                consignmentDate: consignDate,
                freeUntil: freeUntil,
                chargeStartDate: chargeStartStr,
                ratePerUnit: rate,
                note: '',
                pickups: [],
                status: 'active',
                createdAt: new Date().toISOString()
            });
            console.log('💾 儲存寄庫: stockType=' + item.stockType + ' locationId=' + (item.stockType === 'internal' ? (item.locationId || '') : '') + ' customer=' + customer);
            count++;
            totalQty += sel.qty;
        }
        
        WMS.closeModal('consignment-modal');
        showNotification(`✅ 已寄庫 ${count} 筆，共 ${totalQty.toLocaleString()} 件 → ${customer}`, 'success');
        
        if (typeof loadConsignmentList === 'function') setTimeout(loadConsignmentList, 100);
        
    } catch (e) {
        console.error('寄庫失敗:', e);
        alert('❌ 寄庫失敗：' + e.message);
    }
};

window.warehouseConfig = {
    internal: [
        '崇文_成品', '崇文_原料', '崇文_白蝦', '崇文_半成品庫', '崇文_退貨庫',
        '八方_成品', '八方_原料', '八方_白蝦'
    ],
    external: [
        '崇文_洽通', '崇文_有興', '崇文_品順', '崇文_富崐', '崇文_景山1號', '崇文_景山2號',
        '八方_洽通', '八方_有興', '八方_品順', '八方_富崐', '八方_景山1號',
        '張春梅_有興', '張春梅_原料', '張春梅_景山1號',
        '客戶代工倉', '貨品暫存庫'
    ],
    consign: [
        '(惠敏)客戶寄庫倉', '崇文(惠-布袋)客戶寄庫倉', '崇文(業務)客戶寄庫倉',
        '崇文_寄庫倉', 'PCHOME寄倉'
    ]
};

// ========== 寄庫作業分頁功能 ==========

// 全域變數
window.consignOpData = [];          // 庫存資料
window.consignOpSelected = {};      // 已選項目 { key: { item, qty } }
window.consignOpFilter = 'all';     // 篩選：all / internal / external

// 載入寄庫作業頁面
window.loadConsignOpList = function() {
    const tbody = document.getElementById('consign-op-list');
    if (!tbody) return;
    
    tbody.innerHTML = '<tr><td colspan="12" class="text-center text-slate-500 py-10"><i class="fa-solid fa-spinner fa-spin mr-2"></i>載入中...</td></tr>';
    
    // 合併內倉和外倉庫存
    const internalInventory = window.currentInventory ? window.currentInventory() : [];
    const externalInventory = window.externalStock || [];
    
    // 建立已寄倉數量對照表
    const consignedMap = {};
    if (window.consignmentData && Array.isArray(window.consignmentData)) {
        window.consignmentData.forEach(c => {
            if (c.status !== 'active') return;
            const key = `${c.productName || ''}|${c.spec || ''}|${c.batchNo || ''}|${c.sourceWarehouse || ''}`;
            consignedMap[key] = (consignedMap[key] || 0) + (c.remainingQty || 0);
        });
    }
    
    const allItems = [];
    
    // 處理內倉庫存
    internalInventory.forEach(item => {
        if (!item.productName || (item.quantity || 0) <= 0) return;
        const status = (item.status || '').toLowerCase();
        if (status === 'shipped' || status === 'outbound' || status === 'deleted') return;
        
        const warehouseName = item.warehouse || item.company || '內倉';
        const key = `${item.productName}|${item.spec || ''}|${item.batchNo || ''}|${warehouseName}`;
        const consigned = consignedMap[key] || 0;
        const available = Math.max(0, (item.quantity || 0) - consigned);
        
        allItems.push({
            id: item.id,
            stockType: 'internal',
            company: item.company || '崇文',
            productName: item.productName,
            spec: item.spec || '',
            batchNo: item.batchNo || '',
            quantity: item.quantity || 0,
            consigned: consigned,
            available: available,
            locationId: item.locationId || '',
            warehouseName: warehouseName,
            expDate: item.expiryDate ? (item.expiryDate.toDate ? item.expiryDate.toDate().toLocaleDateString('zh-TW') : new Date(item.expiryDate).toLocaleDateString('zh-TW')) : '-',
            key: key
        });
    });
    
    // 處理外倉庫存
    externalInventory.forEach(item => {
        if (!item.productName || (item.quantity || 0) <= 0) return;
        
        let warehouseName = item.warehouseId || '';
        const wh = (window.warehousesData || []).find(w => w.code === item.warehouseId || w.id === item.warehouseId);
        if (wh) {
            warehouseName = wh.company + '_' + wh.name;
        } else if (item.company) {
            warehouseName = item.company + '_' + (item.warehouseId || '外倉');
        }
        
        const key = `${item.productName}|${item.spec || ''}|${item.batchNo || ''}|${warehouseName}`;
        const consigned = consignedMap[key] || 0;
        const available = Math.max(0, (item.quantity || 0) - consigned);
        
        allItems.push({
            id: item.id,
            stockType: 'external',
            company: item.company || '崇文',
            productName: item.productName,
            spec: item.spec || '',
            batchNo: item.batchNo || '',
            quantity: item.quantity || 0,
            consigned: consigned,
            available: available,
            locationId: warehouseName,
            warehouseName: warehouseName,
            expDate: item.expDate || '-',
            key: key
        });
    });
    
    // 排序：品名 → 規格 → 批號
    allItems.sort((a, b) => {
        const nameCompare = (a.productName || '').localeCompare(b.productName || '', 'zh-TW');
        if (nameCompare !== 0) return nameCompare;
        const specCompare = (a.spec || '').localeCompare(b.spec || '', 'zh-TW');
        if (specCompare !== 0) return specCompare;
        return (a.batchNo || '').localeCompare(b.batchNo || '', 'zh-TW');
    });
    
    window.consignOpData = allItems;
    
    renderConsignOpList();
};

// 渲染庫存清單
window.renderConsignOpList = function() {
    const tbody = document.getElementById('consign-op-list');
    if (!tbody) return;
    
    const searchText = (document.getElementById('consign-op-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignOpFilter || 'all';
    
    // 過濾
    let filtered = window.consignOpData.filter(item => {
        // 類型篩選
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        
        // 搜尋
        if (searchText) {
            const match = 
                (item.productName || '').toLowerCase().includes(searchText) ||
                (item.spec || '').toLowerCase().includes(searchText) ||
                (item.batchNo || '').toLowerCase().includes(searchText) ||
                (item.locationId || '').toLowerCase().includes(searchText) ||
                (item.warehouseName || '').toLowerCase().includes(searchText);
            if (!match) return false;
        }
        
        return true;
    });
    
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="12" class="text-center text-slate-500 py-10">無符合條件的庫存</td></tr>';
        return;
    }
    
    let html = '';
    filtered.forEach((item, idx) => {
        const isInternal = item.stockType === 'internal';
        const typeClass = isInternal ? 'bg-blue-600' : 'bg-purple-600';
        const typeLabel = isInternal ? '內倉' : '外倉';
        const companyClass = item.company === '八方' ? 'bg-purple-900/50 text-purple-300' : 'bg-blue-900/50 text-blue-300';
        const availableClass = item.available > 0 ? 'text-emerald-400' : 'text-red-400';
        const disabled = item.available <= 0;
        
        // 檢查是否已選
        const selected = window.consignOpSelected[item.key];
        const isChecked = !!selected;
        const currentQty = selected ? selected.qty : '';
        const rowClass = isChecked ? 'bg-emerald-900/30' : '';
        
        // 效期顏色
        let expClass = 'text-slate-400';
        if (item.expDate && item.expDate !== '-') {
            try {
                const expDate = new Date(item.expDate);
                const today = new Date();
                const diffDays = Math.ceil((expDate - today) / (1000 * 60 * 60 * 24));
                if (diffDays < 0) expClass = 'text-red-500 font-bold';
                else if (diffDays < 30) expClass = 'text-red-400';
                else if (diffDays < 90) expClass = 'text-yellow-400';
            } catch(e) {}
        }
        
        html += `
            <tr class="border-b border-slate-700 hover:bg-slate-800 ${rowClass}" data-key="${item.key}">
                <td class="p-2 text-center">
                    <input type="checkbox" 
                        class="consign-op-checkbox w-4 h-4"
                        data-idx="${idx}"
                        ${isChecked ? 'checked' : ''}
                        ${disabled ? 'disabled' : ''}
                        onchange="toggleConsignOpItem(${idx}, this.checked)"
                    >
                </td>
                <td class="p-2"><span class="px-1.5 py-0.5 rounded text-[10px] ${typeClass}">${typeLabel}</span></td>
                <td class="p-2"><span class="px-1.5 py-0.5 rounded text-xs ${companyClass}">${item.company}</span></td>
                <td class="p-2 text-white">${item.productName}</td>
                <td class="p-2 text-yellow-400">${item.spec || '-'}</td>
                <td class="p-2 text-slate-400 font-mono text-sm">${item.batchNo || '-'}</td>
                <td class="p-2 text-right text-white">${item.quantity}</td>
                <td class="p-2 text-right ${item.consigned > 0 ? 'text-amber-400' : 'text-slate-500'}">${item.consigned || '-'}</td>
                <td class="p-2 text-right ${availableClass} font-bold">${item.available}</td>
                <td class="p-2 ${isInternal ? 'text-cyan-400' : 'text-teal-400'} font-mono text-sm">${item.locationId || '-'}</td>
                <td class="p-2 ${expClass}">${item.expDate}</td>
                <td class="p-2 text-center">
                    <input type="number" 
                        class="scan-input w-20 py-1 text-center text-sm ${disabled ? 'opacity-50' : ''}"
                        data-idx="${idx}"
                        min="1"
                        max="${item.available}"
                        value="${currentQty}"
                        placeholder="${item.available}"
                        ${disabled ? 'disabled' : ''}
                        onchange="updateConsignOpQty(${idx}, this.value)"
                        onfocus="this.select()"
                    >
                </td>
            </tr>
        `;
    });
    
    tbody.innerHTML = html;
    
    updateConsignOpSummary();
};

// 篩選類型
window.setConsignStockType = function(type) {
    window.consignOpFilter = type;
    
    // 更新按鈕樣式
    ['all', 'internal', 'external'].forEach(t => {
        const btn = document.getElementById(`btn-consign-${t}`);
        if (btn) {
            if (t === type) {
                btn.className = 'px-3 py-1.5 rounded text-xs font-bold bg-slate-600 text-white';
            } else {
                btn.className = 'px-3 py-1.5 rounded text-xs font-bold bg-slate-700 text-slate-300 hover:bg-slate-600';
            }
        }
    });
    
    renderConsignOpList();
};

// 搜尋過濾
window.filterConsignOpList = function() {
    renderConsignOpList();
};

// 全選/取消全選
window.toggleConsignOpAll = function(checked) {
    const checkboxes = document.querySelectorAll('.consign-op-checkbox:not(:disabled)');
    checkboxes.forEach(cb => {
        const idx = parseInt(cb.dataset.idx);
        cb.checked = checked;
        toggleConsignOpItem(idx, checked, false);
    });
    updateConsignOpSummary();
};

// 單選項目
window.toggleConsignOpItem = function(idx, checked, updateSummary = true) {
    const searchText = (document.getElementById('consign-op-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignOpFilter || 'all';
    
    // 取得過濾後的資料
    let filtered = window.consignOpData.filter(item => {
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        if (searchText) {
            const match = 
                (item.productName || '').toLowerCase().includes(searchText) ||
                (item.spec || '').toLowerCase().includes(searchText) ||
                (item.batchNo || '').toLowerCase().includes(searchText) ||
                (item.locationId || '').toLowerCase().includes(searchText);
            if (!match) return false;
        }
        return true;
    });
    
    const item = filtered[idx];
    if (!item) return;
    
    if (checked) {
        // 取得數量輸入框的值
        const qtyInput = document.querySelector(`input[type="number"][data-idx="${idx}"]`);
        const qty = parseInt(qtyInput?.value) || item.available;
        
        window.consignOpSelected[item.key] = {
            item: item,
            qty: Math.min(qty, item.available)
        };
        
        // 更新輸入框
        if (qtyInput && !qtyInput.value) {
            qtyInput.value = item.available;
        }
        
        // 更新列樣式
        const row = document.querySelector(`tr[data-key="${item.key}"]`);
        if (row) row.classList.add('bg-emerald-900/30');
    } else {
        delete window.consignOpSelected[item.key];
        
        // 更新列樣式
        const row = document.querySelector(`tr[data-key="${item.key}"]`);
        if (row) row.classList.remove('bg-emerald-900/30');
    }
    
    if (updateSummary) {
        updateConsignOpSummary();
    }
};

// 更新數量
window.updateConsignOpQty = function(idx, value) {
    const searchText = (document.getElementById('consign-op-search')?.value || '').toLowerCase().trim();
    const typeFilter = window.consignOpFilter || 'all';
    
    let filtered = window.consignOpData.filter(item => {
        if (typeFilter === 'internal' && item.stockType !== 'internal') return false;
        if (typeFilter === 'external' && item.stockType !== 'external') return false;
        if (searchText) {
            const match = 
                (item.productName || '').toLowerCase().includes(searchText) ||
                (item.spec || '').toLowerCase().includes(searchText) ||
                (item.batchNo || '').toLowerCase().includes(searchText) ||
                (item.locationId || '').toLowerCase().includes(searchText);
            if (!match) return false;
        }
        return true;
    });
    
    const item = filtered[idx];
    if (!item) return;
    
    const qty = parseInt(value) || 0;
    
    if (qty > 0 && qty <= item.available) {
        // 自動勾選
        const checkbox = document.querySelector(`.consign-op-checkbox[data-idx="${idx}"]`);
        if (checkbox && !checkbox.checked) {
            checkbox.checked = true;
        }
        
        window.consignOpSelected[item.key] = {
            item: item,
            qty: qty
        };
        
        const row = document.querySelector(`tr[data-key="${item.key}"]`);
        if (row) row.classList.add('bg-emerald-900/30');
    } else if (qty <= 0) {
        // 取消勾選
        const checkbox = document.querySelector(`.consign-op-checkbox[data-idx="${idx}"]`);
        if (checkbox) checkbox.checked = false;
        
        delete window.consignOpSelected[item.key];
        
        const row = document.querySelector(`tr[data-key="${item.key}"]`);
        if (row) row.classList.remove('bg-emerald-900/30');
    } else if (qty > item.available) {
        // 超過可寄數量
        const qtyInput = document.querySelector(`input[type="number"][data-idx="${idx}"]`);
        if (qtyInput) qtyInput.value = item.available;
        updateConsignOpQty(idx, item.available);
        return;
    }
    
    updateConsignOpSummary();
};

// 更新統計
window.updateConsignOpSummary = function() {
    const countEl = document.getElementById('consign-op-selected-count');
    const qtyEl = document.getElementById('consign-op-selected-qty');
    const btnConfirm = document.getElementById('btn-consign-op-confirm');
    
    const selectedKeys = Object.keys(window.consignOpSelected);
    const totalQty = selectedKeys.reduce((sum, key) => sum + (window.consignOpSelected[key]?.qty || 0), 0);
    
    if (countEl) countEl.textContent = selectedKeys.length;
    if (qtyEl) qtyEl.textContent = totalQty.toLocaleString();
    
    if (btnConfirm) {
        btnConfirm.disabled = selectedKeys.length === 0;
    }
};

// 開啟確認寄庫視窗
window.openConsignOpConfirm = function() {
    const selectedKeys = Object.keys(window.consignOpSelected);
    if (selectedKeys.length === 0) {
        alert('請先選擇要寄庫的品項');
        return;
    }
    
    const totalQty = selectedKeys.reduce((sum, key) => sum + (window.consignOpSelected[key]?.qty || 0), 0);
    
    // 取得預設日期
    const today = new Date();
    const freeUntilDay = (window.rentalSettings && window.rentalSettings.settlement) ? window.rentalSettings.settlement.freeUntilDay : 25;
    let freeUntil = new Date(today.getFullYear(), today.getMonth(), freeUntilDay);
    if (today.getDate() > freeUntilDay) {
        freeUntil = new Date(today.getFullYear(), today.getMonth() + 1, freeUntilDay);
    }
    const freeUntilStr = freeUntil.toLocalYMD();
    const todayStr = today.toLocalYMD();
    
    // 建立已選清單
    let itemsHtml = '';
    selectedKeys.forEach(key => {
        const sel = window.consignOpSelected[key];
        const item = sel.item;
        const isInternal = item.stockType === 'internal';
        const typeClass = isInternal ? 'text-blue-400' : 'text-purple-400';
        
        itemsHtml += `
            <div class="flex items-center justify-between py-1 border-b border-slate-700">
                <div class="flex-1 min-w-0">
                    <div class="text-white text-sm truncate">${item.productName}</div>
                    <div class="text-slate-500 text-xs">${item.spec || '-'} | ${item.batchNo || '-'}</div>
                    <div class="${typeClass} text-xs">${item.warehouseName}</div>
                </div>
                <div class="text-emerald-400 font-bold ml-2">${sel.qty}</div>
            </div>
        `;
    });
    
    const content = `
        <div class="flex gap-4" style="max-height: 500px;">
            <!-- 左側：寄庫資訊 -->
            <div class="w-72 space-y-3">
                <div>
                    <label class="text-slate-400 text-sm">客戶名稱 *</label>
                    <input type="text" id="consign-op-customer" class="scan-input w-full mt-1" placeholder="輸入客戶名稱...">
                </div>
                <div class="grid grid-cols-2 gap-2">
                    <div>
                        <label class="text-slate-400 text-sm">費率</label>
                        <input type="number" id="consign-op-rate" class="scan-input w-full mt-1" value="0.37" step="0.01">
                    </div>
                    <div>
                        <label class="text-slate-400 text-sm">寄倉日</label>
                        <input type="date" id="consign-op-date" class="scan-input w-full mt-1" value="${todayStr}">
                    </div>
                </div>
                <div>
                    <label class="text-slate-400 text-sm">免費至</label>
                    <input type="date" id="consign-op-free-until" class="scan-input w-full mt-1" value="${freeUntilStr}">
                </div>
                <div class="pt-2 border-t border-slate-700">
                    <div class="flex justify-between text-sm">
                        <span class="text-slate-400">共 ${selectedKeys.length} 筆</span>
                        <span class="text-emerald-400 font-bold">${totalQty.toLocaleString()} 件</span>
                    </div>
                </div>
            </div>
            
            <!-- 右側：已選清單 -->
            <div class="flex-1 flex flex-col min-w-0">
                <div class="text-slate-400 text-sm mb-2">已選品項</div>
                <div class="flex-1 overflow-y-auto bg-slate-800/50 rounded p-2 space-y-1" style="max-height: 350px;">
                    ${itemsHtml}
                </div>
            </div>
        </div>
        
        <div class="flex justify-end gap-2 mt-4 pt-3 border-t border-slate-700">
            <button onclick="WMS.closeModal('consign-op-confirm-modal')" class="px-4 py-2 bg-slate-600 hover:bg-slate-500 text-white rounded">取消</button>
            <button onclick="saveConsignOp()" class="px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded font-bold">
                <i class="fa-solid fa-check mr-1"></i>確認寄庫
            </button>
        </div>
    `;
    
    WMS.createModal('consign-op-confirm-modal', {
        title: '確認寄庫',
        icon: 'fa-solid fa-box-archive text-amber-400',
        content: content,
        width: '650px'
    });
    
    setTimeout(() => {
        document.getElementById('consign-op-customer')?.focus();
    }, 100);
};

// 儲存寄庫
window.saveConsignOp = async function() {
    const customer = document.getElementById('consign-op-customer')?.value.trim();
    const rate = parseFloat(document.getElementById('consign-op-rate')?.value) || 0.37;
    const consignDate = document.getElementById('consign-op-date')?.value;
    const freeUntil = document.getElementById('consign-op-free-until')?.value;
    
    if (!customer) {
        alert('請輸入客戶名稱');
        document.getElementById('consign-op-customer')?.focus();
        return;
    }
    
    const selectedKeys = Object.keys(window.consignOpSelected);
    if (selectedKeys.length === 0) {
        alert('無選擇品項');
        return;
    }
    
    // 計算計費開始日
    const freeUntilDate = new Date(freeUntil);
    const chargeStartDate = new Date(freeUntilDate);
    chargeStartDate.setDate(chargeStartDate.getDate() + 1);
    const chargeStartStr = chargeStartDate.toLocalYMD();
    
    try {
        let savedCount = 0;
        let totalQty = 0;
        
        for (const key of selectedKeys) {
            const sel = window.consignOpSelected[key];
            const item = sel.item;
            
            const consignment = {
                source: item.stockType,
                sourceWarehouse: item.warehouseName,
                locationId: item.stockType === 'internal' ? (item.locationId || '') : '',
                productName: item.productName,
                spec: item.spec || '',
                batchNo: item.batchNo || '',
                expDate: item.expDate || '',
                customer: customer,
                originalQty: sel.qty,
                remainingQty: sel.qty,
                consignmentDate: consignDate,
                freeUntil: freeUntil,
                chargeStartDate: chargeStartStr,
                ratePerUnit: rate,
                note: '',
                pickups: [],
                status: 'active',
                createdAt: new Date().toISOString()
            };
            
            await window.saveConsignmentToFirebase(consignment);
            savedCount++;
            totalQty += sel.qty;
        }
        
        WMS.closeModal('consign-op-confirm-modal');
        showNotification(`✅ 已寄庫 ${savedCount} 筆，共 ${totalQty.toLocaleString()} 件 → ${customer}`, 'success');
        
        // 清空已選
        window.consignOpSelected = {};
        
        // 重新載入
        loadConsignOpList();
        
        // 刷新寄倉管理
        if (typeof loadConsignmentList === 'function') {
            setTimeout(() => loadConsignmentList(), 100);
        }
        
    } catch (e) {
        console.error('寄庫失敗:', e);
        alert('❌ 寄庫失敗：' + e.message);
    }
};

// 頁籤切換時自動載入
(function() {
    const _origSwitchTabForConsignOp = window.switchTab;
    window.switchTab = function(tab, event) {
        if (typeof _origSwitchTabForConsignOp === 'function') {
            _origSwitchTabForConsignOp(tab, event);
        }
        
        if (tab === 'consign-operation') {
            setTimeout(() => {
                loadConsignOpList();
            }, 100);
        }
    };
})();

window.loadConsignmentList = function() {
    const tbody = document.getElementById('consignment-list');
    if (!tbody) return;

    const statusFilter = document.getElementById('consign-status-filter')?.value || 'all';
    const sourceFilter = document.getElementById('consign-source-filter')?.value || 'all';
    const searchText = (document.getElementById('consign-search')?.value || '').toLowerCase();

    let data = [...window.consignmentData]; // 複製陣列避免排序影響原資料

    data.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

    const today = new Date();
    const todayStr = today.toLocalYMD();

    if (statusFilter === 'free') {
        data = data.filter(c => c.status === 'active' && c.freeUntil >= todayStr);
    } else if (statusFilter === 'charging') {
        data = data.filter(c => c.status === 'active' && c.freeUntil < todayStr);
    } else if (statusFilter === 'completed') {
        data = data.filter(c => c.status === 'completed');
    }

    if (sourceFilter === 'internal') {
        data = data.filter(c => c.source !== 'external');
    } else if (sourceFilter === 'external') {
        data = data.filter(c => c.source === 'external');
    }

    if (searchText) {
        data = data.filter(c =>
            (c.customer || '').toLowerCase().includes(searchText) ||
            (c.productName || '').toLowerCase().includes(searchText) ||
            (c.batchNo || '').toLowerCase().includes(searchText) ||
            (c.sourceWarehouse || '').toLowerCase().includes(searchText) ||
            (c.targetWarehouse || '').toLowerCase().includes(searchText)
        );
    }

    let freeCount = 0, chargingCount = 0, expiringCount = 0, totalUnits = 0, totalRent = 0;
    const thisMonth = today.getMonth();

    window.consignmentData.forEach(c => {
        if (c.status !== 'active') return;
        totalUnits += c.remainingQty;

        if (c.freeUntil >= todayStr) {
            freeCount++;
        } else {
            chargingCount++;
            const chargeStart = new Date(c.chargeStartDate);
            const daysDiff = Math.max(0, Math.floor((today - chargeStart) / (1000 * 60 * 60 * 24)));
            totalRent += c.remainingQty * c.ratePerUnit * daysDiff;
        }

        const freeUntilDate = new Date(c.freeUntil);
        if (freeUntilDate.getMonth() === thisMonth) {
            expiringCount++;
        }
    });

    const el = (id) => document.getElementById(id);
    if (el('consign-free-count')) el('consign-free-count').textContent = freeCount;
    if (el('consign-charging-count')) el('consign-charging-count').textContent = chargingCount;
    if (el('consign-expiring-count')) el('consign-expiring-count').textContent = expiringCount;
    if (el('consign-total-units')) el('consign-total-units').textContent = totalUnits.toLocaleString();
    if (el('consign-total-rent')) el('consign-total-rent').textContent = '$' + Math.round(totalRent).toLocaleString();

    if (data.length === 0) {
        tbody.innerHTML = '<tr><td colspan="12" class="text-center text-slate-500 py-10">尚無寄倉資料</td></tr>';
        return;
    }

    let html = '';
    data.forEach(c => {
        const isFree = c.freeUntil >= todayStr;
        const statusBadge = c.status === 'completed'
            ? '<span class="badge badge-slate">已結清</span>'
            : isFree
                ? '<span class="badge badge-green">免費期</span>'
                : '<span class="badge badge-yellow">計費中</span>';

        const sourceWarehouse = c.sourceWarehouse || (c.source === 'external' ? '外倉' : '內倉');
        const isInternal = c.source !== 'external';
        const sourceClass = isInternal ? 'text-blue-400' : 'text-purple-400';

        const targetWarehouse = c.targetWarehouse || '-';

        let chargeDays = 0;
        let accumulatedRent = 0;
        if (!isFree && c.status === 'active') {
            const chargeStart = new Date(c.chargeStartDate);
            chargeDays = Math.max(0, Math.floor((today - chargeStart) / (1000 * 60 * 60 * 24)));
            accumulatedRent = c.remainingQty * c.ratePerUnit * chargeDays;
        }

        html += `
            <tr class="border-b border-slate-700 hover:bg-slate-800">
                <td class="p-2 text-xs ${sourceClass}">${sourceWarehouse}</td>
                <td class="p-2 text-xs text-amber-400">${targetWarehouse}</td>
                <td class="p-2 font-bold text-white">${c.customer}</td>
                <td class="p-2 text-white text-sm">${c.productName}<span class="text-slate-500 text-xs ml-1">${c.spec || ''}</span></td>
                <td class="p-2 text-slate-400 text-xs font-mono">${c.batchNo || '-'}</td>
                <td class="p-2 text-right text-slate-400">${c.originalQty}</td>
                <td class="p-2 text-right font-bold text-white">${c.remainingQty}</td>
                <td class="p-2 text-xs ${isFree ? 'text-emerald-400' : 'text-orange-400'}">${c.freeUntil}</td>
                <td class="p-2 text-right text-slate-400">${chargeDays}</td>
                <td class="p-2 text-right font-bold text-yellow-400">$${Math.round(accumulatedRent).toLocaleString()}</td>
                <td class="p-2">${statusBadge}</td>
                <td class="p-2 text-center">
                    ${c.status === 'active' ? `
                        <button onclick="openPickupModal('${c.id}')" class="text-blue-400 hover:bg-blue-500/20 rounded px-2 py-1 mr-1" title="提貨">
                            <i class="fa-solid fa-truck-ramp-box"></i>
                        </button>
                        <button onclick="deleteConsignment('${c.id}')" class="text-red-400 hover:bg-red-500/20 rounded px-2 py-1" title="刪除">
                            <i class="fa-solid fa-trash"></i>
                        </button>
                    ` : '-'}
                </td>
            </tr>
        `;
    });

    tbody.innerHTML = html;
};

window.filterConsignments = function() {
    loadConsignmentList();
};

window.openPickupModal = function(consignmentId) {
    const c = window.consignmentData.find(item => item.id === consignmentId);
    if (!c) return;

    const todayStr = new Date().toLocalYMD();

    const content = `
        <div class="space-y-4">
            <div class="bg-slate-800 rounded-lg p-3">
                <div class="text-white font-bold">${c.customer}</div>
                <div class="text-sm text-slate-400">${c.productName} | ${c.spec || '-'}</div>
                <div class="text-sm text-slate-400">剩餘：<span class="text-emerald-400 font-bold">${c.remainingQty}</span> 件</div>
            </div>
            <div class="grid grid-cols-2 gap-3">
                <div>
                    <label class="text-sm text-slate-400 mb-1 block">提貨日期</label>
                    <input type="date" id="pickup-date" class="scan-input" value="${todayStr}">
                </div>
                <div>
                    <label class="text-sm text-slate-400 mb-1 block">提貨件數 *</label>
                    <input type="number" id="pickup-qty" class="scan-input" placeholder="${c.remainingQty}" min="1" max="${c.remainingQty}">
                </div>
            </div>
            <div class="flex gap-2">
                <button onclick="savePickup('${consignmentId}')" class="flex-1 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg font-bold">
                    <i class="fa-solid fa-truck-ramp-box mr-1"></i>確認提貨
                </button>
                <button onclick="WMS.closeModal('pickup-modal')" class="px-4 py-2 bg-slate-700 hover:bg-slate-600 text-white rounded-lg">
                    取消
                </button>
            </div>
        </div>
    `;

    WMS.createModal('pickup-modal', {
        title: '客戶提貨',
        icon: 'fa-solid fa-truck-ramp-box text-blue-400',
        content: content,
        width: '400px'
    });
};

window.savePickup = async function(consignmentId) {
    const pickupDate = document.getElementById('pickup-date')?.value;
    const pickupQty = parseInt(document.getElementById('pickup-qty')?.value) || 0;

    const c = window.consignmentData.find(item => item.id === consignmentId);
    if (!c) return;

    if (pickupQty <= 0) {
        alert('請輸入提貨件數');
        return;
    }
    if (pickupQty > c.remainingQty) {
        alert(`提貨件數不能超過剩餘 ${c.remainingQty} 件`);
        return;
    }

    c.pickups.push({
        date: pickupDate,
        qty: pickupQty
    });

    c.remainingQty -= pickupQty;

    if (c.remainingQty <= 0) {
        c.status = 'completed';
        c.completedAt = new Date().toISOString();
    }

    try {
        await window.updateConsignmentInFirebase(consignmentId, {
            pickups: c.pickups,
            remainingQty: c.remainingQty,
            status: c.status,
            completedAt: c.completedAt || null
        });

        WMS.closeModal('pickup-modal');
        showNotification(`✅ 已提貨 ${pickupQty} 件`, 'success');
        loadConsignmentList();
    } catch(e) {
        console.error('提貨儲存失敗:', e);
        alert('❌ 儲存失敗：' + e.message);
    }
};

window.deleteConsignment = async function(consignmentId) {
    if (!confirm('確定要刪除此寄倉記錄嗎？')) return;

    try {
        await window.deleteConsignmentFromFirebase(consignmentId);
        showNotification('✅ 已刪除寄倉記錄', 'success');
        loadConsignmentList();
    } catch(e) {
        console.error('刪除失敗:', e);
        alert('❌ 刪除失敗：' + e.message);
    }
};

// 展開/收合客戶明細
window.toggleCustomerDetail = function(detailId) {
    const detail = document.getElementById(detailId);
    const icon = document.getElementById(detailId + '-icon');
    if (detail && icon) {
        if (detail.classList.contains('hidden')) {
            detail.classList.remove('hidden');
            icon.style.transform = 'rotate(90deg)';
        } else {
            detail.classList.add('hidden');
            icon.style.transform = 'rotate(0deg)';
        }
    }
};

window.loadRentalReport = async function() {
    const monthInput = document.getElementById('rental-month');
    if (!monthInput || !monthInput.value) return;

    const [year, month] = monthInput.value.split('-').map(Number);
    const settleDay = (window.rentalSettings && window.rentalSettings.settlement) ? window.rentalSettings.settlement.settleDay : 25;

    // 計算結算期間（上月結算日+1 到 本月結算日）
    // 例如：選擇 2025-01，期間為 2024/12/26 ~ 2025/01/25
    const startDate = new Date(year, month - 2, settleDay + 1);
    const endDate = new Date(year, month - 1, settleDay);
    const today = new Date();
    
    // 如果結算日還沒到，用今天作為結束日
    const actualEndDate = endDate > today ? today : endDate;
    const daysInPeriod = Math.max(1, Math.floor((actualEndDate - startDate) / (1000 * 60 * 60 * 24)) + 1);

    console.log('📊 倉租計算期間:', startDate.toLocaleDateString(), '~', actualEndDate.toLocaleDateString(), '共', daysInPeriod, '天');

    // ========== 1. 計算自有庫存倉租（崇文/八方）==========
    // 這是本倉庫中，崇文和八方自己的庫存的帳面成本
    let ownStockData = { '崇文': { pallets: 0, palletDays: 0, rent: 0, rate: 22 }, '八方': { pallets: 0, palletDays: 0, rent: 0, rate: 22 } };
    
    try {
        // 取得目前庫存（只計算本倉，排除外倉和寄倉）
        let currentPallets = [];
        if (window.db && window.collection && window.getDocs) {
            const snapshot = await window.getDocs(window.collection(window.db, 'pallets'));
            snapshot.forEach(doc => {
                const data = doc.data();
                // 只計算有數量且在本倉（I/J/K 區）的庫存
                if (data.quantity > 0 && data.locationId && /^[IJK]-/.test(data.locationId)) {
                    currentPallets.push(data);
                }
            });
        }

        // 計算各公司的板數和倉租
        const companies = ['崇文', '八方'];
        companies.forEach(company => {
            const companyPallets = currentPallets.filter(p => p.company === company);
            const palletCount = companyPallets.length;
            const palletDays = palletCount * daysInPeriod;
            
            // 取得費率設定
            let rate = 22; // 預設費率
            if (company === '八方' && window.rentalSettings && window.rentalSettings.storageRate) {
                rate = window.rentalSettings.storageRate.bafang || 22;
            } else if (company === '崇文' && window.rentalSettings && window.rentalSettings.storageRate) {
                const cwRates = window.rentalSettings.storageRate.chungwen;
                if (cwRates && palletCount > (cwRates.tier1Max || 300)) {
                    rate = cwRates.tier2Rate || 20;
                } else {
                    rate = cwRates ? (cwRates.tier1Rate || 22) : 22;
                }
            }
            
            const rent = palletDays * rate;
            
            ownStockData[company] = {
                pallets: palletCount,
                palletDays: palletDays,
                rent: rent,
                rate: rate
            };
        });
        
        console.log('📦 自有庫存:', ownStockData);
        
    } catch(e) {
        console.error('計算自有庫存失敗:', e);
    }

    // 顯示自有庫存倉租（改善顯示格式）
    let ownStockHtml = '';
    let totalOwnRent = 0;
    
    Object.entries(ownStockData).forEach(([company, data]) => {
        // 計算說明：板數 × 天數 = 板天數，板天數 × 費率 = 金額
        const calculation = data.pallets > 0 ? 
            `${data.pallets}板 × ${daysInPeriod}天 × $${data.rate}` : '-';
        ownStockHtml += `
            <tr class="border-b border-slate-700">
                <td class="p-2 text-white font-bold">${company}</td>
                <td class="p-2 text-right">${data.pallets > 0 ? data.pallets + ' 板' : '-'}</td>
                <td class="p-2 text-right text-slate-400 text-xs">${data.pallets > 0 ? data.palletDays.toLocaleString() + ' 板天' : '-'}</td>
                <td class="p-2 text-right text-blue-400">${data.rent > 0 ? '$' + Math.round(data.rent).toLocaleString() : '-'}</td>
            </tr>
        `;
        totalOwnRent += data.rent;
    });
    
    // 加入計費說明
    ownStockHtml += `
        <tr class="border-t border-slate-600">
            <td colspan="4" class="p-2 text-slate-500 text-xs">
                📅 計費期間：${startDate.toLocaleDateString('zh-TW')} ~ ${actualEndDate.toLocaleDateString('zh-TW')}（${daysInPeriod} 天）
            </td>
        </tr>
    `;
    
    document.getElementById('own-stock-rental-body').innerHTML = ownStockHtml;
    document.getElementById('own-stock-total').textContent = totalOwnRent > 0 ? '$' + Math.round(totalOwnRent).toLocaleString() : '$0';

    // ========== 2. 計算客戶寄倉費用（含詳細明細）==========
    const customerDetails = {}; // 按客戶分組的明細
    const allDetails = []; // 所有明細（用於匯出）

    if (window.consignmentData && window.consignmentData.length > 0) {
        window.consignmentData.forEach(c => {
            if (c.status !== 'active') return;
            if (!c.remainingQty || c.remainingQty <= 0) return;
            
            const freeUntil = new Date(c.freeUntil);
            
            // 只計算免費期已過的
            if (freeUntil >= actualEndDate) return;
            
            // 計費開始日 = 免費期結束後一天 或 計費期間開始日（取較晚者）
            const chargeStartDate = new Date(freeUntil);
            chargeStartDate.setDate(chargeStartDate.getDate() + 1);
            const effectiveStart = new Date(Math.max(chargeStartDate.getTime(), startDate.getTime()));
            const effectiveEnd = actualEndDate;
            
            if (effectiveStart >= effectiveEnd) return;
            
            const days = Math.max(0, Math.floor((effectiveEnd - effectiveStart) / (1000 * 60 * 60 * 24)) + 1);
            const ratePerUnit = c.ratePerUnit || 0.37; // 預設費率
            const rent = c.remainingQty * ratePerUnit * days;

            // 建立明細記錄
            const detail = {
                customer: c.customer,
                productName: c.productName,
                spec: c.spec || '',
                batchNo: c.batchNo || '',
                qty: c.remainingQty,
                ratePerUnit: ratePerUnit,
                chargeStart: effectiveStart,
                chargeEnd: effectiveEnd,
                days: days,
                rent: rent,
                freeUntil: c.freeUntil
            };
            
            allDetails.push(detail);

            // 按客戶分組
            if (!customerDetails[c.customer]) {
                customerDetails[c.customer] = { items: [], totalQty: 0, totalDays: 0, totalRent: 0 };
            }
            customerDetails[c.customer].items.push(detail);
            customerDetails[c.customer].totalQty += c.remainingQty;
            customerDetails[c.customer].totalDays += c.remainingQty * days;
            customerDetails[c.customer].totalRent += rent;
        });
    }

    // 顯示客戶列表（可展開明細）
    let detailHtml = '';
    let totalConsignRent = 0;
    let customerIndex = 0;

    if (Object.keys(customerDetails).length === 0) {
        detailHtml = '<div class="text-center text-slate-500 py-6">本月無客戶寄倉費用</div>';
    } else {
        Object.entries(customerDetails).forEach(([customer, data]) => {
            totalConsignRent += data.totalRent;
            customerIndex++;
            const detailId = 'customer-detail-' + customerIndex;
            
            // 客戶標題列（點擊展開）
            detailHtml += `
                <div class="mb-2 bg-slate-800/50 rounded-lg overflow-hidden">
                    <div class="flex justify-between items-center p-3 cursor-pointer hover:bg-slate-700/50 transition-colors"
                         onclick="toggleCustomerDetail('${detailId}')">
                        <div class="flex items-center gap-2">
                            <i class="fa-solid fa-chevron-right text-slate-500 text-xs transition-transform" id="${detailId}-icon"></i>
                            <span class="text-white font-bold">${customer}</span>
                            <span class="text-slate-500 text-xs">(${data.items.length} 筆)</span>
                        </div>
                        <span class="text-amber-400 font-bold text-lg">$${Math.round(data.totalRent).toLocaleString()}</span>
                    </div>
                    
                    <!-- 明細（預設隱藏）-->
                    <div id="${detailId}" class="hidden border-t border-slate-700 p-3 bg-slate-900/30">
                        <table class="w-full text-xs">
                            <thead>
                                <tr class="text-slate-500">
                                    <th class="text-left py-1">品名</th>
                                    <th class="text-right py-1">件數</th>
                                    <th class="text-right py-1">費率</th>
                                    <th class="text-right py-1">天數</th>
                                    <th class="text-right py-1">金額</th>
                                </tr>
                            </thead>
                            <tbody>`;
            
            // 排序明細（相同品項排在一起）
            data.items.sort(function(a, b) {
                var nameCompare = (a.productName || '').localeCompare(b.productName || '', 'zh-TW');
                if (nameCompare !== 0) return nameCompare;
                var specCompare = (a.spec || '').localeCompare(b.spec || '', 'zh-TW');
                if (specCompare !== 0) return specCompare;
                return (a.batchNo || '').localeCompare(b.batchNo || '', 'zh-TW');
            });
            
            data.items.forEach(item => {
                const startStr = item.chargeStart.toLocaleDateString('zh-TW', {month:'numeric', day:'numeric'});
                const endStr = item.chargeEnd.toLocaleDateString('zh-TW', {month:'numeric', day:'numeric'});
                detailHtml += `
                                <tr class="text-slate-300 border-t border-slate-700/50">
                                    <td class="py-1.5">
                                        <div>${item.productName}</div>
                                        <div class="text-slate-500 text-[10px]">${startStr}~${endStr}</div>
                                    </td>
                                    <td class="text-right">${item.qty}</td>
                                    <td class="text-right text-slate-400">$${item.ratePerUnit.toFixed(2)}</td>
                                    <td class="text-right">${item.days}</td>
                                    <td class="text-right text-white">$${Math.round(item.rent).toLocaleString()}</td>
                                </tr>`;
            });
            
            detailHtml += `
                            </tbody>
                            <tfoot>
                                <tr class="border-t border-slate-600 text-slate-400">
                                    <td class="py-1.5 font-bold">小計</td>
                                    <td class="text-right">${data.totalQty} 件</td>
                                    <td></td>
                                    <td class="text-right text-[10px]">${data.totalDays} 件天</td>
                                    <td class="text-right text-amber-400 font-bold">$${Math.round(data.totalRent).toLocaleString()}</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                </div>`;
        });
        
        // 計算說明
        detailHtml += `
            <div class="text-slate-500 text-[10px] mt-2 p-2 bg-slate-800/30 rounded">
                💡 計算方式：件數 × 費率(元/件/天) × 計費天數 = 倉租金額<br>
                📅 計費期間：${startDate.toLocaleDateString('zh-TW')} ~ ${actualEndDate.toLocaleDateString('zh-TW')}
            </div>`;
    }

    document.getElementById('consign-rental-detail').innerHTML = detailHtml;
    document.getElementById('consign-total').textContent = '$' + Math.round(totalConsignRent).toLocaleString();

    // 儲存明細供匯出使用
    window._rentalReportDetails = allDetails;

    // ========== 3. 計算理貨費用 ==========
    let inboundCount = 0;
    try {
        if (window.db && window.collection && window.getDocs) {
            const logsSnapshot = await window.getDocs(window.collection(window.db, 'inventoryLogs'));
            logsSnapshot.forEach(doc => {
                const data = doc.data();
                if (data.type === 'inbound' && data.timestamp) {
                    const logDate = new Date(data.timestamp);
                    if (logDate >= startDate && logDate <= actualEndDate) {
                        inboundCount++;
                    }
                }
            });
        }
    } catch(e) {
        console.error('計算理貨費用失敗:', e);
    }
    
    const inboundFee = inboundCount * (window.rentalSettings && window.rentalSettings.handlingFee ? window.rentalSettings.handlingFee.inbound : 200);
    document.getElementById('handling-inbound-count').textContent = inboundCount;
    document.getElementById('handling-inbound-fee').textContent = '$' + inboundFee.toLocaleString();

    // ========== 4. 計算總計 ==========
    const monthlyTotal = totalConsignRent + inboundFee;
    document.getElementById('monthly-total').textContent = '$' + Math.round(monthlyTotal).toLocaleString();
    
    // 儲存計算結果供匯出使用
    window._rentalReportData = {
        period: { start: startDate, end: actualEndDate, days: daysInPeriod },
        ownStock: ownStockData,
        consignmentDetails: customerDetails,
        handling: { inboundCount, inboundFee },
        totals: { ownRent: totalOwnRent, consignRent: totalConsignRent, handling: inboundFee, grand: monthlyTotal }
    };
};

window.generateMonthlyBill = function() {
    const monthInput = document.getElementById('rental-month');
    if (!monthInput || !monthInput.value) {
        alert('請先選擇月份');
        return;
    }

    if (!window._rentalReportData) {
        alert('請先載入報表資料');
        return;
    }

    const data = window._rentalReportData;
    const [year, month] = monthInput.value.split('-').map(Number);
    const monthStr = year + '年' + month + '月';
    const periodStr = data.period.start.toLocaleDateString('zh-TW') + ' ~ ' + data.period.end.toLocaleDateString('zh-TW');

    // 建立 Excel 資料
    const wb = XLSX.utils.book_new();
    
    // ===== 工作表1：費用總表 =====
    const summaryRows = [
        ['倉租費用總表'],
        ['計費月份：' + monthStr],
        ['計費期間：' + periodStr],
        [],
        ['項目', '說明', '金額'],
        ['自有庫存倉租', '帳面成本，不收費', data.totals.ownRent],
        ['客戶寄倉費用', '應收帳款', data.totals.consignRent],
        ['理貨費用', '入庫 ' + data.handling.inboundCount + ' 板 × $200', data.totals.handling],
        [],
        ['本月應收總計', '', data.totals.consignRent + data.totals.handling],
        [],
        [],
        ['【自有庫存明細】'],
        ['公司', '現有板數', '板天數', '費率(元/板/天)', '倉租金額'],
    ];
    
    Object.entries(data.ownStock).forEach(([company, info]) => {
        if (info.pallets > 0) {
            summaryRows.push([company, info.pallets, info.palletDays, info.rate || 22, info.rent]);
        } else {
            summaryRows.push([company, 0, '-', '-', 0]);
        }
    });
    
    const ws1 = XLSX.utils.aoa_to_sheet(summaryRows);
    ws1['!cols'] = [{wch:20}, {wch:15}, {wch:15}];
    XLSX.utils.book_append_sheet(wb, ws1, '費用總表');
    
    // ===== 每個客戶一個獨立工作表 =====
    if (data.consignmentDetails && Object.keys(data.consignmentDetails).length > 0) {
        Object.entries(data.consignmentDetails).forEach(([customer, custData]) => {
            const custRows = [
                ['客戶寄倉帳單'],
                ['客戶名稱：' + customer],
                ['計費月份：' + monthStr],
                ['計費期間：' + periodStr],
                [],
                ['品名', '規格', '件數', '費率(元/件/天)', '計費起日', '計費迄日', '天數', '金額'],
            ];
            
            custData.items.forEach(item => {
                const startStr = item.chargeStart.toLocaleDateString('zh-TW');
                const endStr = item.chargeEnd.toLocaleDateString('zh-TW');
                
                custRows.push([
                    item.productName,
                    item.spec || '',
                    item.qty,
                    item.ratePerUnit.toFixed(4),
                    startStr,
                    endStr,
                    item.days,
                    Math.round(item.rent)
                ]);
            });
            
            custRows.push([]);
            custRows.push(['', '', custData.totalQty + ' 件', '', '', '合計', custData.totalDays + ' 件天', Math.round(custData.totalRent)]);
            custRows.push([]);
            custRows.push(['計算公式：件數 × 費率(元/件/天) × 計費天數 = 倉租金額']);
            
            // 工作表名稱（Excel 限制 31 字元，且不能有特殊字元）
            let sheetName = customer.replace(/[\\\/\?\*\[\]:]/g, '').substring(0, 28);
            if (!sheetName) sheetName = '客戶';
            
            const wsCustomer = XLSX.utils.aoa_to_sheet(custRows);
            wsCustomer['!cols'] = [{wch:18}, {wch:12}, {wch:8}, {wch:14}, {wch:12}, {wch:12}, {wch:8}, {wch:12}];
            XLSX.utils.book_append_sheet(wb, wsCustomer, sheetName);
        });
    }

    // 下載檔案
    const fileName = '倉租報表_' + year + ('0'+month).slice(-2) + '.xlsx';
    XLSX.writeFile(wb, fileName);
    
    showNotification('✅ 已產生帳單：' + fileName, 'success');
};

window.exportConsignments = function() {
    if (window.consignmentData.length === 0) {
        alert('沒有資料可匯出');
        return;
    }

    const data = window.consignmentData.map(c => ({
        '客戶': c.customer,
        '品名': c.productName,
        '規格': c.spec || '',
        '原始數量': c.originalQty,
        '剩餘數量': c.remainingQty,
        '寄倉日期': c.consignmentDate,
        '免費截止': c.freeUntil,
        '費率(元/件/天)': c.ratePerUnit?.toFixed(4) || '',
        '狀態': c.status === 'completed' ? '已結清' : '進行中',
        '備註': c.note || ''
    }));

    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '寄倉清單');
    XLSX.writeFile(wb, `寄倉清單_${new Date().toLocalYMD()}.xlsx`);

    showNotification('✅ 已匯出寄倉清單', 'success');
};

const originalSwitchTab = window.switchTab;
window.switchTab = function(viewId, event) {
    originalSwitchTab(viewId, event);

    if (viewId === 'consignment') {
        loadConsignmentList();
    } else if (viewId === 'rental-settings') {
        loadRentalSettingsUI();
    } else if (viewId === 'rental-report') {
        const monthInput = document.getElementById('rental-month');
        if (monthInput && !monthInput.value) {
            const today = new Date();
            monthInput.value = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
        }
    } else if (viewId === 'transfer') {
        if (window.initTransferPage) {
            window.initTransferPage();
        }
    } else if (viewId === 'picking-rm') {
        // 切換到原料領用頁面時自動載入
        setTimeout(function() {
            if (typeof window.loadRmStockData === 'function') {
                window.loadRmStockData();
            }
        }, 100);
    }
};

console.log('💰 倉租管理模組已載入');


// ========== WMS V56.0 升級補丁 - 智能入庫+多筆模式 ==========
(function() {
    'use strict';
    
    console.log('🚀 WMS V56.0 升級補丁載入中...');

    // ========== 全域變數 ==========
    window.batchInboundList = []; // 多筆入庫清單
    
    // ========== 1. 智能入庫核心邏輯 ==========
    
    window.toggleAdvancedOptions = function() {
        var options = document.getElementById('advanced-options');
        var icon = document.getElementById('advanced-icon');
        if (!options) return;
        if (options.classList.contains('hidden')) {
            options.classList.remove('hidden');
            if (icon) { icon.classList.remove('fa-chevron-down'); icon.classList.add('fa-chevron-up'); }
        } else {
            options.classList.add('hidden');
            if (icon) { icon.classList.remove('fa-chevron-up'); icon.classList.add('fa-chevron-down'); }
        }
    };
    
    window.smartInbound = async function(mode) {
        var formData = getInboundFormData();
        if (!formData) return;
        
        // 先驗證基本資料
        if (!formData.productName) { alert('❌ 請選擇品項'); return; }
        if (!formData.quantity || formData.quantity <= 0) { alert('❌ 請填寫數量'); return; }
        if (!formData.expDate) { alert('❌ 請填寫效期'); return; }
        if (formData.productType === 'variable' && (!formData.totalWeight || formData.totalWeight <= 0)) {
            alert('❌ 不定重品請填寫總重量');
            return;
        }
        
        // 本倉入庫時檢查儲位
        if (!formData.isExternal && mode !== 'external') {
            if (!formData.locationId || formData.locationId.trim() === '') {
                alert('❌ 請選擇儲位');
                // 聚焦到儲位輸入框
                var locInput = document.getElementById('in-loc');
                if (locInput) {
                    locInput.focus();
                    locInput.classList.add('animate-pulse');
                    setTimeout(function() { locInput.classList.remove('animate-pulse'); }, 2000);
                }
                // 自動觸發智能建議
                if (typeof calculateSmartSuggest === 'function') {
                    calculateSmartSuggest();
                }
                return;
            }
        }
        
        if (formData.isExternal || mode === 'external') {
            await executeExternalInbound(formData, formData.warehouseId);
        } else if (mode === 'print') {
            await executeMainInboundWithPrint(formData);
        } else if (mode === 'direct') {
            await executeMainInboundDirect(formData);
        }
    };
    
    function getInboundFormData() {
        var name = document.getElementById('in-name').value;
        var spec = document.getElementById('in-spec').value || '';
        var batchNo = document.getElementById('in-batch').value || '';
        var vendor = document.getElementById('in-vendor').value || '';
        var exp = document.getElementById('in-exp').value || '';
        var category = document.getElementById('in-category') ? document.getElementById('in-category').value : 'Raw';
        
        var warehouseSelect = document.getElementById('in-warehouse');
        var warehouseId = warehouseSelect ? warehouseSelect.value : 'MAIN';
        var mainWarehouses = ['MAIN', 'MAIN-CONSIGN', 'MAIN-RESERVE', 'MANAGE', ''];
        var isExternal = warehouseId && mainWarehouses.indexOf(warehouseId) === -1;
        
        var locationId = '';
        if (isExternal) {
            locationId = warehouseId;
        } else {
            var locEl = document.getElementById('in-loc');
            locationId = locEl ? locEl.value : '';
        }
        
        var company = '崇文';
        var companyRadio = document.querySelector('input[name="in-company"]:checked');
        if (companyRadio) company = companyRadio.value;
        
        var productType = 'fixed';
        var typeRadio = document.querySelector('input[name="in-product-type"]:checked');
        if (typeRadio) productType = typeRadio.value;
        
        var quantity = 0, totalWeight = 0, unitWeight = 0;
        
        if (productType === 'variable') {
            quantity = parseInt(document.getElementById('in-qty-var')?.value) || 0;
            totalWeight = parseFloat(document.getElementById('in-weight')?.value) || 0;
        } else {
            quantity = parseInt(document.getElementById('in-qty')?.value) || 0;
            unitWeight = parseFloat(document.getElementById('in-unit-weight')?.value) || 0;
            if (unitWeight > 0 && quantity > 0) totalWeight = quantity * unitWeight;
        }
        
        return { company, productName: name, spec, batchNo, vendor, expDate: exp || '', locationId, warehouseId, isExternal, category, productType, quantity, totalWeight, unitWeight };
    }
    
    function validateInboundData(data, isExternal) {
        if (!data.productName) return { valid: false, error: '請填寫品名' };
        if (!data.quantity || data.quantity <= 0) return { valid: false, error: '請填寫數量' };
        if (!data.expDate) return { valid: false, error: '請填寫效期' };
        if (!isExternal && !data.locationId) return { valid: false, error: '請選擇儲位' };
        if (data.productType === 'variable' && (!data.totalWeight || data.totalWeight <= 0)) return { valid: false, error: '不定重品請填寫總重量' };
        return { valid: true };
    }
    
    async function executeExternalInbound(data, warehouseId) {
        var whName = getWarehouseName(warehouseId);
        if (!confirm('確定入庫到外倉？\n\n倉庫：' + whName + '\n品名：' + data.productName + '\n數量：' + data.quantity)) return;
        
        try {
            var existing = (window.externalStock || []).find(s => s.warehouseId === warehouseId && s.productName === data.productName && s.batchNo === data.batchNo && s.company === data.company);
            
            if (existing) {
                await window.updateDoc(window.doc(window.db, 'externalStock', existing.id), { quantity: existing.quantity + data.quantity, totalWeight: (existing.totalWeight || 0) + data.totalWeight, updatedAt: new Date().toISOString() });
            } else {
                await window.addDoc(window.collection(window.db, 'externalStock'), { company: data.company, warehouseId, productName: data.productName, spec: data.spec, batchNo: data.batchNo, expDate: data.expDate, quantity: data.quantity, totalWeight: data.totalWeight, vendor: data.vendor, productType: data.productType, createdAt: new Date().toISOString() });
            }
            
            if (typeof window.logInventoryChange === 'function') {
                await window.logInventoryChange({ type: 'inbound', company: data.company, productName: data.productName, spec: data.spec, quantity: data.quantity, totalWeight: data.totalWeight, quantityChange: data.quantity, locationId: warehouseId, batchNo: data.batchNo, note: '外倉入庫 - ' + whName });
            }
            
            alert('✅ 外倉入庫成功！\n\n倉庫：' + whName + '\n品名：' + data.productName + '\n數量：' + data.quantity);
            if (typeof clearInboundForm === 'function') clearInboundForm();
            if (typeof loadExternalStock === 'function') loadExternalStock();
        } catch (e) { alert('❌ 入庫失敗：' + e.message); }
    }
    
    async function executeMainInboundDirect(data) {
        if (!confirm('確定入庫到 ' + data.locationId + '？\n\n品名：' + data.productName + '\n數量：' + data.quantity)) return;
        
        try {
            var now = new Date();
            var docNo = await window.nextDocNo('IN');
            
            await window.addDoc(window.collection(window.db, 'pallets'), { palletId: docNo, company: data.company, productName: data.productName, spec: data.spec, batchNo: data.batchNo, expDate: data.expDate, expiryDate: data.expDate, quantity: data.quantity, totalWeight: data.totalWeight, unitWeight: data.unitWeight, locationId: data.locationId, vendor: data.vendor, category: data.category, productType: data.productType, source: 'SmartInbound', createdAt: now.toISOString() });
            
            if (typeof window.logInventoryChange === 'function') {
                await window.logInventoryChange({ type: 'inbound', company: data.company, productName: data.productName, spec: data.spec, quantity: data.quantity, totalWeight: data.totalWeight, quantityChange: data.quantity, locationId: data.locationId, batchNo: data.batchNo, palletId: docNo, expDate: data.expDate, note: '入庫' });
            }
            
            alert('✅ 入庫成功！\n\n儲位：' + data.locationId + '\n品名：' + data.productName + '\n數量：' + data.quantity);
            if (typeof clearInboundForm === 'function') clearInboundForm();
        } catch (e) { alert('❌ 入庫失敗：' + e.message); }
    }
    
    async function executeMainInboundWithPrint(data) {
        if (!confirm('確定入庫並列印棧板插單？\n\n儲位：' + data.locationId + '\n品名：' + data.productName + '\n數量：' + data.quantity)) return;
        
        try {
            var now = new Date();
            var docNo = await window.nextDocNo('IN');
            
            await window.addDoc(window.collection(window.db, 'pallets'), { palletId: docNo, company: data.company, productName: data.productName, spec: data.spec, batchNo: data.batchNo, expDate: data.expDate, expiryDate: data.expDate, quantity: data.quantity, totalWeight: data.totalWeight, unitWeight: data.unitWeight, locationId: data.locationId, vendor: data.vendor, category: data.category, productType: data.productType, source: 'SmartInbound', createdAt: now.toISOString() });
            
            if (typeof window.logInventoryChange === 'function') {
                await window.logInventoryChange({ type: 'inbound', company: data.company, productName: data.productName, spec: data.spec, quantity: data.quantity, totalWeight: data.totalWeight, quantityChange: data.quantity, locationId: data.locationId, batchNo: data.batchNo, palletId: docNo, expDate: data.expDate, note: '入庫' });
            }
            
            if (typeof window.printInboundSlip === 'function') {
                window.printInboundSlip({ docNo, productName: data.productName, spec: data.spec, batchNo: data.batchNo, expDate: data.expDate, quantity: data.quantity, locationId: data.locationId, vendor: data.vendor });
            }
            
            alert('✅ 入庫成功！已開啟列印視窗\n\n儲位：' + data.locationId + '\n品名：' + data.productName);
            if (typeof clearInboundForm === 'function') clearInboundForm();
        } catch (e) { alert('❌ 入庫失敗：' + e.message); }
    }
    
    // ========== 2. 倉庫切換 ==========
    
    var originalOnWarehouseChange = window.onWarehouseChange;
    window.onWarehouseChange = function() {
        if (typeof originalOnWarehouseChange === 'function') originalOnWarehouseChange();
        
        var warehouseSelect = document.getElementById('in-warehouse');
        var warehouseId = warehouseSelect ? warehouseSelect.value : 'MAIN';
        var mainWarehouses = ['MAIN', 'MAIN-CONSIGN', 'MAIN-RESERVE', 'MANAGE', ''];
        var isExternal = warehouseId && mainWarehouses.indexOf(warehouseId) === -1;
        
        var mainButtons = document.getElementById('main-wh-buttons');
        var externalButtons = document.getElementById('external-wh-buttons');
        var locationSection = document.getElementById('location-section');
        var externalSection = document.getElementById('external-wh-section');
        var checkLoc = document.getElementById('check-loc');
        
        if (isExternal) {
            if (mainButtons) mainButtons.classList.add('hidden');
            if (externalButtons) externalButtons.classList.remove('hidden');
            if (locationSection) locationSection.classList.add('hidden');
            if (externalSection) externalSection.classList.remove('hidden');
            if (checkLoc) checkLoc.style.display = 'none';
            
            var whName = getWarehouseName(warehouseId);
            var titleEl = document.getElementById('inbound-wh-title');
            if (titleEl) titleEl.innerHTML = '<i class="fa-solid fa-building mr-1"></i>外倉入庫：' + whName;
        } else {
            if (mainButtons) mainButtons.classList.remove('hidden');
            if (externalButtons) externalButtons.classList.add('hidden');
            if (locationSection) locationSection.classList.remove('hidden');
            if (externalSection) externalSection.classList.add('hidden');
            if (checkLoc) checkLoc.style.display = '';
        }
        
        updateInboundButtonState();
    };
    
    function updateInboundButtonState() {
        var warehouseSelect = document.getElementById('in-warehouse');
        var warehouseId = warehouseSelect ? warehouseSelect.value : 'MAIN';
        var mainWarehouses = ['MAIN', 'MAIN-CONSIGN', 'MAIN-RESERVE', 'MANAGE', ''];
        var isExternal = warehouseId && mainWarehouses.indexOf(warehouseId) === -1;
        
        // 取得各欄位值
        var companyRadio = document.querySelector('input[name="in-company"]:checked');
        var company = companyRadio ? companyRadio.value : '';
        var name = document.getElementById('in-name')?.value;
        var exp = document.getElementById('in-exp')?.value;
        var loc = document.getElementById('in-loc')?.value;
        
        var productType = document.querySelector('input[name="in-product-type"]:checked')?.value || 'fixed';
        var qty = productType === 'variable' ? (parseInt(document.getElementById('in-qty-var')?.value) || 0) : (parseInt(document.getElementById('in-qty')?.value) || 0);
        
        // 只檢查基本資料（品名、效期、數量），儲位改為提交時檢查
        var hasBasicData = name && exp && qty > 0;
        
        var btnPrint = document.getElementById('btn-inbound-print');
        var btnDirect = document.getElementById('btn-inbound-direct');
        if (btnPrint) btnPrint.disabled = !hasBasicData;
        if (btnDirect) btnDirect.disabled = !hasBasicData;
        
        var btnExternal = document.getElementById('btn-inbound-external');
        if (btnExternal) btnExternal.disabled = !hasBasicData;
        
        // ========== 更新待確認清單（公司、品名、數量、效期、儲位）==========
        // 有值時顯示橘色，無值時顯示灰色
        
        // 公司
        var checkCompany = document.getElementById('check-company');
        if (checkCompany) {
            var hasCompany = company && company.trim() !== '';
            var icon = checkCompany.querySelector('i');
            var text = checkCompany.querySelector('span');
            if (hasCompany) {
                if (icon) icon.className = 'fa-solid fa-check-circle text-orange-400 text-[8px]';
                if (text) { text.className = 'text-orange-400 font-bold'; text.textContent = company; }
            } else {
                if (icon) icon.className = 'fa-solid fa-circle text-slate-600 text-[8px]';
                if (text) { text.className = 'text-slate-500'; text.textContent = '公司'; }
            }
        }
        
        // 品名
        var checkName = document.getElementById('check-name');
        if (checkName) {
            var hasName = name && name.trim() !== '';
            var icon = checkName.querySelector('i');
            var text = checkName.querySelector('span');
            if (hasName) {
                if (icon) icon.className = 'fa-solid fa-check-circle text-orange-400 text-[8px]';
                var displayName = name.length > 8 ? name.substring(0, 8) + '...' : name;
                if (text) { text.className = 'text-orange-400 font-bold'; text.textContent = displayName; }
            } else {
                if (icon) icon.className = 'fa-solid fa-circle text-slate-600 text-[8px]';
                if (text) { text.className = 'text-slate-500'; text.textContent = '品名'; }
            }
        }
        
        // 數量
        var checkQty = document.getElementById('check-qty');
        if (checkQty) {
            var hasQty = qty > 0;
            var icon = checkQty.querySelector('i');
            var text = checkQty.querySelector('span');
            if (hasQty) {
                if (icon) icon.className = 'fa-solid fa-check-circle text-orange-400 text-[8px]';
                if (text) { text.className = 'text-orange-400 font-bold'; text.textContent = qty + ' 件'; }
            } else {
                if (icon) icon.className = 'fa-solid fa-circle text-slate-600 text-[8px]';
                if (text) { text.className = 'text-slate-500'; text.textContent = '數量'; }
            }
        }
        
        // 效期
        var checkExp = document.getElementById('check-exp');
        if (checkExp) {
            var hasExp = exp && exp.trim() !== '';
            var icon = checkExp.querySelector('i');
            var text = checkExp.querySelector('span');
            if (hasExp) {
                if (icon) icon.className = 'fa-solid fa-check-circle text-orange-400 text-[8px]';
                // 格式化效期顯示
                var expDisplay = exp.replace(/-/g, '/').replace(/\//g, '/');
                if (text) { text.className = 'text-orange-400 font-bold'; text.textContent = expDisplay; }
            } else {
                if (icon) icon.className = 'fa-solid fa-circle text-slate-600 text-[8px]';
                if (text) { text.className = 'text-slate-500'; text.textContent = '效期'; }
            }
        }
        
        // 儲位
        var checkLoc = document.getElementById('check-loc');
        if (checkLoc && !isExternal) {
            var hasLocation = loc && loc.trim() !== '';
            var icon = checkLoc.querySelector('i');
            var text = checkLoc.querySelector('span');
            if (hasLocation) {
                if (icon) icon.className = 'fa-solid fa-check-circle text-orange-400 text-[8px]';
                if (text) { text.className = 'text-orange-400 font-bold'; text.textContent = loc; }
            } else {
                if (icon) icon.className = 'fa-solid fa-circle text-slate-600 text-[8px]';
                if (text) { text.className = 'text-slate-500'; text.textContent = '儲位'; }
            }
        } else if (checkLoc && isExternal) {
            checkLoc.style.display = 'none';
        }
    }
    
    var originalUpdateInboundProgress = window.updateInboundProgress;
    window.updateInboundProgress = function() {
        if (typeof originalUpdateInboundProgress === 'function') originalUpdateInboundProgress();
        updateInboundButtonState();
    };
    
    // ========== 3. 品項主檔整合 ==========
    
    // 更多選項切換
    window.toggleInboundMoreOptions = function() {
        var panel = document.getElementById('more-options-panel');
        var icon = document.getElementById('more-options-icon');
        var text = document.getElementById('more-options-text');
        if (!panel) return;
        
        if (panel.classList.contains('hidden')) {
            panel.classList.remove('hidden');
            if (icon) { icon.classList.remove('fa-chevron-down'); icon.classList.add('fa-chevron-up'); }
            if (text) text.textContent = '收合選項';
        } else {
            panel.classList.add('hidden');
            if (icon) { icon.classList.remove('fa-chevron-up'); icon.classList.add('fa-chevron-down'); }
            if (text) text.textContent = '更多選項';
        }
    };
    
    // 更新規格顯示文字
    window.updateSpecDisplayText = function() {
        var specEl = document.getElementById('in-spec');
        var displayRow = document.getElementById('spec-display-row');
        var displayText = document.getElementById('spec-display-text');
        
        if (specEl && displayText) {
            var spec = specEl.value;
            displayText.textContent = spec || '-';
            if (displayRow) {
                if (spec) displayRow.classList.remove('hidden');
                else displayRow.classList.add('hidden');
            }
        }
    };
    
    // 設定品項類型（定重/不定重）並更新 UI
    function setProductType(type) {
        var fixedFields = document.getElementById('fixed-weight-fields');
        var variableFields = document.getElementById('variable-weight-fields');
        var typeBadge = document.getElementById('product-type-badge');
        var badgeLabel = document.getElementById('type-badge-label');
        var unitWeightOption = document.getElementById('unit-weight-option');
        
        // 設定 radio
        var fixedRadio = document.querySelector('input[name="in-product-type"][value="fixed"]');
        var variableRadio = document.querySelector('input[name="in-product-type"][value="variable"]');
        
        if (type === 'variable') {
            // 不定重品
            if (fixedRadio) fixedRadio.checked = false;
            if (variableRadio) variableRadio.checked = true;
            if (fixedFields) fixedFields.classList.add('hidden');
            if (variableFields) variableFields.classList.remove('hidden');
            if (badgeLabel) {
                badgeLabel.textContent = '⚖️ 不定重品';
                badgeLabel.className = 'px-2 py-1 rounded text-xs font-bold bg-amber-600/20 text-amber-400 border border-amber-500/30';
            }
            if (unitWeightOption) unitWeightOption.classList.add('hidden');
        } else {
            // 定重品（預設）
            if (fixedRadio) fixedRadio.checked = true;
            if (variableRadio) variableRadio.checked = false;
            if (fixedFields) fixedFields.classList.remove('hidden');
            if (variableFields) variableFields.classList.add('hidden');
            if (badgeLabel) {
                badgeLabel.textContent = '📦 定重品';
                badgeLabel.className = 'px-2 py-1 rounded text-xs font-bold bg-blue-600/20 text-blue-400 border border-blue-500/30';
            }
            if (unitWeightOption) unitWeightOption.classList.remove('hidden');
        }
        
        // 顯示類型標籤
        if (typeBadge) typeBadge.classList.remove('hidden');
        
        // 呼叫原本的 toggleProductType（如果存在）
        if (typeof window.originalToggleProductType === 'function') {
            window.originalToggleProductType(type);
        }
    }
    
    // 保存原本的 toggleProductType
    window.originalToggleProductType = window.toggleProductType;
    window.toggleProductType = setProductType;
    
    var originalFillProductFromMaster = window.fillProductFromMaster;
    window.fillProductFromMaster = function(product) {
        var nameEl = document.getElementById('in-name');
        var specEl = document.getElementById('in-spec');
        var codeEl = document.getElementById('in-product-code');
        
        if (nameEl) nameEl.value = product.name || product.productName || '';
        if (specEl) specEl.value = product.spec || '';
        if (codeEl) codeEl.value = product.code || product.id || '';
        
        // 更新規格顯示
        updateSpecDisplayText();
        
        // 自動判斷定重/不定重
        var isVariable = product.productType === 'variable' || product.isVariable === true || product.weightType === 'variable';
        setProductType(isVariable ? 'variable' : 'fixed');
        
        // 自動填入箱容
        if (product.unitWeight) {
            var unitWeightEl = document.getElementById('in-unit-weight');
            if (unitWeightEl) unitWeightEl.value = product.unitWeight;
        }
        
        // 自動設定入庫類型
        if (product.category) {
            var categoryMap = { 'RAW': 'Raw', 'FG': 'FG', 'WIP': 'WIP', 'raw': 'Raw', 'fg': 'FG', 'wip': 'WIP' };
            var category = categoryMap[product.category] || product.category;
            var categoryEl = document.getElementById('in-category');
            if (categoryEl) categoryEl.value = category;
            
            // 更新入庫類型按鈕樣式
            if (typeof selectInboundType === 'function') {
                selectInboundType(category);
            }
        }
        
        if (typeof updateLivePreview === 'function') updateLivePreview();
        if (typeof updateInboundProgress === 'function') updateInboundProgress();
        
        // 重要：觸發智能儲位建議
        if (typeof autoTriggerSmartSuggest === 'function') {
            autoTriggerSmartSuggest();
        }
        
        // 自動跳到批號欄位
        setTimeout(function() { var batchEl = document.getElementById('in-batch'); if (batchEl) batchEl.focus(); }, 100);
    };
    
    // ========== 4. 公司別篩選外倉 ==========
    
    function updateWarehouseOptions() {
        var companyRadio = document.querySelector('input[name="in-company"]:checked');
        var company = companyRadio ? companyRadio.value : '崇文';
        
        var optgroupCW = document.getElementById('optgroup-cw');
        var optgroupBF = document.getElementById('optgroup-bf');
        if (!optgroupCW || !optgroupBF) return;
        
        if (company === '崇文') {
            optgroupCW.style.display = '';
            optgroupBF.style.display = 'none';
        } else {
            optgroupCW.style.display = 'none';
            optgroupBF.style.display = '';
        }
        
        var warehouseSelect = document.getElementById('in-warehouse');
        if (warehouseSelect) {
            var selectedOption = warehouseSelect.selectedOptions[0];
            var parent = selectedOption ? selectedOption.parentElement : null;
            if ((company === '崇文' && parent === optgroupBF) || (company === '八方' && parent === optgroupCW)) {
                warehouseSelect.value = 'MAIN';
                if (typeof onWarehouseChange === 'function') onWarehouseChange();
            }
        }
    }
    
    document.addEventListener('change', function(e) { if (e.target.name === 'in-company') updateWarehouseOptions(); });
    
    // ========== 5. 效期輸入優化 ==========
    
    function initExpiryDateInput() {
        var expInput = document.getElementById('in-exp');
        if (!expInput || expInput.dataset.enhanced === 'true') return;
        
        var newInput = document.createElement('input');
        newInput.type = 'text';
        newInput.id = 'in-exp';
        newInput.className = expInput.className;
        newInput.placeholder = 'YYYY/MM/DD';
        newInput.maxLength = 10;
        newInput.dataset.enhanced = 'true';
        
        newInput.addEventListener('input', function(e) {
            var value = e.target.value.replace(/\D/g, '');
            var formatted = '';
            if (value.length >= 4) {
                formatted = value.substring(0, 4);
                if (value.length > 4) { formatted += '/' + value.substring(4, 6); if (value.length > 6) formatted += '/' + value.substring(6, 8); }
            } else { formatted = value; }
            e.target.value = formatted;
            if (typeof updateLivePreview === 'function') updateLivePreview();
            if (typeof updateInboundProgress === 'function') updateInboundProgress();
        });
        
        if (expInput.parentNode) expInput.parentNode.replaceChild(newInput, expInput);
    }
    
    // ========== 6. 庫存編輯 ==========
    
    window.editPallet = async function(id) {
        console.log('📝 editPallet 被呼叫，ID:', id);
        
        // 先嘗試從本地快取找
        var inventory = [];
        try {
            if (typeof window.currentInventory === 'function') {
                inventory = window.currentInventory() || [];
            }
        } catch (e) {
            console.error('讀取本地庫存失敗:', e);
        }
        
        console.log('📦 本地庫存數量:', inventory.length);
        
        var item = null;
        for (var i = 0; i < inventory.length; i++) {
            if (inventory[i].id === id) {
                item = inventory[i];
                console.log('✅ 在本地找到資料:', item);
                break;
            }
        }
        
        // 如果本地找不到，從 Firebase 讀取
        if (!item) {
            console.log('⚠️ 本地找不到，嘗試從 Firebase 讀取...');
            try {
                if (window.db && window.doc && window.getDoc) {
                    var docRef = window.doc(window.db, 'pallets', id);
                    var docSnap = await window.getDoc(docRef);
                    if (docSnap.exists) {
                        item = { id: docSnap.id, ...docSnap.data() };
                        console.log('✅ 從 Firebase 讀取成功:', item);
                    } else {
                        console.log('❌ Firebase 中也找不到此文件');
                    }
                }
            } catch (e) {
                console.error('❌ Firebase 讀取失敗:', e);
            }
        }
        
        if (!item) { 
            alert('找不到此筆資料 (ID: ' + id + ')'); 
            return; 
        }
        
        // 移除舊彈窗
        var oldModal = document.getElementById('edit-pallet-modal');
        if (oldModal) oldModal.remove();
        
        // 建立彈窗容器
        var modal = document.createElement('div');
        modal.id = 'edit-pallet-modal';
        modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;z-index:9999;';
        
        // 建立內容區
        var content = document.createElement('div');
        content.style.cssText = 'background:#1e293b;border-radius:12px;padding:24px;width:500px;max-height:90vh;overflow:auto;border:1px solid #475569;';
        
        // 標題
        var title = document.createElement('h3');
        title.style.cssText = 'color:white;font-size:20px;font-weight:bold;margin-bottom:16px;';
        title.innerHTML = '<i class="fa-solid fa-edit" style="color:#60a5fa;margin-right:8px;"></i>編輯庫存';
        content.appendChild(title);
        
        // 表單區域
        var form = document.createElement('div');
        form.style.cssText = 'display:flex;flex-direction:column;gap:12px;';
        
        // 公司選擇
        var companyRow = document.createElement('div');
        companyRow.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:12px;';
        companyRow.innerHTML = '<div><label style="color:#94a3b8;font-size:12px;">公司</label><select id="edit-company-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;"><option value="崇文">崇文</option><option value="八方">八方</option></select></div><div><label style="color:#94a3b8;font-size:12px;">儲位</label><input type="text" id="edit-location-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;"></div>';
        form.appendChild(companyRow);
        
        // 品名
        var nameRow = document.createElement('div');
        nameRow.innerHTML = '<label style="color:#94a3b8;font-size:12px;">品名</label><input type="text" id="edit-name-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;">';
        form.appendChild(nameRow);
        
        // 規格
        var specRow = document.createElement('div');
        specRow.innerHTML = '<label style="color:#94a3b8;font-size:12px;">規格</label><input type="text" id="edit-spec-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;">';
        form.appendChild(specRow);
        
        // 批號和數量
        var batchQtyRow = document.createElement('div');
        batchQtyRow.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:12px;';
        batchQtyRow.innerHTML = '<div><label style="color:#94a3b8;font-size:12px;">批號</label><input type="text" id="edit-batch-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;"></div><div><label style="color:#94a3b8;font-size:12px;">數量</label><input type="number" id="edit-qty-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;"></div>';
        form.appendChild(batchQtyRow);
        
        // 重量和效期
        var weightExpRow = document.createElement('div');
        weightExpRow.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:12px;';
        weightExpRow.innerHTML = '<div><label style="color:#94a3b8;font-size:12px;">重量 (kg)</label><input type="number" step="0.01" id="edit-weight-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;"></div><div><label style="color:#94a3b8;font-size:12px;">效期</label><input type="date" id="edit-expiry-field" style="width:100%;padding:8px;background:#334155;border:1px solid #475569;border-radius:4px;color:white;box-sizing:border-box;"></div>';
        form.appendChild(weightExpRow);
        
        content.appendChild(form);
        
        // 按鈕區
        var btnRow = document.createElement('div');
        btnRow.style.cssText = 'display:flex;gap:12px;margin-top:20px;';
        
        var cancelBtn = document.createElement('button');
        cancelBtn.textContent = '取消';
        cancelBtn.style.cssText = 'flex:1;padding:10px;background:#475569;border:none;border-radius:8px;color:white;cursor:pointer;';
        cancelBtn.onclick = function() { modal.remove(); };
        
        var saveBtn = document.createElement('button');
        saveBtn.textContent = '儲存修改';
        saveBtn.style.cssText = 'flex:1;padding:10px;background:#2563eb;border:none;border-radius:8px;color:white;font-weight:bold;cursor:pointer;';
        
        btnRow.appendChild(cancelBtn);
        btnRow.appendChild(saveBtn);
        content.appendChild(btnRow);
        
        modal.appendChild(content);
        document.body.appendChild(modal);
        
        // 設定欄位值
        document.getElementById('edit-company-field').value = item.company || '崇文';
        document.getElementById('edit-location-field').value = item.locationId || '';
        document.getElementById('edit-name-field').value = item.productName || '';
        document.getElementById('edit-spec-field').value = item.spec || '';
        document.getElementById('edit-batch-field').value = item.batchNo || '';
        document.getElementById('edit-qty-field').value = item.quantity || 0;
        document.getElementById('edit-weight-field').value = item.totalWeight || 0;
        
        // 效期處理
        if (item.expiryDate) {
            try {
                var ed = item.expiryDate.toDate ? item.expiryDate.toDate() : new Date(item.expiryDate);
                if (!isNaN(ed.getTime())) {
                    var y = ed.getFullYear();
                    var m = String(ed.getMonth() + 1).padStart(2, '0');
                    var d = String(ed.getDate()).padStart(2, '0');
                    document.getElementById('edit-expiry-field').value = y + '-' + m + '-' + d;
                }
            } catch (e) {
                console.warn('效期轉換失敗:', e);
            }
        }
        
        console.log('✅ 表單欄位已設定:', {
            company: item.company,
            location: item.locationId,
            name: item.productName,
            spec: item.spec,
            batch: item.batchNo,
            qty: item.quantity,
            weight: item.totalWeight
        });
        
        // 儲存按鈕事件
        saveBtn.onclick = async function() {
            var updateData = {
                company: document.getElementById('edit-company-field').value,
                locationId: document.getElementById('edit-location-field').value.trim(),
                productName: document.getElementById('edit-name-field').value.trim(),
                spec: document.getElementById('edit-spec-field').value.trim(),
                batchNo: document.getElementById('edit-batch-field').value.trim(),
                quantity: parseInt(document.getElementById('edit-qty-field').value) || 0,
                totalWeight: parseFloat(document.getElementById('edit-weight-field').value) || 0,
                updatedAt: new Date().toISOString()
            };
            
            if (!updateData.productName) { alert('品名不能為空'); return; }
            if (!updateData.locationId) { alert('儲位不能為空'); return; }
            
            var expiryStr = document.getElementById('edit-expiry-field').value;
            if (expiryStr) updateData.expiryDate = new Date(expiryStr);
            
            try {
                await window.updateDoc(window.doc(window.db, 'pallets', id), updateData);
                modal.remove();
                if (window.showNotification) {
                    showNotification('✅ 更新成功', 'success');
                } else {
                    alert('✅ 更新成功');
                }
            } catch (e) {
                alert('❌ 更新失敗：' + e.message);
            }
        };
        
        // 點擊背景關閉
        modal.onclick = function(e) {
            if (e.target === modal) modal.remove();
        };
    };
    
    // ========== 7. 外倉庫存顯示 ==========
    
    function getWarehouseName(code) {
        if (!code) return '本倉';
        var wh = (window.warehousesData || []).find(w => w.code === code);
        return wh ? wh.company + '_' + wh.name : code;
    }
    
    function checkAndRenderExternal() {
        var tbody = document.getElementById('inventory-list-body');
        if (!tbody) return;
        tbody.querySelectorAll('tr[data-type="external"]').forEach(row => row.remove());
        var externalStock = window.externalStock || [];
        if (externalStock.length === 0) return;
        
        // 建立外倉寄庫對照表（數量和客戶）
        // 外倉用 品名|規格|批號|倉庫名稱 匹配（沒有 locationId 的就是外倉）
        var extConsignedMap = {};
        var extConsignCustomerMap = {};
        if (window.consignmentData && Array.isArray(window.consignmentData)) {
            window.consignmentData.forEach(function(c) {
                if (c.status !== 'active') return;
                if (c.locationId) return; // 有 locationId 是內倉，跳過
                var warehouseName = c.sourceWarehouse || '';
                var key = (c.productName || '') + '|' + (c.spec || '') + '|' + (c.batchNo || '') + '|' + warehouseName;
                extConsignedMap[key] = (extConsignedMap[key] || 0) + (c.remainingQty || 0);
                if (c.customer) {
                    if (!extConsignCustomerMap[key]) extConsignCustomerMap[key] = [];
                    if (!extConsignCustomerMap[key].includes(c.customer)) {
                        extConsignCustomerMap[key].push(c.customer);
                    }
                }
            });
        }
        
        externalStock.forEach(function(item) {
            var expClass = 'text-slate-400';
            if (item.expDate) { var days = Math.floor((new Date(item.expDate) - new Date()) / 86400000); if (days < 0) expClass = 'text-red-500 font-bold'; else if (days < 30) expClass = 'text-orange-400'; else if (days < 90) expClass = 'text-yellow-400'; }
            var companyClass = item.company === '八方' ? 'bg-purple-900/50 text-purple-300' : 'bg-blue-900/50 text-blue-300';
            
            // 取得寄庫數量和客戶
            var whName = getWarehouseName(item.warehouseId);
            var extKey = (item.productName || '') + '|' + (item.spec || '') + '|' + (item.batchNo || '') + '|' + whName;
            var consignedQty = extConsignedMap[extKey] || 0;
            var extCustomers = extConsignCustomerMap[extKey] || [];
            var customerDisplay;
            if (extCustomers.length > 0 && consignedQty > 0) {
                customerDisplay = '<span class="text-amber-400">' + extCustomers.join(', ') + ' (' + consignedQty + ')</span>';
            } else {
                customerDisplay = '<span class="text-slate-600">-</span>';
            }
            
            var row = document.createElement('tr');
            row.className = 'border-b border-slate-700 hover:bg-slate-800 bg-teal-900/20';
            row.setAttribute('data-company', item.company || '');
            row.setAttribute('data-type', 'external');
            row.innerHTML = '<td class="p-2"><span class="px-1.5 py-0.5 rounded text-xs ' + companyClass + '">' + (item.company || '崇文') + '</span></td><td class="text-white p-2">' + (item.productName || '-') + '</td><td class="text-yellow-400 p-2">' + (item.spec || '-') + '</td><td class="text-slate-400 font-mono p-2">' + (item.batchNo || '-') + '</td><td class="text-right text-white p-2">' + (item.quantity || 0) + '</td><td class="text-right p-2">' + (item.totalWeight ? '<span class="text-amber-400">' + item.totalWeight + ' kg</span>' : '-') + '</td><td class="p-2 text-teal-400 font-mono"><span class="bg-teal-800/50 px-1.5 py-0.5 rounded text-xs mr-1">外</span>' + whName + '</td><td class="p-2 ' + expClass + '">' + (item.expDate || '-') + '</td><td class="p-2 text-sm">' + customerDisplay + '</td><td class="p-2 text-right"><button onclick="editExternalStock(\'' + item.id + '\')" class="text-blue-400 hover:text-blue-300 mr-2"><i class="fa-solid fa-edit"></i></button><button onclick="deleteExternalStock(\'' + item.id + '\')" class="text-red-500 hover:bg-red-500/20 rounded px-2"><i class="fa-solid fa-trash"></i></button></td>';
            tbody.appendChild(row);
        });
    }
    
    window.editExternalStock = async function(id) {
        var item = (window.externalStock || []).find(s => s.id === id);
        if (!item) { alert('找不到此筆資料'); return; }
        var newQty = prompt('編輯數量\n\n倉庫：' + getWarehouseName(item.warehouseId) + '\n品名：' + item.productName + '\n目前數量：' + item.quantity, item.quantity);
        if (newQty === null) return;
        var qty = parseInt(newQty);
        if (isNaN(qty) || qty < 0) { alert('請輸入有效的數量'); return; }
        if (qty === 0 && !confirm('數量為 0，是否刪除此筆資料？')) return;
        try {
            // 以交易讀最新數量，寫入差額並留下調整記錄
            var ref = window.doc(window.db, 'externalStock', id);
            await window.db.runTransaction(async function(tx) {
                var snap = await tx.get(ref);
                if (!snap.exists) throw new Error('資料已不存在（可能已被其他人處理）');
                var cur = snap.data();
                var before = parseFloat(cur.quantity) || 0;
                if (qty === 0) tx.delete(ref);
                else tx.update(ref, { quantity: qty, updatedAt: new Date().toISOString() });
                tx.set(window.db.collection('inventoryLogs').doc(), window.buildInventoryLogEntry({
                    type: 'adjust',
                    company: cur.company || '',
                    productName: cur.productName,
                    spec: cur.spec || '',
                    batchNo: cur.batchNo || '',
                    quantity: qty,
                    quantityChange: qty - before,
                    locationId: cur.warehouseId || '',
                    note: '外倉庫存手動調整：' + before + ' → ' + qty
                }));
            });
            alert('✅ 更新成功');
            await window.loadExternalStock();
        } catch (e) { alert('❌ 更新失敗：' + e.message); }
    };
    
    window.deleteExternalStock = async function(id) {
        var item = (window.externalStock || []).find(s => s.id === id);
        if (!item) { alert('找不到此筆資料'); return; }
        if (!confirm('確定刪除？\n\n倉庫：' + getWarehouseName(item.warehouseId) + '\n品名：' + item.productName + '\n數量：' + item.quantity)) return;
        try { await window.deleteDoc(window.doc(window.db, 'externalStock', id)); alert('✅ 已刪除'); await window.loadExternalStock(); } catch (e) { alert('❌ 刪除失敗：' + e.message); }
    };
    
    var originalLoadExternalStock = window.loadExternalStock;
    if (typeof originalLoadExternalStock === 'function') { window.loadExternalStock = async function() { await originalLoadExternalStock(); checkAndRenderExternal(); }; }
    setInterval(function() { var tbody = document.getElementById('inventory-list-body'); if (tbody && window.externalStock && window.externalStock.length > 0 && !tbody.querySelector('tr[data-type="external"]')) checkAndRenderExternal(); }, 2000);
    
    // ========== 8. 貨櫃入庫作業優化 ==========
    
    // 匯入方式切換
    window.switchContainerInputMode = function(mode) {
        var btnManual = document.getElementById('btn-mode-manual');
        var btnExcel = document.getElementById('btn-mode-excel');
        var manualPanel = document.getElementById('container-manual-panel');
        var excelPanel = document.getElementById('container-excel-panel');
        
        if (mode === 'excel') {
            if (btnManual) { btnManual.className = 'flex-1 py-1.5 rounded text-xs font-bold bg-slate-800 text-slate-400 hover:bg-slate-700 transition-all'; }
            if (btnExcel) { btnExcel.className = 'flex-1 py-1.5 rounded text-xs font-bold bg-emerald-600 text-white transition-all'; }
            if (manualPanel) manualPanel.classList.add('hidden');
            if (excelPanel) excelPanel.classList.remove('hidden');
        } else {
            if (btnManual) { btnManual.className = 'flex-1 py-1.5 rounded text-xs font-bold bg-cyan-600 text-white transition-all'; }
            if (btnExcel) { btnExcel.className = 'flex-1 py-1.5 rounded text-xs font-bold bg-slate-800 text-slate-400 hover:bg-slate-700 transition-all'; }
            if (manualPanel) manualPanel.classList.remove('hidden');
            if (excelPanel) excelPanel.classList.add('hidden');
        }
    };
    
    // 貨櫃入庫更多選項切換
    window.toggleContainerMoreOptions = function() {
        var panel = document.getElementById('container-more-panel');
        var icon = document.getElementById('container-more-icon');
        var text = document.getElementById('container-more-text');
        if (!panel) return;
        
        if (panel.classList.contains('hidden')) {
            panel.classList.remove('hidden');
            if (icon) { icon.classList.remove('fa-chevron-down'); icon.classList.add('fa-chevron-up'); }
            if (text) text.textContent = '收合選項';
        } else {
            panel.classList.add('hidden');
            if (icon) { icon.classList.remove('fa-chevron-up'); icon.classList.add('fa-chevron-down'); }
            if (text) text.textContent = '更多選項';
        }
    };
    
    // 設定貨櫃入庫品項類型
    function setPreProductType(type) {
        var fixedFields = document.getElementById('pre-fixed-fields');
        var variableFields = document.getElementById('pre-variable-fields');
        var typeBadge = document.getElementById('pre-product-type-badge');
        var badgeLabel = document.getElementById('pre-type-badge-label');
        var unitWeightRow = document.getElementById('pre-unit-weight-row');
        var perPalletVarRow = document.getElementById('pre-per-pallet-var-row');
        
        var fixedRadio = document.querySelector('input[name="pre-product-type"][value="fixed"]');
        var variableRadio = document.querySelector('input[name="pre-product-type"][value="variable"]');
        
        if (type === 'variable') {
            if (fixedRadio) fixedRadio.checked = false;
            if (variableRadio) variableRadio.checked = true;
            if (fixedFields) fixedFields.classList.add('hidden');
            if (variableFields) variableFields.classList.remove('hidden');
            if (badgeLabel) {
                badgeLabel.textContent = '⚖️ 不定重品';
                badgeLabel.className = 'px-2 py-1 rounded text-xs font-bold bg-amber-600/20 text-amber-400 border border-amber-500/30';
            }
            if (unitWeightRow) unitWeightRow.classList.add('hidden');
            if (perPalletVarRow) perPalletVarRow.classList.remove('hidden');
        } else {
            if (fixedRadio) fixedRadio.checked = true;
            if (variableRadio) variableRadio.checked = false;
            if (fixedFields) fixedFields.classList.remove('hidden');
            if (variableFields) variableFields.classList.add('hidden');
            if (badgeLabel) {
                badgeLabel.textContent = '📦 定重品';
                badgeLabel.className = 'px-2 py-1 rounded text-xs font-bold bg-blue-600/20 text-blue-400 border border-blue-500/30';
            }
            if (unitWeightRow) unitWeightRow.classList.remove('hidden');
            if (perPalletVarRow) perPalletVarRow.classList.add('hidden');
        }
        
        if (typeBadge) typeBadge.classList.remove('hidden');
    }
    
    // 覆寫原本的 togglePreProductType
    window.togglePreProductType = setPreProductType;
    
    // 覆寫品項選擇後填入函數（貨櫃入庫用）
    var originalFillContainerProduct = window.fillContainerProductFromMaster;
    window.fillContainerProductFromMaster = function(product) {
        console.log('📦 fillContainerProductFromMaster 被呼叫, product:', product);
        
        var nameEl = document.getElementById('pre-name');
        var specEl = document.getElementById('pre-spec');
        var codeEl = document.getElementById('pre-product-code');
        
        if (nameEl) nameEl.value = product.name || product.productName || '';
        if (specEl) specEl.value = product.spec || '';
        if (codeEl) codeEl.value = product.code || product.id || '';
        
        // 自動判斷定重/不定重
        var isVariable = product.weightType === 'variable' || product.productType === 'variable' || product.isVariable === true;
        setPreProductType(isVariable ? 'variable' : 'fixed');
        
        // 自動填入箱容
        if (product.unitWeight) {
            var unitWeightEl = document.getElementById('pre-unit-weight');
            if (unitWeightEl) unitWeightEl.value = product.unitWeight;
        }
        
        // 🔧 修正：自動填入每板數（從品項主檔的板容量），確保一定會設定值
        var perPalletEl = document.getElementById('pre-per-pallet');
        var perPalletVarEl = document.getElementById('pre-per-pallet-var');
        var palletCapacityValue = parseInt(product.palletCapacity) || 40;
        
        console.log('📦 設定每板件數: ' + palletCapacityValue + ' (原始值: ' + product.palletCapacity + ')');
        
        if (perPalletEl) {
            perPalletEl.value = palletCapacityValue;
            console.log('📦 pre-per-pallet 設定為: ' + perPalletEl.value);
        }
        if (perPalletVarEl) {
            perPalletVarEl.value = palletCapacityValue;
            console.log('📦 pre-per-pallet-var 設定為: ' + perPalletVarEl.value);
        }
        
        // 更新 checklist 和智能建議
        if (typeof updateContainerChecklist === 'function') {
            updateContainerChecklist();
        }
        if (typeof calculateContainerSmartSuggest === 'function') {
            calculateContainerSmartSuggest();
        }
        
        // 自動跳到批號欄位
        setTimeout(function() { var batchEl = document.getElementById('pre-batch'); if (batchEl) batchEl.focus(); }, 100);
    };
    
    // 擴展 openProductSelectModal 以支援貨櫃入庫
    var originalOpenProductSelectModal = window.openProductSelectModal;
    window.openProductSelectModal = function(source) {
        window.productSelectSource = source;
        if (typeof originalOpenProductSelectModal === 'function') {
            originalOpenProductSelectModal(source);
        }
    };
    
    // 擴展品項選擇確認函數 - 修正參數格式匹配
    var originalSelectProductFromModal = window.selectProductFromModal;
    window.selectProductFromModal = function(code, name, spec, palletCapacity, shelfLife) {
        console.log('📦 selectProductFromModal 被呼叫 - code:', code, 'name:', name, 'palletCapacity:', palletCapacity);
        
        var source = window.productSelectSource || 'inbound';
        console.log('📦 source:', source);
        
        // 從品項主檔取得完整資料
        var productData = (window.productMasterData || []).find(function(p) {
            return p.code === code || p.name === name;
        }) || {};
        
        console.log('📦 productData:', productData);
        console.log('📦 productData.palletCapacity:', productData.palletCapacity);
        
        // 🔧 修正：確保 palletCapacity 是數字
        var finalPalletCapacity = parseInt(palletCapacity) || parseInt(productData.palletCapacity) || 40;
        console.log('📦 finalPalletCapacity:', finalPalletCapacity);
        
        // 建立完整的 product 物件
        var product = {
            code: code,
            name: name,
            spec: spec,
            palletCapacity: finalPalletCapacity,
            shelfLife: shelfLife || productData.shelfLife || 24,
            weightType: productData.weightType || 'fixed',
            inboundType: productData.inboundType || 'Raw',
            unitWeight: productData.unitWeight || 0,
            category: productData.category || ''
        };
        
        if (source === 'container') {
            if (typeof window.fillContainerProductFromMaster === 'function') {
                window.fillContainerProductFromMaster(product);
            } else {
                // 降級處理：直接填入基本欄位
                console.log('📦 降級處理被執行, product:', product);
                var nameEl = document.getElementById('pre-name');
                var specEl = document.getElementById('pre-spec');
                var codeEl = document.getElementById('pre-product-code');
                if (nameEl) nameEl.value = name || '';
                if (specEl) specEl.value = spec || '';
                if (codeEl) codeEl.value = code || '';
                
                // 🔧 修正：降級處理也要設定每板件數
                var perPalletEl = document.getElementById('pre-per-pallet');
                var perPalletVarEl = document.getElementById('pre-per-pallet-var');
                var palletCapacityValue = parseInt(product.palletCapacity) || 40;
                if (perPalletEl) perPalletEl.value = palletCapacityValue;
                if (perPalletVarEl) perPalletVarEl.value = palletCapacityValue;
                console.log('📦 降級處理設定每板件數: ' + palletCapacityValue);
                
                // 觸發 checklist 和智能建議更新
                if (typeof updateContainerChecklist === 'function') {
                    updateContainerChecklist();
                }
                if (typeof calculateContainerSmartSuggest === 'function') {
                    calculateContainerSmartSuggest();
                }
            }
        } else {
            if (typeof window.fillProductFromMaster === 'function') {
                window.fillProductFromMaster(product);
            } else {
                // 降級處理：直接填入基本欄位
                var nameEl = document.getElementById('in-name');
                var specEl = document.getElementById('in-spec');
                var codeEl = document.getElementById('in-product-code');
                if (nameEl) nameEl.value = name || '';
                if (specEl) specEl.value = spec || '';
                if (codeEl) codeEl.value = code || '';
                if (typeof updateLivePreview === 'function') updateLivePreview();
                if (typeof updateInboundProgress === 'function') updateInboundProgress();
            }
            // 重要：觸發智能儲位建議
            if (typeof autoTriggerSmartSuggest === 'function') {
                autoTriggerSmartSuggest();
            }
        }
        
        // 關閉 modal - 支援兩種 modal ID
        if (typeof closeProductSelectModal === 'function') {
            closeProductSelectModal();
        } else {
            var modal = document.getElementById('modal-product-select') || document.getElementById('product-select-modal');
            if (modal) modal.classList.add('hidden');
        }
    };
    
    // ========== 9. 初始化 ==========
    
    function init() {
        initExpiryDateInput();
        updateWarehouseOptions();
        setTimeout(function() { if (typeof onWarehouseChange === 'function') onWarehouseChange(); }, 1000);
    }
    
    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); }
    else { setTimeout(init, 500); }
    
    console.log('✅ WMS V56.0 升級補丁載入完成');
    console.log('📋 更新內容：');
    console.log('   - 智能入庫流程優化');
    console.log('   - 貨櫃入庫作業優化');
    console.log('   - 品項主檔整合（自動判斷定重/不定重）');
    console.log('   - 公司別篩選外倉');
    console.log('   - 效期輸入優化');

    // ========== 9. 開發者工具函數 ==========
    
    // 清除單一 localStorage 項目
    window.clearLocalStorageItem = function(key) {
        if (!confirm('確定要清除「' + key + '」的資料嗎？')) return;
        
        localStorage.removeItem(key);
        showNotification('✅ 已清除 ' + key, 'success');
        refreshDevToolsStats();
    };
    
    // 清除所有本地資料
    window.clearAllLocalStorage = function() {
        if (!confirm('⚠️ 警告：這將清除所有本地資料！\n\n包括任務清單、波次資料、暫存設定等。\n\n確定要繼續嗎？')) return;
        if (!confirm('再次確認：這個操作無法復原！')) return;
        
        var wmsKeys = [];
        for (var i = 0; i < localStorage.length; i++) {
            var key = localStorage.key(i);
            if (key && key.indexOf('wms') !== -1) {
                wmsKeys.push(key);
            }
        }
        
        wmsKeys.forEach(function(key) {
            localStorage.removeItem(key);
        });
        
        showNotification('✅ 已清除所有本地 WMS 資料（' + wmsKeys.length + ' 項）', 'success');
        refreshDevToolsStats();
    };
    
    // 清除 Firebase 集合
    window.clearFirebaseCollection = async function(collectionName) {
        if (!window.db || !window.collection || !window.getDocs || !window.deleteDoc || !window.doc) {
            alert('Firebase 尚未初始化');
            return;
        }
        
        var displayNames = {
            'dispatchOrders': '調度工單',
            'waves': '波次資料',
            'pendingInbound': '待入庫工單',
            'inventoryLogs': '庫存異動紀錄',
            'pallets': '庫存資料'
        };
        
        var displayName = displayNames[collectionName] || collectionName;
        
        if (!confirm('⚠️ 警告：這將清除雲端「' + displayName + '」的所有資料！\n\n這個操作無法復原！\n\n確定要繼續嗎？')) return;
        if (!confirm('再次確認：確定要刪除雲端「' + displayName + '」嗎？')) return;
        
        try {
            var snapshot = await window.getDocs(window.collection(window.db, collectionName));
            var count = 0;
            
            for (var docSnap of snapshot.docs) {
                await window.deleteDoc(window.doc(window.db, collectionName, docSnap.id));
                count++;
            }
            
            showNotification('✅ 已清除 ' + displayName + '（' + count + ' 筆）', 'success');
            
            // 重新載入相關資料
            if (collectionName === 'pallets' && typeof window.loadInventory === 'function') {
                window.loadInventory();
            }
            
            refreshDevToolsStats();
        } catch (e) {
            alert('清除失敗：' + e.message);
        }
    };
    
    // 重新整理開發者工具統計
    window.refreshDevToolsStats = async function() {
        // 本地庫存
        var localInv = JSON.parse(localStorage.getItem('wms_inventory') || '[]');
        var localInvEl = document.getElementById('dev-local-inv-count');
        if (localInvEl) localInvEl.textContent = localInv.length;
        
        // 本地任務
        var localTasks = JSON.parse(localStorage.getItem('wms_dispatch_orders') || '[]');
        var localTaskEl = document.getElementById('dev-local-task-count');
        if (localTaskEl) localTaskEl.textContent = localTasks.length;
        
        // 雲端統計
        if (window.db && window.collection && window.getDocs) {
            try {
                var palletSnap = await window.getDocs(window.collection(window.db, 'pallets'));
                var cloudInvEl = document.getElementById('dev-cloud-inv-count');
                if (cloudInvEl) cloudInvEl.textContent = palletSnap.size;
                
                var taskSnap = await window.getDocs(window.collection(window.db, 'dispatchOrders'));
                var cloudTaskEl = document.getElementById('dev-cloud-task-count');
                if (cloudTaskEl) cloudTaskEl.textContent = taskSnap.size;
            } catch (e) {
                var cloudInvEl = document.getElementById('dev-cloud-inv-count');
                var cloudTaskEl = document.getElementById('dev-cloud-task-count');
                if (cloudInvEl) cloudInvEl.textContent = '錯誤';
                if (cloudTaskEl) cloudTaskEl.textContent = '錯誤';
            }
        } else {
            var cloudInvEl = document.getElementById('dev-cloud-inv-count');
            var cloudTaskEl = document.getElementById('dev-cloud-task-count');
            if (cloudInvEl) cloudInvEl.textContent = 'N/A';
            if (cloudTaskEl) cloudTaskEl.textContent = 'N/A';
        }
    };

})();


// ========== 資料格式遷移（一次性，限管理員）==========
// 把既有資料統一成目前的格式：
//   pallets / externalStock / inboundOrders：效期統一為 'YYYY-MM-DD' 並同時寫入 expiryDate、expDate；數量字串轉數字
//   inventoryLogs：timestamp 統一為 ISO 字串（現場掃描舊記錄是 Timestamp，日期查詢查不到）
// dryRun = true 只統計不寫入
window.migrateDataFormats = async function(dryRun) {
    if (!window.currentUser || window.currentUser.role !== 'admin') {
        throw new Error('只有管理員可以執行資料遷移');
    }
    var report = {};
    var pending = [];

    function sameValue(a, b) {
        return JSON.stringify(a === undefined ? null : a) === JSON.stringify(b === undefined ? null : b);
    }

    for (var coll of ['pallets', 'externalStock', 'inboundOrders']) {
        var snap = await window.db.collection(coll).get();
        var changed = 0;
        snap.forEach(function(d) {
            var orig = d.data();
            var norm = window.normalizeStockRecord(Object.assign({}, orig));
            var update = {};
            ['expiryDate', 'expDate', 'quantity'].forEach(function(f) {
                if (norm[f] !== undefined && !sameValue(orig[f], norm[f])) update[f] = norm[f];
            });
            if (Object.keys(update).length > 0) {
                changed++;
                pending.push({ ref: d.ref, data: update });
            }
        });
        report[coll] = { total: snap.size, changed: changed };
    }

    var logSnap = await window.db.collection('inventoryLogs').get();
    var logChanged = 0;
    logSnap.forEach(function(d) {
        var ts = d.data().timestamp;
        if (ts && typeof ts !== 'string') {
            var date = typeof ts.toDate === 'function' ? ts.toDate() : new Date(ts);
            if (!isNaN(date.getTime())) {
                logChanged++;
                pending.push({ ref: d.ref, data: { timestamp: date.toISOString() } });
            }
        }
    });
    report.inventoryLogs = { total: logSnap.size, changed: logChanged };

    if (!dryRun) {
        for (var i = 0; i < pending.length; i += 400) {
            var batch = window.db.batch();
            pending.slice(i, i + 400).forEach(function(p) { batch.update(p.ref, p.data); });
            await batch.commit();
        }
    }
    report.dryRun = !!dryRun;
    report.totalChanged = pending.length;
    return report;
};

window.runDataMigrationUI = async function(dryRun) {
    var out = document.getElementById('dev-migrate-result');
    if (!dryRun && !confirm('確定要把既有資料轉成統一格式？\n\n建議先按「預覽」確認筆數，並先做一次備份。')) return;
    if (out) out.innerHTML = '<span class="text-yellow-400"><i class="fa-solid fa-spinner fa-spin mr-1"></i>處理中...</span>';
    try {
        var r = await window.migrateDataFormats(dryRun);
        var names = { pallets: '庫存棧板', externalStock: '外倉庫存', inboundOrders: '入庫單', inventoryLogs: '異動記錄' };
        var html = '<div class="text-white font-bold mb-1">' + (r.dryRun ? '預覽（尚未寫入）' : '✅ 已完成') + '</div>';
        Object.keys(names).forEach(function(k) {
            html += '<div>' + names[k] + '：' + r[k].changed + ' / ' + r[k].total + ' 筆需要轉換</div>';
        });
        if (out) out.innerHTML = html;
    } catch (e) {
        console.error('資料遷移失敗:', e);
        if (out) out.innerHTML = '<span class="text-red-400">❌ ' + e.message + '</span>';
    }
};
